const {
  app, BrowserWindow, ipcMain, screen, desktopCapturer,
  globalShortcut, systemPreferences, shell, protocol, net, dialog, nativeImage, Tray, Menu, clipboard,
} = require('electron');
const path = require('path');
const fs = require('fs');
const { spawn } = require('child_process');
const Anthropic = require('@anthropic-ai/sdk');
const { pathToFileURL } = require('url');
const { startSnipHook, stopSnipHook, shutdownSnipHook, startShield, stopShield, foregroundWindow, foregroundPid, restoreForeground, forceForeground } = require('./winhook');
const { isAvailable: winCaptureAvailable, captureRegionNative } = require('./wincapture');
const { startComboHook, stopComboHook, shutdownComboHook } = require('./winkeyhook');
const { setMouseButtons, stopMouseButtons, shutdownMouseButtons } = require('./winmousehook');
const hoverDict = require('./hover-dict');

const IS_WIN = process.platform === 'win32';

// Where "point at a word" can run at all — defined in capabilities.js because the renderer's mode
// strip has to draw its chip by exactly the same rule this file filters the shortcut list by, and a
// second platform test over there is how the two would eventually disagree. macOS joined Windows on
// 2026-08-15 when visionocr.swift learned the ";boxes" dialect.
const { HOVER_CAPABLE, THAI_SOURCE, PAIR_LOCK } = require('./capabilities');
// Generated by `npx electron scripts/gen-icons.js` (re-run it if the mark changes). Without an explicit icon every window —
// and the taskbar entry — falls back to Electron's own logo, which is what an unbranded dev build
// looks like. electron-builder picks the same file up from buildResources for packaged builds.
// The Gloss mark, rendered from the website's own favicon by `npx electron scripts/gen-icons.js`.
// Windows take the full-size file; the tray takes the 64px one it downscales to 16.
const APP_ICON = path.join(__dirname, 'build', 'icon.png');
// The tray gets its own file: same mark, colours swapped, so it carries contrast on a taskbar of any
// shade instead of dissolving into a dark one.
const TRAY_ICON = path.join(__dirname, 'build', 'tray.png');
// Same mark, smaller file. It needs no contrast swap: unlike the → it replaced, this one fills its
// tile with a white glyph and cyan brackets, so it reads on a dark shelf and on a light one.

let mainWindow = null;
let learnWindow = null;
let snipWindows = [];
let snipFreeze = null;   // (freeze-frame path — inert; Windows uses the click-through hook drag instead)
let snipStarting = false; // (inert)
let snipPointActive = false; // a second shortcut press acts as the shutter (macOS point style)
let winSnipArmed = false;
let winSnipPrevFg = null;    // who owned the foreground when the snip armed — handed back on disarm    // Windows: the snip hook is armed, waiting for/handling a left-drag
// true = snip drags over a MOUSE-CAPTURING overlay (doesn't leak the drag to the app underneath).
// KEEP IT false. Re-tested 2026-07-19 with the overlay background already `transparent` (the suspected
// real culprit): the video underneath STILL freezes hard the moment a capturing overlay covers it —
// so it's the capturing window itself, not the old rgba fill. The click-through path stays, and its
// known cost stays with it: uiohook is a listener and cannot swallow events, so the drag reaches the
// app below (selects its text / clicks into the game). Fixing THAT needs a native event-suppressing
// hook (WH_MOUSE_LL returning 1) — not something uiohook-napi can do.
const WIN_CAPTURING_SNIP = false;

let ocrWindow = null;
let ocrSeq = 0;
const ocrPending = new Map();
let history = [];
let vocab = [];

const MIN_CONFIDENCE = 60; // tesseract 0-100; below this the read is usually noise

// The confidence gate, asked as one question so all three read paths ask it the same way.
//
// An ARBITRATED read is exempt. When withSecondOpinion swaps the native read for tesseract's, the
// dictionary has already judged the two — and it judged the TEXT, which is the thing the gate is a
// proxy for. Re-asking tesseract's own score after that is not a second check, it is a veto by the
// weaker judge: measured on this app's own case, a correct read of stylised lettering scores 37-50
// while the native engine hands back a flat 90 for any non-empty read at all. jek hit the real
// version on 2026-08-31 — "bulldozers" alone read wrong by Windows OCR, read RIGHT by tesseract,
// and then thrown away as "Blurry — try a bigger box" for the score of the read that won. The same
// word inside its sentence sailed through, because there the native read kept enough known words to
// win the arbitration and carry its fake 90 with it.
function lowConfidence(ocr) {
  return !ocr.arbitrated && ocr.confidence < MIN_CONFIDENCE;
}
const MAX_HISTORY = 300; // hard ceiling for the on-disk file; the live cap is settings.maxHistory
// Reading the same line twice is one entry, not two. The list is a place to go back to something,
// and a screen of "เสน่ห์… / Enchanting… now" four times over (jek, 2026-09-08) buries the four
// other things read in the same minute. A repeat moves its row back to the top with a fresh
// timestamp — what a recent-searches list anywhere does.
//
// Keyed on the source text AND the kind: pointing at a word and snipping the sentence that contains
// it are different acts with different cards, and collapsing those two would delete one of them.
function rememberHistory(payload) {
  const key = payload && payload.en;
  if (key) {
    const kind = (h) => (h.live ? 1 : 0) + (h.typed ? 2 : 0) + (h.point ? 4 : 0);
    const mine = kind(payload);
    const at = history.findIndex((h) => h && h.en === key && kind(h) === mine);
    if (at >= 0) history.splice(at, 1);
  }
  history.unshift(payload);
  if (history.length > historyCap()) history.length = historyCap();
}

const historyCap = () => Math.max(20, Math.min(2000, Number(settings.maxHistory) || MAX_HISTORY));
// 500 was a data-loss trap: vocab is SRS study data, and at the cap the OLDEST saved word — the one
// you've reviewed longest — dropped silently. 5000 words is ~500KB of JSON, i.e. free, and past any
// realistic collection. Raised 2026-07-22; see the guard in vocab:add for what happens at the ceiling.
const MAX_VOCAB = 5000;

// Rebindable global shortcuts. Data-driven so the Settings page can list + re-key them: each action
// has a stable id, a label, a default accelerator, and its handler. The live accelerator is
// settings.shortcuts[id] || def — see accelFor()/registerShortcuts().
const SHORTCUT_ACTIONS = [
  // The three you reach for constantly are TWO keys, and the same two on both platforms. ⌘⇧S is a
  // three-finger claw in the bottom-left corner — the corner your left hand is already using for
  // WASD — and asking a player to make that shape mid-fight is asking them to stop playing.
  //
  // Alt (⌥ on mac) rather than the alternatives, and the reasoning is per-platform:
  //   mac      ⌘+letter belongs to every app on the machine — ⌘S save, ⌘T new tab, ⌘M MINIMISE. A
  //            global grab steals it system-wide. ⌥+letter only costs the odd glyph (ß † µ).
  //   Windows  Win+letter is reserved BY Windows and the collisions are exact: Win+S opens Search,
  //            Win+T cycles the taskbar, Win+M minimises everything. Ctrl+letter is every app's save
  //            and new-tab. Alt+letter is the one family left, and the overlay most gaming PCs run —
  //            GeForce Experience — puts its bindings on Alt+F-keys (Alt+Z, Alt+F9, Alt+F10), not on
  //            Alt+letters, so these three sit in the gap. Alt also survives a fullscreen game, where
  //            a plain letter key belongs to the game.
  // Letters chosen to be guessable without the manual: S-nip, T-ype, M-ic.
  // Snip is the exception to the Alt+letter rule below, and deliberately: it is the only action with
  // a HOLD style ('hold' snipStyle — keep it down, move, let go), and a hold only works on a trigger
  // made of modifiers. A letter in the trigger would be typed INTO the game for the whole drag —
  // Alt+S held over a shooter walks you backwards, since the hook never swallows keys (winkeyhook.js).
  // ⌃⌥ also costs the game nothing on its own, which a letter always does. Rebindable like the rest;
  // bind a letter to it and the style falls back to 'drag' rather than pretending to hold (see
  // effectiveSnipStyle).
  { id: 'snip', label: 'Snip & translate', def: 'Control+Alt', defPress: 'Alt+S', run: () => doSnipStart() },
  { id: 'type', label: 'Type to translate', def: 'Alt+T', run: () => doTypeFocus() },
  // Was `mac: true` — dropped from Windows because toggleSpeak could only answer "macOS-only" there,
  // and a shortcut that takes Ctrl+Shift+M away from the game for a dead feature is worse than no
  // shortcut. native/winspeak.ps1 gives Windows a real recogniser, so the row is on both now.
  { id: 'speak', label: 'Speak to translate', def: 'Alt+M', run: () => toggleSpeak() }, // M = mic
  // CC was the one MODE with no key — the only way in or out was the pill's own button, which is the
  // thing you can't reach in the middle of a fight, and the reason to turn subtitles off is usually
  // that something just started happening (jek, 2026-08-09). Same toggle the button runs, so the two
  // can never disagree about what "on" means: first press picks the strip and starts, second stops.
  // C for captions, in the same Alt+letter family as the other three.
  { id: 'live', label: 'Live captions (CC)', def: 'Alt+C', run: () => doLiveToggle(), mode: true },
  { id: 'clear', label: 'Clear card', def: 'CommandOrControl+Shift+X', run: () => doClear() },
  { id: 'lock', label: 'Lock overlay', def: 'CommandOrControl+Shift+L', run: () => sendMain('lock:toggle'), mode: true },
  { id: 'cardUp', label: 'Card bigger', def: 'CommandOrControl+Shift+Up', run: () => doFontStep(+2) },
  { id: 'cardDown', label: 'Card smaller', def: 'CommandOrControl+Shift+Down', run: () => doFontStep(-2) },
  // Multi-monitor: the overlay window is one display's work area, so this is the only way to get the
  // pill onto the screen the game is actually on without a mouse. No-op on a single display.
  { id: 'nextDisplay', label: 'Move to next monitor', def: 'CommandOrControl+Shift+D', run: () => cycleDisplay() },
  // Its own key, not a snip style, because it is not a snip: no box, no card, no translation call —
  // point at a word and a bubble names it. Alt+G because it sits with the other Alt+letter actions
  // and G is free of both the Windows and the GeForce bindings the block above catalogues.
  { id: 'hover', label: 'Point at a word', def: 'Alt+G', run: () => toggleHoverMode(), boxesOcr: true, mode: true },
  // The other half of pointing. Pointing answers "what is that word"; this answers "keep it" — and
  // until now there was no key for it at all, so the only way into the collection was to leave the
  // game, find the word again on a card in the pill and click its ★ (jek, 2026-08-12: "มันไม่มี keyword
  // ในการ save คำๆนั้นที่ชี้"). Three actions for something you noticed in one.
  // `when` is why this may exist without costing the game a key: it binds only while the mode is
  // running and is released the moment it stops. Registering it always would take Alt+K away from a
  // shooter for an action that can do nothing 99% of the time — the exact mistake the speak row made
  // on Windows (see its note above). K = Keep, and it stays in the Alt+letter family this block chose.
  { id: 'hoverSave', label: 'Keep the word you point at', def: 'Alt+K',
    run: () => saveHoverWord(), boxesOcr: true, when: () => hoverActive },
  // Filtered once, here, so registerShortcuts() and shortcutList() can never disagree about which
  // actions exist on this platform.
].filter((a) => !a.mac || process.platform === 'darwin')
  // A row for an action that cannot run is worse than no row: it takes a key off the game and answers
  // with an apology. Only where an OCR engine hands back per-character geometry (see recognizeBoxes).
  .filter((a) => !a.boxesOcr || HOVER_CAPABLE);

let registeredAccels = []; // exactly what registerShortcuts() put in — unregistered precisely (never
                           // globalShortcut.unregisterAll(), which would also drop the snip-only Escape).

// Where a modifier-only trigger can actually be run: it needs a low-level keyboard listener, because
// the OS hotkey API has no concept of one. macOS = the mousehook event tap, Windows = winkeyhook's
// WH_KEYBOARD_LL. Linux has neither, so it stays on press-style triggers.
const HOLD_CAPABLE = process.platform === 'darwin' || process.platform === 'win32';

function accelFor(action) {
  const custom = settings.shortcuts && settings.shortcuts[action.id];
  const accel = (custom && custom.trim()) || action.def;
  // This used to force a modifier-only trigger back to the default off macOS, on the grounds that only
  // the mac event tap could run one. Windows has had winkeyhook since the port, and as of the
  // single-trigger change the DEFAULT snip binding is itself modifier-only — so on Windows the guard
  // would have been rewriting the very thing it was meant to rescue.
  //
  // It still matters where there is genuinely no hook (Linux): globalShortcut refuses a modifier-only
  // accelerator, correctly, so leaving one in place there means the action has NO trigger at all and
  // nothing says why. Fall back to the press-style default instead — a different key beats no key.
  if (!HOLD_CAPABLE && isHoldAccel(accel)) return action.defPress || action.def;
  // Same rescue, for the same reason, one platform narrower: a mouse button is run by winmousehook
  // and by nothing else, so off Windows the binding is a trigger that cannot fire. A settings.json
  // carried between machines is the way that happens.
  if (!MOUSE_CAPABLE && isMouseAccel(accel)) return action.defPress || action.def;
  return accel;
}

// ---------- Mouse-button triggers ----------------------------------------------------------------
// 'Mouse4' / 'Mouse5' are OUR spelling, not Electron's — there isn't one. No accelerator syntax at any
// OS can name a mouse button, which is why binding one needs a device-level hook (winmousehook.js) and
// why these strings never go near globalShortcut.register: it would throw, and the row would report
// "already used by another app" for a trigger nothing else owns.
//
// Side buttons only. Left/right/middle are the buttons the game is playing with, and a global binding
// on one of those fires every time you shoot — see the header of winmousehook.js.
const MOUSE_ACCELS = { Mouse4: 4, Mouse5: 5 };
const MOUSE_CAPABLE = process.platform === 'win32';

function isMouseAccel(accel) {
  return Object.prototype.hasOwnProperty.call(MOUSE_ACCELS, String(accel || '').trim());
}

// ---------- Hold-style triggers -----------------------------------------------------------------
// ONE trigger, and Settings > "Select by" says what it does — that is the whole model.
//
// There used to be two ways to snip: a rebindable shortcut (Alt+S) and a hardcoded ⌃⌥ hold-drag,
// both ending at the same snip. Two keys for one function, and nothing on screen said which you were
// meant to press. An earlier pass tried to merge them by making the STYLE follow the key you bound —
// modifier-only means hold, a letter means press — but that only moved the confusion: the way to
// change how snipping feels was to change which keys you press, which is not where anyone looks.
// Now the style is a normal setting and the key is just a key. (jek, 2026-08-07)
//
// What the platform can deliver still differs, and that is what the rest of this section is about:
// only the OS can register a PRESS (globalShortcut refuses modifier-only accelerators, correctly —
// there is no keystroke to fire on), and only a low-level listener can see a RELEASE. So a
// modifier-only trigger is driven entirely by the hook (both styles — 'hold' uses its down/up edges,
// 'drag'/'point' just take the down edge as the press), while a trigger with a letter in it is
// registered with the OS and can only ever be pressed.
const ACCEL_MODIFIERS = new Set(['CommandOrControl', 'Command', 'Cmd', 'Control', 'Ctrl',
  'Alt', 'Option', 'AltGr', 'Shift', 'Super', 'Meta']);

function isHoldAccel(accel) {
  const parts = String(accel || '').split('+').map((p) => p.trim()).filter(Boolean);
  return parts.length >= 2 && parts.every((p) => ACCEL_MODIFIERS.has(p));
}

// Electron's spelling → the names native/mousehook understands. CommandOrControl is Control here
// because this is about the physical ⌃ key under the hand, not about the platform's "primary"
// modifier — the same reading Windows' winkeyhook takes.
function holdModsFor(accel) {
  const map = { CommandOrControl: 'control', Control: 'control', Ctrl: 'control',
    Command: 'command', Cmd: 'command', Meta: 'command', Super: 'command',
    Alt: 'alternate', Option: 'alternate', AltGr: 'alternate', Shift: 'shift' };
  return String(accel || '').split('+').map((p) => map[p.trim()]).filter(Boolean).join(',');
}

// The modifiers the hook has to watch, or '' when the snip trigger is a press-style shortcut the OS
// can deliver on its own and the hook should stay off. NOT a question about the snip STYLE any more:
// a modifier-only trigger is the hook's job in every style, because the OS will not report it at all.
function snipHoldMods() {
  const snip = SHORTCUT_ACTIONS.find((a) => a.id === 'snip');
  const accel = snip ? accelFor(snip) : '';
  return isHoldAccel(accel) ? holdModsFor(accel) : '';
}

// The snip style actually in force, which is the saved one except where it cannot be honoured.
// 'hold' needs a release event, and a release only exists for a modifier-only trigger on a platform
// with a hook — bind a letter (or run on Linux) and holding is physically not on offer. Degrade to
// 'drag' rather than silently doing nothing: the user still gets a snip from the key they pressed.
// Everything that acts on the style reads it from here, so there is one answer, not five.
function effectiveSnipStyle() {
  const style = settings.snipStyle || DEFAULT_SETTINGS.snipStyle;
  if (style !== 'hold') return style;
  return (HOLD_CAPABLE && snipHoldMods()) ? 'hold' : 'drag';
}

// (Re)register every global shortcut from current settings. Returns [{id, accel}] that failed to bind
// (invalid combo or already taken by another app). Safe to call any time settings change.
function registerShortcuts() {
  for (const a of registeredAccels) { try { globalShortcut.unregister(a); } catch { /* ignore */ } }
  registeredAccels = [];
  const failed = [];
  // Rebuilt from scratch on every pass, exactly like registeredAccels: whatever is not in this object
  // when setMouseButtons runs is unbound, so a row re-keyed off its side button releases it.
  const mouseMap = {};
  for (const action of SHORTCUT_ACTIONS) {
    const accel = accelFor(action);
    // Hold-style: no keystroke to bind, the event tap carries it. Not a failure — don't report it as
    // one, or the user gets "Hotkey in use by another app" for a trigger that is working fine.
    if (isHoldAccel(accel)) continue;
    // Same deal for a side button: the OS has no way to register it, winmousehook watches for it.
    if (isMouseAccel(accel)) { mouseMap[MOUSE_ACCELS[accel]] = action.run; continue; }
    // An action that only means something inside a MODE (see hoverSave) holds its key only while that
    // mode runs — start/stopHoverMode call back through here, so the binding follows the state.
    // It is still PROBED while idle: Settings must be able to tell you the combo you just typed is
    // owned by another app, and it can only find that out by asking the OS. Bound and released inside
    // this call, so the game never loses the key for it.
    if (action.when && !action.when()) {
      let free = false;
      try { free = globalShortcut.register(accel, () => {}); } catch { free = false; }
      if (free) { try { globalShortcut.unregister(accel); } catch { /* ignore */ } }
      else failed.push({ id: action.id, accel });
      continue;
    }
    let ok = false;
    try { ok = globalShortcut.register(accel, action.run); } catch { ok = false; }
    if (ok) registeredAccels.push(accel);
    else {
      console.warn(`shortcut: "${accel}" (${action.id}) could not be registered — another app owns it`);
      failed.push({ id: action.id, accel });
    }
  }
  // Nothing bound to a side button → an empty map, which uninstalls the hook rather than idling it.
  if (MOUSE_CAPABLE) setMouseButtons(mouseMap);
  return failed;
}

function shortcutList() {
  // `hold` lets the Settings row and the pill's resting hint say "hold" instead of "press" without
  // each of them re-deriving the rule from the accelerator string.
  return SHORTCUT_ACTIONS.map((a) => ({ id: a.id, label: a.label, def: a.def, accel: accelFor(a),
    hold: isHoldAccel(accelFor(a)),
    // Bound only while its mode is running (`when` in SHORTCUT_ACTIONS — hoverSave is the one). Said
    // out loud because anything auditing "is every shortcut registered?" otherwise reads a key that
    // is CORRECTLY unbound as a failure, and a suite that is red for a non-bug teaches you to stop
    // reading it — which is exactly how a real one hid here for a week (see NEXT.md).
    modeOnly: !!a.when,
    // A MODE, not a one-shot: its key switches something ON and leaves it on until you switch it off
    // (jek, 2026-08-09 — "CC Subtitle เนี่ยจะเป็นการเปิดปิด ... ตัวชี้เมาส์ ... ก็เป็นเปิดปิดเหมือนกัน
    // ไม่ใช่ keyword"). The row draws a real switch for these rather than a key chip alone, which
    // reads as "press this and one thing happens".
    mode: !!a.mode }));
}

// While the Settings page is capturing a new combo, drop the OS-level bindings so pressing the current
// snip/lock/etc. combo just gets recorded instead of ALSO firing the action. registeredAccels is kept,
// so resume simply re-registers the current set.
function suspendShortcuts() {
  for (const a of registeredAccels) { try { globalShortcut.unregister(a); } catch { /* ignore */ } }
  // The side buttons have to go quiet for the same reason the keys do: while Settings is capturing,
  // clicking the button you are trying to re-key must record it, not fire a snip behind the panel.
  // resumeShortcuts() → registerShortcuts() puts the map back.
  if (MOUSE_CAPABLE) stopMouseButtons();
}
function resumeShortcuts() {
  registerShortcuts();
}

// ---------- Escape, single owner ----------
// Two different snip paths used to register 'Escape' independently (showSnipWindows and
// startWinSnip). Electron lets the second registration clobber the first silently, so opening CC
// while a Windows snip was armed left the mouse hook swallowing every click with no way to cancel.
// One dispatcher owns the key instead, and syncEscape() decides purely from current state.
let escapeArmed = false;

function onEscapePressed() {
  if (winSnipArmed) { cancelWinSnip(); return; } // armed hook first — it's the one that eats clicks
  if (externSession) { abortExternSession(); return; } // a ⌃⌥ hold-drag in flight
  // Before the snip cases: point-at-a-word shows no UI you can click, so Esc is its only way out.
  if (hoverActive) { stopHoverMode(); return; }
  if (snipping) closeSnipWindows();
}

function syncEscape() {
  // externSession counts: a hold-drag sets NEITHER of the other two flags, so without it Escape was
  // never even registered during one. If the matching release went missing (⌃⌥ released while
  // another app had focus, a Space/display switch mid-drag) the session stayed open forever — every
  // later hold-drag bounced off the guard in mouseHookDown, and the pill stayed hidden from capture
  // with no way back short of relaunching. Windows had cancelWinSnip as its way out; mac had none.
  // hoverActive too: Esc is the only way out of a mode that shows no UI of its own to click.
  const want = winSnipArmed || snipping || !!externSession || hoverActive;
  if (want === escapeArmed) return;
  if (want) {
    try { escapeArmed = globalShortcut.register('Escape', onEscapePressed); } catch { escapeArmed = false; }
  } else {
    try { globalShortcut.unregister('Escape'); } catch { /* ignore */ }
    escapeArmed = false;
  }
}

// ---------- settings (survive a quit) ----------

const DEFAULT_SETTINGS = {
  apiKey: '',         // YOUR OWN Claude key. Set = unlimited, billed to you, never touches our server
  licenceKey: '',     // Gloss Pro licence; AI runs through our proxy on a one-time bundle of reads
  deviceId: '',       // random id minted on first run — identifies the free trial's 100 reads
  cardSize: 14,       // base font size of the card, in px — everything scales off it
  showEnglish: true,  // show the OCR'd source text above the translation
  // WHAT THE ANSWER CARRIES, asked once and honoured everywhere it is answered — the Alt+G bubble, the
  // Type bar's quick look and the snip card all read these four. Before them, each surface decided for
  // itself what a word was worth saying, so the same word answered differently depending on how you
  // asked (jek, 2026-08-12: "ข้อมูลอะไรบ้าง … ต้องตั้งค่าใน setting ได้ … ทั้งฟังก์ชัน Alt+G หรือ
  // Translation Bar จะโชว์ข้อมูลตามที่เรา setting").
  //
  // A surface honours the ones it HAS and ignores the rest — a Type peek has no reading to hide, a
  // card has no second dictionary sense. That is a gap in the data, not a switch that does nothing:
  // see the matrix above each use site.
  showPos: true,        // the coloured word-class chip (N. / V. / Adj.)
  // The dictionary's English answer, kept BESIDE the reader's own language rather than replaced by it.
  // On for the reader who is here to learn the source language; off for the one who only wants to know
  // what the line said, who was reading the same fact twice.
  showEnMeaning: true,
  // showReading defaults OFF, and that is the point of it: the bubble and the peek were cut down to
  // one meaning and no reading BY REQUEST (jek, 2026-08-09: "มันดูใหญ่มาก แล้วก็รู้สึกว่ามันให้ข้อมูลเยอะ
  // เกินไป"). It gives that back to whoever wants it without putting it back in front of everyone.
  showReading: false,   // how the word reads — furigana / pronunciation
  // showSenses came back ON (jek, 2026-08-13, asking what a word that is both a noun and a verb does
  // in the bar — `party` answered "งานสังสรรค์ N." and the verb was fetched but never drawn). It is
  // not the same trade as showReading: fillSenseChips is SILENT below two senses, so the row costs
  // nothing on the words that aren't ambiguous, and off-by-default was wrong for the only words it
  // has anything to say about.
  showSenses: true,     // the other meanings, beside the first
  sourceLang: 'eng',  // tesseract lang code of the game text: eng|jpn|chi_sim|kor
  targetLang: 'th',   // translation target (Google/Claude language code); replaced on a FIRST run by
                      // the OS language — see firstRunTargetLang(). 'th' stays the written default
                      // because that is the one a settings file from before this change carries.

  // How loud the 🔊 pronounce button is, 0-100. 100 is what an unset utterance already does, so this
  // starts as a no-op and only ever goes DOWN — the Web Speech volume caps at 1 and there is nothing
  // above it (jek, 2026-08-09: asked for up or down; up does not exist, and Windows' per-app volume
  // mixer is the only louder there is). See setVolume in renderer/shared/tts.js.
  speakVolume: 100,
  slideSpeed: 38,     // marquee scroll speed in px/sec — ONE speed for every sliding text in the app (lower = slower/easier to read)
  holdSec: 7,         // seconds the translation card auto-closes after (it's a glance over live gameplay, not a page to read). Pauses while the cursor is over the card. 0 = never closes on its own (set via Settings > Card stays)
  // HOW a snip is driven, and the only place that choice is made. All three run off the one snip
  // trigger — there is no second gesture with a key of its own any more.
  //   'hold'  = keep the trigger held, move over the text, let go. The casual one: no aiming, no
  //             second press, and nothing to cancel. Needs a modifier-only trigger (see snipHoldMods).
  //   'drag'  = tap the trigger, then mouse-drag a box. Precise, both hands free.
  //   'point' = tap to anchor at the cursor, move to stretch, tap again to capture. NO LONGER OFFERED
  //             (jek, 2026-08-09): it held the label "Normally" while being the one gesture he never
  //             called normal, and its selling point — needing no low-level hook — is shared by
  //             'drag', which selects on our own overlay just the same. Still honoured if a settings
  //             file carries it, so an old install keeps working until the migration below moves it.
  // ('click' was removed — dead on Windows' click-through overlay, only a coarse 'point' on mac.)
  snipStyle: 'hold',
  hideFromCapture: false, // ON = pill/card won't appear in screen recordings/screenshots (streaming)
  // Windows only. OFF (default): the drag overlay is excluded from every screen capture, because a
  // transparent window lands in a GDI BitBlt as a solid black rectangle over the very text being read
  // — the live preview would OCR that rectangle. ON: the snip switches to the frozen-frame path
  // (startFrozenSnip), which captures the screen BEFORE the overlay appears and drags over that still
  // image, so nothing needs excluding and a screen recorder sees the box.
  // ON by default since 2026-09-08 (jek): "it should be visible when you use it, and visible when you
  // record — otherwise how does anyone watching know the app is being used." The old default optimised
  // for the one second of the drag and paid for it everywhere else: every clip, every screen share and
  // every bug report someone films showed the game with nothing happening over it, because the box
  // they were drawing was excluded from the capture. A tool nobody can film is a tool nobody can show
  // anyone, and this one is sold by showing it.
  // The trade is real and does not go away: on the frozen path the picture stops moving while you
  // drag, so a video or a game appears to pause for that second. That is what the switch is for —
  // it is now "turn the freeze off and accept that recordings miss the box", which is the rarer want.
  recordableSnip: true,
  dock: 'bc',         // which snap spot the pill vacuums to: 9 rows {b,1,q,2,m,3,u,4,t} x 5 columns {l,w,c,e,r} — default bottom-centre
  autoHidePanel: true, // ON = the History/Settings panel auto-closes a few seconds after the cursor leaves it
  // How present the pill is while you play. 'visible' = the pill as it has always been. 'dim' = its
  // label/hint/buttons sit back at 45% until you hover (the STATUS DOT never fades — that's what tells
  // you a translation landed). 'ghost' = it rests tucked at the screen edge as a 26px tab and reveals
  // itself for a translation/status exactly the way a tucked pill already does. 'ghostdim' = both at
  // once: it tucks like 'ghost', and on the way back out it is faded like 'dim' rather than arriving
  // at full strength — for the player who wants it gone AND wants its return to be quiet.
  // Default is deliberately 'visible': the previous auto-hiding pill was removed BY REQUEST because a
  // pill that hides itself without being asked is a pill you can't find (see maybeIdle in index.js).
  pillStyle: 'visible',
  // ON = after a card fades, the word it was about stays parked in the pill's right-hand slot, tinted,
  // instead of the slot going straight back to the shortcut hint.
  //
  // Default flipped to ON (jek, 2026-08-09: "ปกติมันควรจะเปิดไว้สิ"). It shipped OFF on the grounds that
  // the slot is what teaches a new user the shortcut, and a parked word squatting there means they
  // never see it. "Squatting" was the wrong word for what the code does: the park is timed, not
  // permanent — text that fits clears after VOCAB_HOLD_MS (12s) and text that overflows after its two
  // slides, and either way the slot goes back to the shortcut hint on its own. So the hint is delayed,
  // not replaced, and the recall rep is the reason anyone snips the same word twice.
  pillKeyword: true,
  // ON = the overlay re-homes itself to whichever monitor you snip on, so the pill is never stranded
  // on the other screen from the game. No-op on a single display, which is why it defaults ON.
  followMonitor: true,
  // Which monitor the pill was last parked on, so it comes back where you left it instead of on the
  // primary display every launch. `{ id, x, y }` or null. No Settings row and none is wanted: it is
  // written by MOVING the pill (⌘⇧D / a snip with followMonitor on), which is a more honest way to
  // say where it goes than a dropdown listing monitors by number. See rememberedDisplay().
  //
  // This is what made "keep the pill off the game screen" only half-doable: turning followMonitor
  // off stopped the pill CHASING the game, but createMainWindow() still opened on the primary
  // display, which on jek's desk is the screen the game is on — so every launch put it back and
  // ⌘⇧D had to be pressed again (2026-08-31).
  pillDisplay: null,
  openAtLogin: false,  // start Gloss with the OS session (Settings > System). Off by default — an overlay that appears on a machine you didn't launch it on is a surprise, so it's opt-in. Only takes effect in a packaged build; see applyLoginItem().
  uiLang: 'auto',      // app-CHROME language (menus/settings/tooltips): 'auto' follows the OS locale, or 'en'|'th'. The translated CONTENT is set by targetLang, separately.
  // ON = every snip builds the full AI card, the way it worked before 2026-08-06. OFF = a snip is a
  // free Google translation and the AI card is one tap away on the card itself. Off by default: most
  // lines in a game are read once and forgotten, and paying for a learner's card on all of them
  // spends the bought bundle on reads nobody wanted.
  aiCards: false,
  // A line written in more than one alphabet is the one thing local OCR structurally cannot read:
  // every engine here is configured for a single language (see looksMixed). ON = those lines, and
  // only those, are read by Claude from the picture instead. On by default, because the alternative
  // is a read that is silently half-wrong and says nothing about it — but it does spend units, so it
  // is a switch rather than a fact of life.
  aiMixedRead: true,
  // Keep the word you are pointing at without touching the keyboard: hold the cursor on it and it is
  // collected. OFF by default on purpose — a collection that fills itself with words nobody asked for
  // is worse than one that needs a key press, and the key (⌥K) is unchanged either way.
  hoverDwellSave: false,
  shortcuts: {},       // per-action accelerator overrides { [actionId]: 'CommandOrControl+Shift+S' }; absent = default
  // CC (live subtitle) mode:
  // The strip CC watches, in absolute screen coords. Remembered ACROSS RUNS, not just across a toggle:
  // the subtitles in a game are where they are, and answering "where" once per game was the whole point
  // of splitting picking from switching on. It was module-scope only, so every relaunch asked again
  // (jek, 2026-08-09: "ฉันต้องปรับใหม่ตลอดเลยเวลาเปิดปิด"). Validated against the live displays before
  // it is trusted — see liveRegionUsable.
  ccRegion: null,      // { x, y, width, height } or null = never picked
  ccIntervalMs: 1200,  // gap between subtitle reads; higher = lighter on the CPU (matters on Windows/tesseract)
  // ccShowOriginal / ccFontSize / ccOpacity / ccBox are gone with the caption box they configured.
  // A subtitle is a card now, so the card's own settings answer all four: "Show source text" decides
  // whether the original line is there (and it is the tappable one), "Card text" its size. Keeping
  // dead keys around to be safe is how a settings file grows things nothing reads.
  // ---- Studying (the learn window's Settings tab). These used to be constants in the code, which
  // meant the one number the whole "รู้แล้ว" conversation is about could not be changed (jek, 2026-07-30).
  gradSeen: 5,          // meet a word this many times and it counts as known (was the GRAD_SEEN constant)
  reviewCap: 20,        // most cards one review session will hand you; 0 = everything that's due
  reverseDefault: false, // start Review asking meaning → word
  testDefault: false,   // open Review in Test (multiple choice) instead of Study
  speakOnFlip: false,   // say the word out loud when a card flips to its answer
  vocabSortDefault: 'new', // 'new' | 'seen' | 'due' — how the Collected list is ordered on open
  // 2000, up from 300. The cap earns its place for one reason and it is not tidiness: saveHistory()
  // rewrites the WHOLE file on every new row, and CC adds a row per subtitle — an uncapped history
  // means a file that grows all session being rewritten once a second while you play. 300 was set
  // when a row could only come from a snip; live captions changed the arrival rate and nothing
  // revisited the number, so a couple of evenings of CC now pushes real lines off the end. A row is
  // ~300 bytes, so 2000 is ~600KB — still nothing, and the same trap this file already documents for
  // vocab at MAX_VOCAB: at the cap the OLDEST entry goes silently. Starred words are safe either way;
  // they live in vocab.json, not here.
  maxHistory: 2000,
};

let settings = { ...DEFAULT_SETTINGS };

function settingsPath() {
  return path.join(app.getPath('userData'), 'settings.json');
}

// What to translate INTO before anyone has said. It was hard-coded to Thai, so every person who
// downloaded this outside Thailand snipped their first line and got Thai back — a wrong answer
// delivered confidently, in the one moment the app has to prove it works. The app already knows the
// answer: the same OS locale that i18n.js reads to pick the interface language. Asking on a first
// run would be a screen; reading the locale is none.
//
// Only the seven the <select> offers (renderer/main/index.html #targetLang) — a code that is not in
// that list would load a phantom selection, which is the trap the snipStyle migration below already
// fell into once.
const LOCALE_TO_TARGET = [
  ['th', 'th'], ['ja', 'ja'], ['ko', 'ko'], ['vi', 'vi'], ['es', 'es'], ['zh', 'zh-CN'], ['en', 'en'],
];
function firstRunTargetLang() {
  let loc = '';
  // getPreferredSystemLanguages is the one that answers before 'ready'; the others are fallbacks for
  // an Electron that does not have it. All three are wrapped because a locale is never worth a crash.
  try { loc = (app.getPreferredSystemLanguages?.() || [])[0] || ''; } catch { /* ignore */ }
  if (!loc) { try { loc = app.getSystemLocale?.() || ''; } catch { /* ignore */ } }
  if (!loc) loc = process.env.LANG || '';
  loc = String(loc).toLowerCase();
  const hit = LOCALE_TO_TARGET.find(([prefix]) => loc.startsWith(prefix));
  return hit ? hit[1] : 'en';   // an unlisted language reads English far more often than Thai
}

function loadSettings() {
  let fresh = false;
  try {
    const raw = fs.readFileSync(settingsPath(), 'utf8');
    settings = { ...DEFAULT_SETTINGS, ...JSON.parse(raw) };
  } catch {
    settings = { ...DEFAULT_SETTINGS };
    fresh = true;
  }
  // First run only. An existing install keeps whatever it has, chosen or defaulted — a language that
  // changes under someone because they updated is worse than one that started wrong.
  if (fresh && !PAIR_LOCK) settings.targetLang = firstRunTargetLang();
  // The locked edition has no first-run guess to make and no saved value to honour: the pair IS the
  // product. Applied on every load, not just a fresh one, so an install carrying jpn→ja from an
  // earlier build lands on the pair this build can actually deliver.
  if (PAIR_LOCK) Object.assign(settings, PAIR_LOCK);
  // One-time migration to "nothing closes itself" (jek 2026-07-22): a saved file from before this
  // change carries the old auto-close values, so new defaults alone would never reach an existing
  // install. Both are still user-settable afterwards — this only moves the starting point once.
  if (!settings.stayOpenV1) {
    settings.stayOpenV1 = true;
    settings.autoHidePanel = false;
    settings.holdSec = 0;
    saveSettings();
  }
  // 'click' snip style was removed — fold any persisted value back to the default so the renderer's
  // <select> (which no longer has a click option) never loads a phantom selection (jek, 2026-07-31).
  if (settings.snipStyle === 'click') { settings.snipStyle = 'drag'; saveSettings(); }
  // recordableSnip flipped to ON by default (2026-09-08). A default change reaches nobody who has
  // already run the app: the old `false` is sitting in their settings file, written there the first
  // time anything was saved, and it would keep winning forever. This moves them once, and records
  // that it happened so a later deliberate "off" is never undone a second time.
  if (!settings.recSnipDefaultV2) {
    settings.recordableSnip = true;
    settings.recSnipDefaultV2 = true;
    saveSettings();
  }
  // One trigger, one style setting (jek, 2026-08-07). Before this, every install had TWO ways to snip:
  // the snip shortcut (Alt+S by default) and an always-on ⌃⌥ hold-drag with no row of its own. The
  // hold is now simply one of the styles, so an existing settings file needs its habit carried over —
  // and the habit was the hold: it is what the empty state teaches first and what the ⌃⌥ gesture was
  // there for. Only moved when snipStyle is still sitting on the old default; 'point' is a deliberate
  // choice (it is the style you pick when a game blocks hooks) and overwriting it would take away the
  // one style that works for that user. The shortcut itself is left alone: an unset snip binding picks
  // up the new Control+Alt default on its own, and a custom one was chosen on purpose.
  if (!settings.oneTriggerV1) {
    settings.oneTriggerV1 = true;
    if (settings.snipStyle === 'drag') settings.snipStyle = 'hold';
    saveSettings();
  }
  // The migration above turned 'drag' into 'hold' on the reasoning that the two differ only in whether
  // the trigger can be held. For the app that is true; for the hand it is not — dragging a box is
  // aimed and leaves both hands free, sweeping is neither, and with a holdable trigger bound the
  // aimed one had become unreachable. So 'drag' is an option again, and 'point' — which had inherited
  // the name "Normally" — is retired into it. Only 'point' moves: a stored 'hold' was either chosen
  // or inherited from that first migration, and moving it twice would take away a style the user is
  // by now used to. (jek, 2026-08-09: "มันควรจะฟังก์ชันเดียวกันกับตัว Ctrl Shift S สิ")
  if (!settings.snipDragBackV1) {
    settings.snipDragBackV1 = true;
    if (settings.snipStyle === 'point') settings.snipStyle = 'drag';
    saveSettings();
  }
  // And back to one style, this time for a reason that is not taste (jek, 2026-08-29: "เอาฟังก์ชัน
  // การกด keyword ค้าง เป็นฟังก์ชัน snip หลัก ส่วนการลากค้าง เอาออกไปเลย"). Every press style needs a
  // mouse button held down for the length of the sweep, and swallowing that press in the low-level
  // hook is NOT enough: a Unity game (measured on Restory.exe) reads the mouse through Raw Input,
  // which no hook can filter, so the click still fired in the game and the dialogue advanced past the
  // very line being boxed. Holding the trigger presses no mouse button at all, so there is nothing
  // left to leak. Every stored style moves — 'drag'/'point'/'spot' were all chosen before this was
  // understood, and the option is gone from Settings. 'drag' survives only as the automatic fallback
  // in effectiveSnipStyle for a trigger that physically cannot be held.
  if (!settings.holdOnlyV1) {
    settings.holdOnlyV1 = true;
    settings.snipStyle = 'hold';
    saveSettings();
  }
  // Every bar gets out of the way on its own again (jek, 2026-07-31). stayOpenV1 turned both of these
  // off in July on the principle that nothing should close itself; the ask now is the opposite — the
  // card, Settings and History all clear off the screen once you have stopped using them, because
  // this thing lives on top of a game. Like stayOpenV1 this moves the starting point exactly once, so
  // it reaches installs that already have a settings file, and both stay user-settable afterwards.
  if (!settings.autoVanishV1) {
    settings.autoVanishV1 = true;
    // Only move a value that is still sitting where the PREVIOUS migration put it. stayOpenV1 forced
    // holdSec to 0; anyone who has since picked a number of their own picked it deliberately, and a
    // migration that overwrites a deliberate choice without saying so is just data loss with a
    // changelog. autoHidePanel has no such tell — it is a boolean and false is both "stayOpenV1 set
    // this" and "I turned it off" — so it is turned on and stays user-settable from Settings.
    if (settings.holdSec === 0) settings.holdSec = DEFAULT_SETTINGS.holdSec;
    settings.autoHidePanel = true;
    saveSettings();
  }
  // The parked word is on by default now (see pillKeyword in DEFAULT_SETTINGS). A new default alone
  // would reach new installs only: every existing settings.json has the old `false` written into it —
  // saveSettings serialises the whole object, so "never touched it" and "turned it off" look the same
  // on disk, and the switch would appear to do nothing for the people already using the app. Same
  // once-only shape as the migrations above, and it stays user-settable from Settings > Display
  // afterwards. (jek, 2026-08-09 — found it off on their own machine and asked why.)
  if (!settings.pillKeywordOnV1) {
    settings.pillKeywordOnV1 = true;
    settings.pillKeyword = true;
    saveSettings();
  }
  // History's cap moved 300 -> 2000 (see maxHistory in DEFAULT_SETTINGS). Only a file still sitting
  // on the old default is moved: 300 exactly means nobody chose it, any other number was picked in
  // the Learn window and is not ours to overrule. Raising a cap loses nothing — it only stops the
  // next rows from pushing old ones out.
  if (!settings.historyCap2000V1) {
    settings.historyCap2000V1 = true;
    if (Number(settings.maxHistory) === 300) settings.maxHistory = 2000;
    saveSettings();
  }
  // "Other meanings" is on by default now (see showSenses in DEFAULT_SETTINGS). Same once-only shape
  // and the same reason as pillKeywordOnV1: saveSettings serialises the whole object, so every
  // existing settings.json already carries the old `false` and a new default alone would reach new
  // installs only. Moved unconditionally rather than "only if still false" — the switch shipped OFF,
  // so a stored false is the default nobody chose, not a deliberate one. Stays user-settable from
  // Settings › Display afterwards.
  if (!settings.sensesOnV1) {
    settings.sensesOnV1 = true;
    settings.showSenses = true;
    saveSettings();
  }
  // (A ccOriginalOnV1 migration lived here for about an hour, turning on the caption's original line.
  // The caption box is gone; so is the setting it flipped. Removed rather than left running against a
  // key nothing reads — a migration with no reader is a lie about what the file is for.)
}

function saveSettings() {
  try {
    fs.writeFileSync(settingsPath(), JSON.stringify(settings, null, 2));
  } catch (err) {
    console.error('Could not save settings:', err);
  }
}

// History survives a restart so it can serve as a vocab list.
function historyPath() {
  return path.join(app.getPath('userData'), 'history.json');
}

function loadHistory() {
  try {
    const arr = JSON.parse(fs.readFileSync(historyPath(), 'utf8'));
    history = Array.isArray(arr) ? arr.slice(0, Math.max(MAX_HISTORY, historyCap())) : [];
  } catch {
    history = [];
  }
}

function saveHistory() {
  try {
    fs.writeFileSync(historyPath(), JSON.stringify(history));
  } catch (err) {
    console.error('Could not save history:', err);
  }
}

// ---- Insights stats (stats.json) ----
// history.json is capped at MAX_HISTORY, so it can't answer "how much have I read, ever?" or draw a
// streak older than 300 captures. This is the append-only tally that can: one small row per calendar
// day (local dates — the streak grid must line up with the user's own days, not UTC) plus lifetime
// per-script character totals. Cheap enough to rewrite on every capture, like history does.
const MAX_STAT_DAYS = 420; // ~14 months, enough to fill the heatmap's rolling year
// `months` is a SECOND tally, and deliberately not derived from `days`. It counts words COLLECTED
// (one per accepted vocab:add), where days.w counts words READ by the OCR — two numbers an order of
// magnitude apart that must never be shown as the same thing. It has to be its own ledger because
// the obvious alternative, counting savedVocab by ts, answers "what do you still own" and not "what
// did you collect": deleting a word rewrites last year, and at MAX_VOCAB the add is refused outright
// (see vocab:add), so the count would silently stop climbing. One row per calendar month, never
// pruned — 12 tiny entries a year, which is what lets a per-year total survive MAX_STAT_DAYS.
let stats = { days: {}, months: {}, scripts: { ja: 0, zh: 0, ko: 0, la: 0 }, firstTs: 0, mFill: 0 };

function statsPath() {
  return path.join(app.getPath('userData'), 'stats.json');
}

function loadStats() {
  try {
    const s = JSON.parse(fs.readFileSync(statsPath(), 'utf8'));
    stats = {
      days: (s && typeof s.days === 'object' && s.days) || {},
      months: (s && typeof s.months === 'object' && s.months) || {},
      scripts: { ja: 0, zh: 0, ko: 0, la: 0, ...(s && s.scripts) },
      firstTs: (s && s.firstTs) || 0,
      mFill: (s && s.mFill) || 0,
    };
  } catch {
    stats = { days: {}, months: {}, scripts: { ja: 0, zh: 0, ko: 0, la: 0 }, firstTs: 0, mFill: 0 };
  }
}

function saveStats() {
  try {
    fs.writeFileSync(statsPath(), JSON.stringify(stats));
  } catch (err) {
    console.error('Could not save stats:', err);
  }
}

// 'YYYY-MM-DD' in LOCAL time (sv-SE formats exactly that way) — toISOString would shift the day.
function dayKey(ts) {
  return new Date(ts).toLocaleDateString('sv-SE');
}

// 'YYYY-MM', sliced off the same local-time day key so a word collected at 23:50 on the 31st lands
// in the month the user was actually in.
function monthKey(ts) {
  return dayKey(ts).slice(0, 7);
}

// One accepted collection = +1 on its month. Called only where vocab:add really appended, so a word
// re-clicked (already saved, so refused) doesn't inflate the month the way counting raw highlight
// presses would.
function bumpCollected(ts) {
  const key = monthKey(ts || Date.now());
  stats.months[key] = (stats.months[key] || 0) + 1;
  saveStats();
}

// THE script ranges. There were five near-identical copies of these across the app before this table
// (stats, the hover bare-token rescue, the renderer's single-word test, the Learn window's copy of
// that, and the TTS voice guess) — five chances for "what counts as Japanese" to drift apart.
// Anything that needs to ask what alphabet a piece of text is written in reads them from here.
const SCRIPTS = {
  kana: '぀-ヿ',
  hangul: '가-힯ᄀ-ᇿ',
  han: '㐀-鿿豈-﫿',
  latin: 'A-Za-zÀ-ɏ',
};
const SCRIPT_RE = Object.fromEntries(Object.entries(SCRIPTS).map(([k, r]) => [k, new RegExp(`[${r}]`, 'g')]));

// How many characters of each script the text holds. Digits, punctuation and whitespace count as
// nothing at all — "HP 100/100" is two letters of latin, not ten characters of anything.
function scriptCounts(text) {
  const t = String(text || '');
  const out = { total: 0 };
  for (const [name, re] of Object.entries(SCRIPT_RE)) {
    out[name] = (t.match(re) || []).length;
    out.total += out[name];
  }
  return out;
}

// Which script was this capture mostly written in? One bucket per capture, and its whole length is
// credited to that bucket — good enough for a "what am I actually reading" breakdown, and far less
// noise than classifying every character (a JP line is full of latin punctuation and digits).
function dominantScript(text) {
  const c = scriptCounts(text);
  const top = Math.max(c.kana, c.hangul, c.han, c.latin);
  if (!top) return null;
  if (top === c.kana) return 'ja';
  if (top === c.hangul) return 'ko';
  if (top === c.han) return c.kana ? 'ja' : 'zh'; // any kana at all means it's Japanese, not Chinese
  return 'la';
}

// Latin scripts are word-delimited, CJK is not — count spaced words for one and characters for the
// other so a Japanese line doesn't read as "1 word".
// Built from SCRIPTS, which widens the han range here by the compatibility block this function's own
// copy of it used to miss. Those are CJK characters too, so counting them as characters instead of
// folding them into a \p{L} "word" is the answer this function was always after.
const CJK_CHARS = new RegExp(`[${SCRIPTS.kana}${SCRIPTS.han}${SCRIPTS.hangul}]`, 'g');
function countWords(text) {
  const t = String(text || '');
  const cjk = (t.match(CJK_CHARS) || []).length;
  const words = (t.replace(CJK_CHARS, ' ').match(/[\p{L}\p{N}]+/gu) || []).length;
  return cjk + words;
}

// ---- "There is more than one language in this line" ---------------------------------------------
//
// Every OCR engine here reads ONE language: sourceLang is a single value, Windows.Media.Ocr takes one
// Language, tesseract takes one traineddata, and Vision is only ever handed one tag. So a line that
// mixes scripts — an English name inside a Japanese subtitle, a Japanese term in an English paragraph
// — comes back with the other half mangled or missing, and none of the existing quality gates notice:
// the half the engine WAS configured for reads fine and scores well.
//
// This is what routes those lines to Claude instead (see translateOnce), which reads a picture with no
// language setting at all. It is deliberately hard to trigger, because each rescue costs 2 quota units
// where a normal snip costs none — the thresholds exist to keep "HP 100", "Lv.5" and a stray "OK" out
// of the paid path. The whole read is the unit; there is no per-word language anywhere in Gloss.
// The two directions are NOT symmetric, and measuring them against real lines is what showed it:
//   · latin inside a CJK line is everywhere and usually means nothing — HP, MP, Lv.5, OK, YES / NO,
//     START. A Japanese OCR pack reads those correctly anyway, so paying 2 units for them is waste.
//   · a CJK or hangul word inside a latin line is never decoration. It is the one word in the line
//     the reader can't read, and the engine was not set up for it.
// So latin has to clear a share of the line AND look like language rather than a HUD label, while a
// non-latin script only has to be there.
const MIX_MIN_LETTERS = 8;         // shorter than this is a label, not a line worth 2 units
const MIX_MIN_LATIN = 3;           // "OK" and "HP" are two letters and never enough on their own
const MIX_MIN_LATIN_SHARE = 0.15;
const MIX_MIN_OTHER = 2;           // one stray glyph can be a misread; a two-character word is a word
// A latin run counts as LANGUAGE only if it is 3+ letters and not shouted. Games write their interface
// in capitals (SAVE, YES / NO, START) and their prose in ordinary case, so the caps rule separates
// "the UI is in English" from "this sentence has English in it" without a word list to maintain.
const LATIN_RUN = /[A-Za-zÀ-ɏ]+/g;
function latinWordLetters(text) {
  let n = 0;
  for (const run of String(text || '').match(LATIN_RUN) || []) {
    if (run.length >= 3 && run !== run.toUpperCase()) n += run.length;
  }
  return n;
}
// What the engine was ASKED to read — not everything that may legally appear in it. Japanese is mixed
// by construction (kana + han in every sentence) and Chinese and Korean lines carry han the same way,
// so each language owns every script its own writing system uses. Only a script OUTSIDE that set is
// evidence the engine was handed something it cannot read.
const LANG_SCRIPTS = {
  eng: ['latin'],
  jpn: ['kana', 'han'],
  chi_sim: ['han', 'kana'], // kana glyphs a Chinese engine may emit for the same shapes
  kor: ['hangul', 'han'],
};

function looksMixed(text, sourceLang) {
  const c = scriptCounts(text);
  if (c.total < MIX_MIN_LETTERS) return false;
  const own = LANG_SCRIPTS[sourceLang] || LANG_SCRIPTS.eng;
  let other = 0;
  for (const name of Object.keys(SCRIPT_RE)) {
    if (name !== 'latin' && !own.includes(name)) other += c[name];
  }
  if (other >= MIX_MIN_OTHER) return true;
  if (own.includes('latin')) return false; // the line is already in the alphabet we asked for
  const latin = latinWordLetters(text);
  return latin >= MIX_MIN_LATIN && latin / c.total >= MIX_MIN_LATIN_SHARE;
}

// Called once per translation that lands in history — the three paths (snip, typed, live) all funnel
// here so the Insights source bars can never disagree with the capture count.
function bumpStats(payload, defer) {
  const ts = payload.ts || Date.now();
  const text = payload.en || '';
  const key = dayKey(ts);
  const d = stats.days[key] || { c: 0, w: 0, ch: 0, s: 0, t: 0, l: 0, m: 0 };
  d.c += 1;
  d.w += countWords(text);
  d.ch += text.replace(/\s/g, '').length;
  // `m` (spoken) is tested BEFORE `t`: a spoken line also carries `typed` — it reached the same
  // no-OCR path — so testing typed first would file every dictation under "Typed in" and Insights
  // would report a number nobody produced. Same ordering reason as srcOf() in the renderer.
  // Days written before `m` existed simply have no key; `|| 0` at every read site covers them.
  if (payload.spoken) d.m = (d.m || 0) + 1;
  else if (payload.typed) d.t += 1;
  else if (payload.live) d.l += 1;
  else d.s += 1;
  stats.days[key] = d;

  const sc = dominantScript(text);
  if (sc) stats.scripts[sc] = (stats.scripts[sc] || 0) + text.replace(/\s/g, '').length;

  if (!stats.firstTs || ts < stats.firstTs) stats.firstTs = ts;

  const keys = Object.keys(stats.days).sort();
  if (keys.length > MAX_STAT_DAYS) keys.slice(0, keys.length - MAX_STAT_DAYS).forEach((k) => delete stats.days[k]);

  if (!defer) saveStats();
}

// First run after this feature shipped: stats.json doesn't exist yet, but history.json does — so
// replay it once instead of showing an Insights page that claims you've read nothing. Only ever runs
// while stats is empty, so a real tally is never double-counted.
function backfillStats() {
  if (Object.keys(stats.days).length || !history.length) return;
  history.slice().reverse().forEach((p) => bumpStats(p, true)); // oldest first, one write at the end
  saveStats();
}

// Saved vocab words, promoted from the pill's localStorage to here so a future main window can
// share the same collection. vocab.json is the source of truth now; the pill renderer keeps a
// local mirror array but every mutation round-trips through here.
function vocabPath() {
  return path.join(app.getPath('userData'), 'vocab.json');
}

function loadVocab() {
  try {
    const arr = JSON.parse(fs.readFileSync(vocabPath(), 'utf8'));
    vocab = Array.isArray(arr) ? arr.slice(0, MAX_VOCAB) : [];
  } catch {
    vocab = [];
  }
}

// The months ledger starts the day it ships, so everything collected before that would read as zero.
// Seed it once from the vocab we still hold — an undercount for anyone who has deleted words, but a
// floor is honest where a blank year is not. Guarded by its own flag rather than "months is empty",
// because a brand-new install has an empty vocab AND empty months, and would re-run this every boot
// (harmless today, but it would double-count the moment the guard's meaning drifted).
function backfillMonths() {
  if (stats.mFill) return;
  stats.mFill = 1;
  for (const v of vocab) {
    const ts = Number(v && v.ts);
    if (!ts) continue;
    const key = monthKey(ts);
    stats.months[key] = (stats.months[key] || 0) + 1;
  }
  saveStats();
}

function saveVocab() {
  try {
    fs.writeFileSync(vocabPath(), JSON.stringify(vocab));
  } catch (err) {
    console.error('Could not save vocab:', err);
  }
}

// Entry shape can be the new { word, meaning, reading, ... } or the legacy { en, th, ... } (see the
// renderer's getWord comment) — read either so dedup/lookup never misses an old-shaped entry.
function vocabEntryWord(v) {
  return (v && (v.word != null ? v.word : v.en)) || '';
}
function vocabKey(w) {
  return String(w || '').trim().toLowerCase();
}

function vocabHas(word) {
  const key = vocabKey(word);
  return !!key && vocab.some((v) => vocabKey(vocabEntryWord(v)) === key);
}

// ONE door into the collection, for the renderers' ★ (via vocab:add) and for the point-at-a-word key
// alike — so a word kept either way is stored, counted and broadcast identically, and the ceiling
// rule below can't end up with two versions of itself. Returns what happened: 'added' | 'dup' |
// 'full' | 'empty'.
function addVocabEntry(entry) {
  const key = vocabKey(vocabEntryWord(entry));
  if (!key) return 'empty';
  if (vocab.some((v) => vocabKey(vocabEntryWord(v)) === key)) return 'dup';
  // At the ceiling, REFUSE the new word instead of pushing the oldest one out. Losing a word you
  // studied for months to make room for one you just met is the worse of the two failures, and a
  // star that doesn't stick is at least visible — silent deletion is not.
  if (vocab.length >= MAX_VOCAB) {
    console.warn(`Vocab is full (${MAX_VOCAB}) — not saving "${vocabEntryWord(entry)}".`);
    return 'full';
  }
  vocab = [entry, ...vocab];
  saveVocab();
  // Credited to the entry's own ts, not now(): the Learn window and the pill both build the entry
  // before the IPC hop, and a word collected at 23:59:59 must not land in tomorrow's month.
  bumpCollected(Number(entry && entry.ts) || Date.now());
  sendAll('vocab:changed', vocab);
  return 'added';
}

function uiSettings() {
  const { cardSize, showEnglish, showPos, showEnMeaning, showReading, showSenses,
    sourceLang, targetLang, slideSpeed, speakVolume, holdSec, snipStyle, hideFromCapture, dock, autoHidePanel, pillStyle,
    pillKeyword, followMonitor, openAtLogin, aiCards, aiMixedRead, hoverDwellSave, uiLang, ccIntervalMs,
    recordableSnip,
    gradSeen, reviewCap, reverseDefault, testDefault, speakOnFlip, vocabSortDefault, maxHistory } = settings;
  // Flags, never the key itself — the renderers have no business holding it.
  // hasKey answers the only question the UI actually asks: "can I attempt an AI call?" That is now
  // true for everyone, because a user with no key of their own still has the free trial and then a
  // licence. hasOwnKey is the narrower fact, and only Settings needs it (to say the key is saved).
  // canOpenAtLogin: a dev run would register electron.exe (or Electron.app) as the login item, which
  // is not this app — so the row says why it's inert instead of silently doing nothing.
  return { cardSize, showEnglish, showPos, showEnMeaning, showReading, showSenses,
    sourceLang, targetLang, slideSpeed, speakVolume, holdSec, snipStyle, hideFromCapture, dock, autoHidePanel, pillStyle,
    pillKeyword, followMonitor, openAtLogin, canOpenAtLogin: app.isPackaged, aiCards, aiMixedRead, hoverDwellSave, uiLang, ccIntervalMs,
    recordableSnip, isWin: IS_WIN,
    gradSeen, reviewCap, reverseDefault, testDefault, speakOnFlip, vocabSortDefault, maxHistory,
    hasKey: true, hasOwnKey: !!apiKey(), hasLicence: !!settings.licenceKey, quota: quotaSnapshot(),
    buyUrl: BUY_URL };
}

// displayPrefs() was deleted with the only thing that called it. showEnMeaning / showReading /
// showSenses are the FULL-DICTIONARY switches now — they belong to the windows where someone is
// studying a word (Learn › Settings › Advanced), and the hover bubble deliberately ignores all three:
// it answers with one line in the reader's own language, the way the snip Translation Bar does, and a
// switch that can grow it back into a dictionary page is the thing that made it one twice.

// Register (or clear) the OS login item to match the setting. Written on every apply rather than only
// on change: the login item lives in the OS, not in settings.json, so a machine restored from backup
// or an app moved to another folder would otherwise keep a stale entry pointing nowhere.
// Never in a dev run — `npx electron .` would register Electron itself, and uninstalling this app
// would leave that entry behind. uiSettings().canOpenAtLogin tells the UI that's why it's inert.
// Windows writes login items as HKCU\...\Run values, and the value name is ours while the path is
// wherever the exe lived when the toggle was flipped. Reinstall to a different folder, or run a
// portable copy from a second location, and the old value stays — pointing at an exe that may not
// exist any more, or worse, at an OLD Gloss that then starts itself every login while the Settings
// toggle here reads "off" because THIS copy never wrote anything. setLoginItemSettings only ever
// touches one entry, so clearing the stale ones is a separate pass: enumerate what's registered,
// keep only the entry for this exact executable, and delete the rest by name.
// Windows-only — macOS login items are bookmark-based and follow a moved bundle, so there is no
// equivalent orphan to collect there.
//
// Read straight from the registry rather than through app.getLoginItemSettings(). Measured on
// Electron 32.3.3: `launchItems` only ever reports entries whose path is process.execPath — a Run
// value named after our own AppUserModelID but pointing at a different folder comes back as an
// EMPTY list. Every entry this function exists to find is exactly the kind that API hides, so
// using it here would have looked like a fix and cleared nothing.
function pruneStaleLoginItems() {
  if (!IS_WIN || !app.isPackaged) return;
  const { execFileSync } = require('child_process');
  const RUN_KEY = 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run';
  // Task Manager's enabled/disabled state lives in its own key. Deleting only the Run value leaves
  // a ghost row there, so the entry gets removed from both or neither.
  const APPROVED_KEY = 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\StartupApproved\\Run';
  // stdio 'pipe' so a miss on the approval key below reports as a thrown error we swallow, rather
  // than reg.exe printing "unable to find the specified registry key" straight onto our console.
  const reg = (args) => execFileSync('reg', args, { encoding: 'utf8', timeout: 3000, windowsHide: true, stdio: 'pipe' });
  try {
    const mine = process.execPath.toLowerCase();
    const myExe = path.basename(process.execPath).toLowerCase();
    for (const line of reg(['query', RUN_KEY]).split(/\r?\n/)) {
      // `    ValueName    REG_SZ    "C:\...\Gloss.exe" --opened-at-login` — four spaces separate the
      // three columns, and a value NAME may itself contain single spaces, so split on the columns.
      const m = line.match(/^ {4}(.+?) {4}REG_SZ {4}(.*)$/);
      if (!m) continue;
      const [, name, data] = m;
      // The data is a command line: quoted path plus arguments, or a bare path when it has none.
      const cmd = data.trim();
      const exe = cmd.startsWith('"') ? cmd.slice(1, cmd.indexOf('"', 1)) : cmd.split(' ')[0];
      // Only ours: same executable NAME (Gloss.exe) from a different folder. An entry belonging to
      // some other app that happens to sit in the Run key is none of our business.
      if (path.basename(exe).toLowerCase() !== myExe) continue;
      if (exe.toLowerCase() === mine) continue; // this copy — leave it to applyLoginItem()
      reg(['delete', RUN_KEY, '/v', name, '/f']);
      try { reg(['delete', APPROVED_KEY, '/v', name, '/f']); } catch { /* no approval row — nothing to clear */ }
      console.log('cleared stale login item:', name, '->', exe);
    }
  } catch (err) {
    console.error('login item prune failed:', err && err.message); // non-fatal — worst case the stale entry stays
  }
}

function applyLoginItem() {
  if (!app.isPackaged) return;
  pruneStaleLoginItems();
  try {
    app.setLoginItemSettings({
      openAtLogin: !!settings.openAtLogin,
      openAsHidden: !!settings.openAtLogin, // macOS: come up without stealing focus from what you're doing
      // Windows: name the exe and tag the launch, so a session that started itself is telling the
      // truth about it in process.argv (nothing reads the flag yet — it's there for when something
      // needs to behave differently on a login start than on a double-click).
      ...(IS_WIN ? { path: process.execPath, args: ['--opened-at-login'] } : {}),
    });
  } catch { /* a locked-down machine can refuse this; the setting just stays cosmetic */ }
}

// setContentProtection(true) makes the window invisible to screen recorders/screenshots — for
// streaming/recording without the overlay showing. Off by default so it DOES show in captures (the
// original behaviour). Re-applied whenever the setting changes.
function applyContentProtection() {
  // liveActive: live subtitle mode force-hides the overlay from capture (so we never OCR our own
  // card back) regardless of the user's hideFromCapture preference. See startLive()/stopLive().
  //
  // NOT on Windows with the native capture path, for the same reason hidePillFromCapture() skips it
  // there: BitBlt/SRCCOPY already skips layered windows, so the overlay cannot land in our own frame
  // and the affinity flip buys nothing. What it COSTS is severe — this window is display.bounds, i.e.
  // the whole screen (see overlayArea), so display affinity blacks out the entire monitor for anything
  // capturing it. jek turned CC on with Discord sharing his screen and the viewers got a black screen
  // (2026-08-10). A user who ticks hideFromCapture is asking for exactly that and still gets it; live
  // mode is not, and must not decide it for them.
  const forcedByLive = liveActive() && !(IS_WIN && winCaptureAvailable());
  setProtect(mainWindow, forcedByLive || !!settings.hideFromCapture);
}

// Hide the pill (our own EN→TH label + result card) from screen CAPTURE only — it stays visible on
// the display. A snip box that overlaps the pill would otherwise OCR our own UI text ("EN → TH")
// into the translation. Enabled at drag-start so it's fully applied by the time we capture; undone
// by applyContentProtection() (which respects the user's hideFromCapture / live-mode state).
function hidePillFromCapture() {
  // Windows/BitBlt: nothing to do. Plain SRCCOPY already skips layered windows, and the pill window
  // is one — it can't land in the frame. Toggling display affinity anyway made DWM rebuild the pill
  // on every single snip, which read as the pill blinking out and back the moment you pressed the
  // shortcut. Only the desktopCapturer fallback (which does see it) still needs the hide.
  if (IS_WIN && winCaptureAvailable()) return;
  setProtect(mainWindow, true);
}

function doFontStep(delta) {
  settings.cardSize = Math.min(28, Math.max(10, settings.cardSize + delta));
  saveSettings();
  sendAll('settings:changed', uiSettings()); // every window: the Plan tab saves the key, the pill draws the PRO tag
}

// ⌘⇧T / Ctrl⇧T — pop the type-to-translate field open with the cursor ready, without a click. The
// pill overlay is click-through and never focused, so we must hand it keyboard focus here — which on
// macOS activates our app and pulls focus off the game. So remember which app WAS frontmost first;
// returnFocusFromType() (on Enter/Esc) reactivates it so the game gets keyboard control straight back.
let prevFrontApp = null;

// ⌘⇧T is not the only way into the Type page: the pill's ☰ button opens it too, and the panel focuses
// the field itself — no doTypeFocus, so prevFrontApp stayed null (nothing reactivated on Enter: the
// game's keyboard was dead until a manual click) or stale from an earlier ⌘⇧T (the WRONG app got
// reactivated). Capture it where it's true for EVERY entry path instead: whatever takes over when our
// overlay loses focus IS the app that should get the keyboard back afterwards.
let frontCaptureAt = 0;
// Windows has no osascript, and — worse — no blur to hang this on: the overlay is click-through and
// focusable:false, so the 'blur' hook fires on macOS and essentially never here. Windows asks at snip
// time instead (doSnipStart), which is the moment the answer matters: whatever owns the foreground
// when a snip starts IS the game. Measured 2026-09-04: GetForegroundWindow -> GetWindowThreadProcessId
// -> tasklist answers "msedge.exe" for the window under the cursor.
// Until this existed the report's `app` field — "which game", the field this launch needs most — was
// an empty string for every Windows user, because captureFrontApp returned on the darwin check.
function captureFrontAppWin() {
  let pid = 0;
  try { pid = foregroundPid(); } catch { /* hook module unavailable — leave the field empty */ }
  if (!pid || pid === process.pid) return;
  // tasklist, not one more koffi binding: one CSV line, no wide-string buffer to marshal, present on
  // every Windows. It costs a spawn, but at most one per snip — captureFrontApp throttles the burst.
  const p = spawn('tasklist', ['/FI', `PID eq ${pid}`, '/NH', '/FO', 'CSV']);
  let out = '';
  p.stdout.on('data', (d) => { out += d; });
  p.on('close', () => {
    // "eldenring.exe","1234","Console","1","123,456 K" → leading quoted field, minus the extension.
    const m = /^"([^"]+)"/.exec(out.trim());
    if (!m) return; // pid already gone, or the filter matched nothing
    const name = m[1].replace(/\.exe$/i, '');
    if (name && !/^(electron|GameTranslator|Gloss)$/i.test(name)) prevFrontApp = name;
  });
  p.on('error', () => {});
}

function captureFrontApp() {
  if (process.platform === 'win32') {
    const t = Date.now();
    if (t - frontCaptureAt < 800) return; // same one-probe-per-burst rule as the mac path below
    frontCaptureAt = t;
    captureFrontAppWin();
    return;
  }
  if (process.platform !== 'darwin') return;
  const now = Date.now();
  if (now - frontCaptureAt < 800) return; // focus can bounce; one probe per burst is plenty
  frontCaptureAt = now;
  // Small delay: right after our blur the switch may not have landed yet and we'd read ourselves.
  setTimeout(() => {
    const p = spawn('osascript', ['-e', 'tell application "System Events" to get name of first application process whose frontmost is true']);
    let out = '';
    p.stdout.on('data', (d) => { out += d; });
    p.on('close', () => {
      const name = out.trim();
      if (name && !/^(Electron|GameTranslator|Gloss)$/.test(name)) prevFrontApp = name;
    });
    p.on('error', () => {});
  }, 150);
}

// Always opens the panel's Type page — one place to type, whether via ⌘⇧T, the ⧉ button, or Space/a
// typed character out of a snip (the pill's inline field was removed as a confusing second surface, jek
// 2026-07-31). seed is the character that opened it, if any — Space and ⌘⇧T open empty; only a real
// typed character on macOS seeds.
function doTypeFocus(seed) {
  if (!mainWindow || mainWindow.isDestroyed()) return;
  const open = () => { mainWindow.focus(); sendMain('type:focus', { seed: seed || '' }); };
  if (process.platform !== 'darwin') { open(); return; }
  // Accessibility permission (already granted for the mousehook) covers reading the frontmost process.
  const p = spawn('osascript', ['-e', 'tell application "System Events" to get name of first application process whose frontmost is true']);
  let out = '';
  p.stdout.on('data', (d) => { out += d; });
  // Reading ourselves (the panel was already focused) must NOT wipe what the blur-capture recorded —
  // that name is the only way back to the game.
  p.on('close', () => { const n = out.trim(); if (n && !/^(Electron|GameTranslator|Gloss)$/.test(n)) prevFrontApp = n; open(); });
  p.on('error', () => { open(); });
}

// Give keyboard focus back to whatever app was frontmost before ⌘⇧T, so typing a word doesn't leave
// the user stuck in our overlay (game input dead until a manual click). Best-effort; ignores errors.
function returnFocusFromType() {
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.blur();
    // Handing focus back to the game DEACTIVATES our app. A window that is capturing the mouse
    // (ignoreMouseEvents false — which it is, the cursor was on the panel while typing) receives no
    // mousemove at all while the app is inactive, and forwarding only runs when ignore is true. So the
    // renderer went blind: hover froze, `interactive` stayed stuck true, and every click was eaten —
    // only a mousedown-drag still landed, whose mouseup happened to reset it. Drop to click-through
    // here so forwarded mousemove keeps flowing and the next cursor move re-arms hover by itself.
    interactiveState = false;
    mainWindow.setIgnoreMouseEvents(true, { forward: true });
    setClickShield(false); // the shield follows interactiveState everywhere, not only through ui:interactive
    // Release EVERY holder, by iteration, not one by name. This line used to read
    // holdForeground('pill', false) and went stale the day the 'pill' holder was deleted (2026-08-30):
    // the holders that actually existed ('field', 'panel') stayed in the set, so fgHolders was never
    // empty again — and every later holdForeground(x, true) saw `want === had` and returned WITHOUT
    // re-taking the foreground. Measured: after a single Enter the log reads
    //   [DBG] hold panel=true set={field,panel} focused=false
    // with no `fg TAKEN` after it, for the rest of the session. The Type bar could be clicked and
    // never focused again — "พิมพ์ได้แค่ตอนเปิด history ครั้งแรก" (jek).
    //
    // Naming a holder here is the bug, not the typo: this function's job is "we are handing the
    // foreground back", which is true of every holder there is, including ones added later.
    releaseAllForeground();
    sendMain('ui:interactive-reset'); // renderer's own `interactive` var must agree, or it early-returns
  }
  const name = prevFrontApp;
  prevFrontApp = null;
  if (process.platform === 'darwin' && name && !/^(Electron|GameTranslator|Gloss)$/.test(name)) {
    try { spawn('osascript', ['-e', `tell application "${name.replace(/[\\"]/g, '')}" to activate`]); } catch {}
  }
}
ipcMain.on('type:done', () => { console.log('[DBG] type:done'); returnFocusFromType(); });

function sendMain(channel, payload) {
  if (mainWindow && !mainWindow.isDestroyed()) mainWindow.webContents.send(channel, payload);
}

// Broadcasts to EVERY open window, not just the pill — forward-compatible with a future learn/main
// window that shares the same vocab store. Only the pill exists today, so this currently reaches it.
function sendAll(channel, payload) {
  for (const w of BrowserWindow.getAllWindows()) {
    if (!w.isDestroyed()) w.webContents.send(channel, payload);
  }
}


// ---------- OCR (hidden Chromium window) ----------

// tesseract.js never finishes createWorker() under Electron's Node — not in the
// main process, not in a utilityProcess. In a renderer it works, so OCR runs in
// a hidden window and everything it needs is served locally over gt://.
const GT_ROUTES = {
  '/ocr.html': 'renderer/ocr/ocr.html',
  '/ocr.js': 'renderer/ocr/ocr.js',
  '/tesseract.min.js': 'node_modules/tesseract.js/dist/tesseract.min.js',
  '/worker.min.js': 'node_modules/tesseract.js/dist/worker.min.js',
  '/eng.traineddata': 'eng.traineddata',
  '/jpn.traineddata': 'jpn.traineddata',
  // Vertical Japanese (manga/novel columns). The horizontal model reads 縦書き as gibberish at any
  // page-seg mode — measured 59% confidence on a real speech bubble, under MIN_CONFIDENCE, which is
  // exactly what surfaced as "Blurry". Loaded alongside jpn; see the two-pass race in renderer/ocr/ocr.js.
  '/jpn_vert.traineddata': 'jpn_vert.traineddata',
  '/chi_sim.traineddata': 'chi_sim.traineddata',
  '/kor.traineddata': 'kor.traineddata',
};

// electron-builder unpacks tesseract out of the asar; point at the real file.
function resolveAsset(rel) {
  const base = app.isPackaged
    ? (rel.startsWith('node_modules/')
        ? path.join(process.resourcesPath, 'app.asar.unpacked')
        : path.join(process.resourcesPath, 'app.asar'))
    : __dirname;
  if (app.isPackaged && rel.endsWith('.traineddata')) return path.join(process.resourcesPath, rel);
  return path.join(base, rel);
}

// Executables cannot live inside the asar. spawn() goes straight to the OS, which cannot walk a path
// through an archive — it fails ENOTDIR even though fs.existsSync happily says yes, because
// Electron's asar layer only fakes READS. Every native helper here was doing exactly that in a
// packaged build: the ⌃⌥ hold gesture never armed, and Vision OCR fell back to tesseract on every
// machine that wasn't a dev checkout, silently, because the spawn error is caught and logged.
// build.asarUnpack puts native/** on disk next to the archive; this points at that copy. (2026-08-05)
function nativeBin(...parts) {
  const base = app.isPackaged ? path.join(process.resourcesPath, 'app.asar.unpacked') : __dirname;
  return path.join(base, 'native', ...parts);
}

// tesseract.js-core can be hoisted to the top level (dev) or nested under
// tesseract.js (how electron-builder unpacked it). Return whichever exists.
function resolveCore(file) {
  const candidates = [
    'node_modules/tesseract.js-core/' + file,
    'node_modules/tesseract.js/node_modules/tesseract.js-core/' + file,
  ].map(resolveAsset);
  return candidates.find(p => fs.existsSync(p)) || candidates[0];
}

function registerGtProtocol() {
  protocol.handle('gt', (request) => {
    const { pathname } = new URL(request.url);
    let file;
    if (pathname.startsWith('/core/')) {
      file = resolveCore(pathname.slice('/core/'.length));
    } else {
      const rel = GT_ROUTES[pathname];
      if (!rel) return new Response('not found', { status: 404 });
      file = resolveAsset(rel);
    }
    return net.fetch(pathToFileURL(file).toString());
  });
}

function createOcrWindow() {
  if (ocrWindow && !ocrWindow.isDestroyed()) return;
  ocrWindow = new BrowserWindow({
    show: false,
    webPreferences: {
      preload: path.join(__dirname, 'preload-ocr.js'),
      contextIsolation: true,
      nodeIntegration: false,
      backgroundThrottling: false,
    },
  });
  ocrWindow.loadURL('gt://ocr/ocr.html');

  // Both paths settle any in-flight reads and clear ocrWindow so the next
  // recognize() rebuilds it. Without the crash handler, a dead-but-not-destroyed
  // renderer (e.g. tesseract wasm OOM) would leave every future read to time out.
  const teardown = () => {
    ocrWindow = null;
    for (const resolve of ocrPending.values()) resolve({ text: '', confidence: 0 });
    ocrPending.clear();
  };
  ocrWindow.on('closed', teardown);
  ocrWindow.webContents.on('render-process-gone', () => {
    if (ocrWindow && !ocrWindow.isDestroyed()) ocrWindow.destroy();
    teardown();
  });
}

// Set GT_DEBUG=1 to dump what OCR saw/read and log per-stage timings.
const DEBUG = !!process.env.GT_DEBUG;

// The traineddata this build ships (see the file map below) — the languages tesseract can be asked for.
const TESS_LANGS = new Set(['eng', 'jpn', 'chi_sim', 'kor']);

// Tesseract's Japanese/Chinese output, cleaned of the two things it gets wrong on every line of game
// dialogue. Both were measured on a real snip (jek, 2026-08-19): 「あー！久しぶり！呼んでくれてありがとう！」
// came back as `、あ ー! 久 し ぶ り 1 呼ん で くれ て っ あ り が と 1)` — every ！ turned into 1 or 1), and a
// space wedged between almost every kana. The 1s then travelled into the translation ("...แล้ว 1 ...ฉัน 1)"),
// which is what read as a mistranslation when the translator had in fact translated exactly what it was
// handed.
//
// Runs ONLY on tesseract reads (see recognize()). Windows.Media.Ocr and Vision produce neither fault, and
// on a machine with the Japanese OCR pack installed this code never executes at all.
//
// The ！ recovery is deliberately narrow, because a digit after Japanese text is often a real number:
//   converts   り1呼  (kana → digit → CJK)          — a digit wedged inside a kana run is not a number
//   converts   と1)   (kana → 1) )                  — the parenthesised shape is ！ split in two
//   leaves     第1話  (kanji on the left)           — counters and episode numbers keep their digit
//   leaves     レベル1  (nothing readable after it)  — a trailing number stays a number
// The known false positive is a real number that genuinely sits between kana (レベル1です). It costs an
// exclamation mark in the translation, which is the cheaper of the two errors.
const CJK_CH = '\\u3040-\\u30ff\\u3400-\\u4dbf\\u4e00-\\u9fff\\uff66-\\uff9f'; // kana + kanji + halfwidth kana
const KANA_CH = '\\u3041-\\u309f\\u30a1-\\u30ff\\uff66-\\uff9f';
const GAP = '[ \\t\\u3000]*';               // the spaces tesseract sprinkles between glyphs
const GAPN = '[ \\t\\u3000\\r\\n]*';        // the same, plus the line break it wraps a bubble on
// ！ read as a digit or a dash, mid-line: kana → junk → more Japanese. The line break has to be part of
// the gap — measured 2026-08-19, the read was `久しぶり 1\n呼んでくれて`, and a rule that only allowed
// spaces walked straight past it.
const CJK_BANG_INLINE_RE = new RegExp(`([${KANA_CH}])${GAP}[1lI|\uff11]${GAPN}(?=[${CJK_CH}])`, 'g');
// ！ read as junk + a closing paren, which is how it comes back at the END of a line: `ありがと 1)`,
// `ありがと！ー)`. One or two junk characters, because the ！ is sometimes split into two glyphs and
// sometimes read once and then echoed. A real 「(ですね)」 has no junk in front of its bracket, so it stays.
const CJK_BANG_TAIL_RE = new RegExp(`([${KANA_CH}])${GAP}[！!1lI|\uff11\u30fc]{1,2}[)）]`, 'g');
// A line break INSIDE a sentence is layout, not punctuation — a bubble wraps where it runs out of width.
// Joining those lines is what stops the translator answering each fragment on its own (which is how one
// ありがとう came back as two ขอบคุณ). Only between two CJK characters, so a line that ended on 。！？」
// keeps its break: those are not in CJK_CH.
const CJK_NEWLINE_RE = new RegExp(`([${CJK_CH}])${GAP}\\r?\\n${GAP}(?=[${CJK_CH}])`, 'g');
// The left side also accepts Japanese punctuation: 「あー！ 久しぶり」 keeps a space after the ！ that a
// CJK-to-CJK rule cannot see, and that space is one more token for the translator to trip over.
const CJK_SPACE_RE = new RegExp(`([${CJK_CH}！!？?、。ー])[ \\t\\u3000]+(?=[${CJK_CH}])`, 'g');
function tidyCjkRead(text, lang) {
  if (!text || (lang !== 'jpn' && lang !== 'chi_sim')) return text;
  // Order matters: the ！ rules read the gaps as evidence of where a glyph ended, so they run BEFORE
  // the gaps are closed up.
  return text
    .replace(CJK_BANG_TAIL_RE, '$1！')
    .replace(CJK_BANG_INLINE_RE, '$1！')
    .replace(CJK_NEWLINE_RE, '$1')
    .replace(CJK_SPACE_RE, '$1');
}

function recognizeTesseract(png) {
  createOcrWindow();
  const id = ++ocrSeq;
  return new Promise((resolve) => {
    ocrPending.set(id, resolve);
    // The OCR window (re)loads the worker for this language on demand; CJK reads
    // are slower, so give them a longer ceiling than the English default.
    ocrWindow.webContents.send('ocr:recognize', { id, png: new Uint8Array(png), lang: settings.sourceLang, debug: DEBUG });
    setTimeout(() => {
      if (ocrPending.delete(id)) resolve({ text: '', confidence: 0 });
    }, 30000);
  });
}

// ---------- Apple Vision OCR (macOS only) ----------
// Native Vision framework reads game fonts far more accurately than tesseract
// (no U/V confusion etc). Used as the primary engine on darwin; any failure
// (missing binary, spawn error, timeout, empty read) falls through to tesseract.
const VISION_BIN = nativeBin('visionocr');
const VISION_LANG_MAP = { eng: 'en-US', jpn: 'ja-JP', chi_sim: 'zh-Hans', kor: 'ko-KR', tha: 'th-TH' };
const VISION_TIMEOUT_MS = 5000;

// One-shot fallback: spawns a fresh visionocr process per call (~150-250ms overhead just to
// start it). Kept as-is for when the persistent server (below) is unavailable or errors.
function visionRecognizeOnce(pngBuffer, sourceLang) {
  return new Promise((resolve) => {
    if (process.platform !== 'darwin') return resolve({ text: '', confidence: 0 });
    const visionLang = VISION_LANG_MAP[sourceLang] || 'en-US';
    let child;
    try {
      child = spawn(VISION_BIN, ['-', visionLang]);
    } catch (err) {
      warnVisionUnavailable(err.message);
      return resolve({ text: '', confidence: 0 });
    }

    let settled = false;
    const done = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };

    const timer = setTimeout(() => {
      if (!child.killed) child.kill();
      console.error('Vision OCR timed out');
      done({ text: '', confidence: 0 });
    }, VISION_TIMEOUT_MS);

    const chunks = [];
    child.stdout.on('data', (d) => chunks.push(d));
    child.stderr.on('data', (d) => { if (DEBUG) console.error('Vision stderr:', d.toString()); });
    child.on('error', (err) => {
      console.error('Vision process error:', err);
      done({ text: '', confidence: 0 });
    });
    child.on('close', (code) => {
      if (code !== 0) return done({ text: '', confidence: 0 });
      const text = Buffer.concat(chunks).toString('utf8').replace(/\n+$/, '');
      done({ text, confidence: text.trim() ? 90 : 0 });
    });

    child.stdin.on('error', () => {}); // EPIPE if the process already died
    child.stdin.end(pngBuffer);
  });
}

// ---------- Persistent Vision OCR server (macOS) ----------
// `visionocr --serve` stays alive across calls so preview OCR during a drag doesn't pay the
// ~150-250ms process-spawn cost on every tick — only the actual Vision recognition time.
// Requests are strictly FIFO (one line of JSON response per request, in order), so no request
// IDs are needed: a queue of pending resolvers lines up with the responses as they arrive.
let visionServer = null; // { proc, queue: [{resolve}], buf: string }

function startVisionServer() {
  if (process.platform !== 'darwin') return null;
  let proc;
  try {
    proc = spawn(VISION_BIN, ['--serve']);
  } catch (err) {
    warnVisionUnavailable(err.message);
    return null;
  }
  const server = { proc, queue: [], buf: '' };
  proc.stdout.on('data', (d) => {
    server.buf += d.toString('utf8');
    let idx;
    while ((idx = server.buf.indexOf('\n')) !== -1) {
      const line = server.buf.slice(0, idx);
      server.buf = server.buf.slice(idx + 1);
      const pending = server.queue.shift();
      if (!pending) continue;
      try {
        // `lines` is only present when the request asked for it (the ";boxes" lang suffix) — the
        // ordinary translate path never pays for per-character geometry, so it stays undefined
        // there and every existing caller keeps reading .text exactly as before.
        const obj = JSON.parse(line);
        pending.resolve({ text: obj.text || '', lines: obj.lines });
      } catch (err) {
        pending.resolve({ text: '' });
      }
    }
  });
  proc.stderr.on('data', (d) => { if (DEBUG) console.error('Vision server stderr:', d.toString()); });
  const onDown = (err) => {
    if (err) console.error('Vision server died:', err);
    if (visionServer === server) visionServer = null;
    // Fail anything still queued so callers fall back to the one-shot spawn instead of hanging.
    for (const pending of server.queue) pending.resolve(null);
    server.queue = [];
  };
  proc.on('exit', () => onDown());
  proc.on('error', onDown);
  proc.stdin.on('error', () => {}); // EPIPE if the process already died mid-write
  return server;
}

function stopVisionServer() {
  if (!visionServer) return;
  const server = visionServer;
  visionServer = null;
  try { server.proc.stdin.end(); } catch {}
  try { server.proc.kill(); } catch {}
}

// Sends one OCR request to the persistent server; resolves null on any failure (no server,
// dead process, timeout, bad response) so the caller falls back to a one-shot spawn.
function visionServerRecognize(pngBuffer, visionLang) {
  return new Promise((resolve) => {
    if (!visionServer) visionServer = startVisionServer();
    if (!visionServer) return resolve(null);
    const server = visionServer;
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      resolve(null); // leave the queue entry in place — a late response will just no-op below
    }, VISION_TIMEOUT_MS);
    server.queue.push({
      resolve: (result) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve(result);
      },
    });
    try {
      const lenBuf = Buffer.alloc(4);
      lenBuf.writeUInt32BE(pngBuffer.length, 0);
      server.proc.stdin.write(visionLang + '\n');
      server.proc.stdin.write(lenBuf);
      server.proc.stdin.write(pngBuffer);
    } catch (err) {
      if (!settled) { settled = true; clearTimeout(timer); resolve(null); }
    }
  });
}

// Entry point for both preview and final OCR: persistent server first (fast), one-shot spawn
// as the fallback (server never started / died / this request errored or timed out).
async function visionRecognize(pngBuffer, sourceLang) {
  if (process.platform !== 'darwin') return { text: '', confidence: 0 };
  const visionLang = VISION_LANG_MAP[sourceLang] || 'en-US';
  const viaServer = await visionServerRecognize(pngBuffer, visionLang).catch(() => null);
  if (viaServer && typeof viaServer.text === 'string') {
    const text = viaServer.text.replace(/\n+$/, '');
    return { text, confidence: text.trim() ? 90 : 0 };
  }
  return visionRecognizeOnce(pngBuffer, sourceLang);
}

// ---------- Windows.Media.Ocr (Windows only) ----------
// The Windows half of "use the OCR the OS already ships with". Same reasoning as Vision on macOS:
// the native engine reads game fonts far better than tesseract.js, and it is free, offline and
// already installed. See native/winocr.ps1 for the protocol and why it is a PowerShell script.
//
// Everything here degrades to tesseract rather than failing: no PowerShell, no language pack, a
// dead server, a timeout, a malformed reply — all resolve to empty text, and recognize() falls
// through exactly as it does when Vision misses on macOS.
// nativeBin, not __dirname: powershell.exe is an outside process and cannot read a path that runs
// through app.asar. Worse, the existsSync guard below could not catch it — Electron answers that for
// the archive and says the file is there — so the spawn went ahead and Windows OCR failed silently
// into tesseract on every packaged build. Same fault as the native binaries. (2026-08-05)
const WINOCR_PS1 = nativeBin('winocr.ps1');
// Our OCR language codes → BCP-47 tags Windows.Globalization.Language accepts.
const WINOCR_LANG_MAP = { eng: 'en-US', jpn: 'ja', chi_sim: 'zh-Hans', kor: 'ko' };
// The tags above are what the OCR engine is asked for; they are NOT what a reader is told. "No ja
// OCR pack" shipped the code itself into the pill and the banner (jek, 2026-08-20) — and "ja" is
// also the one hop of the Settings path the reader has to match against a list that says Japanese.
const WINOCR_LANG_LABELS = { 'en-US': 'English', ja: 'Japanese', 'zh-Hans': 'Chinese', ko: 'Korean' };
const WINOCR_TIMEOUT_MS = 5000;
// The PNG travels as a file path, so keep a small rotating set of names instead of one per read —
// if a delete ever fails (antivirus holding the handle, say) this caps the mess at four files
// instead of leaving one behind for every frame of a live translation.
const WINOCR_SLOTS = 4;
let winOcrSlot = 0;

let winOcrServer = null; // { proc, queue: [{resolve}], buf: string, langs: string[] }
let winOcrDisabled = false; // set once the engine proves unavailable, so we stop retrying every read
const winOcrWarned = new Set(); // language tags we've already told the user about

// Does this machine have NOTHING native to read this language with? Windows ships OCR for the
// languages you have installed and nothing else, and the fallback — tesseract — is not a mild step
// down on CJK: measured on a hand-lettered manga bubble it returned "アバ 具 ハ っ1 たカ ん 1 す の SS"
// for パーカー買ったんすか, at 70% confidence, which is a WRONG answer delivered confidently and so
// passes every quality gate the rescue below normally waits for (2026-08-19). Swapping in the
// heavier tessdata_best model was tried and measured worse — 65% on the same bubble, and it broke a
// vertical line the light model reads correctly — so there is no better local engine to reach for.
//
// The honest answer is that the read is unreliable for the whole session, not for one bad crop, and
// something that can actually read it should be asked FIRST rather than after a gate happens to trip.
// Is the AI reader actually going to cover a missing pack? All three have to be true — the switch,
// the allowance, and a client to call — and any one of them being false puts the user back on
// tesseract, which is the version of the banner that has an errand in it.
function aiCovers() {
  return !!(settings.aiMixedRead && aiAllowanceLeft() && anthropicClient());
}

function nativeOcrMissing(lang) {
  if (!IS_WIN) return false;            // macOS Vision needs no packs
  if (!winOcrServer || !winOcrServer.ready) return false; // not up yet — say nothing rather than guess
  const tag = WINOCR_LANG_MAP[lang];
  if (!tag) return false;
  const langs = winOcrServer.langs || [];
  if (!langs.length) return false;      // an engine that reported no list at all is not evidence
  return !langs.some((l) => String(l).toLowerCase().startsWith(String(tag).toLowerCase()));
}

function startWinOcrServer() {
  if (!IS_WIN || winOcrDisabled) return null;
  if (!fs.existsSync(WINOCR_PS1)) { winOcrDisabled = true; return null; }
  let proc;
  try {
    // powershell.exe, NOT pwsh.exe — the WinRT bridge in the script needs .NET Framework.
    // windowsHide stops a console window from flashing over the game on every launch.
    proc = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', WINOCR_PS1], { windowsHide: true });
  } catch (err) {
    console.error('Windows OCR spawn failed:', err);
    winOcrDisabled = true;
    return null;
  }
  const server = { proc, queue: [], buf: '', langs: [], ready: false };
  proc.stdout.on('data', (d) => {
    server.buf += d.toString('utf8');
    let idx;
    while ((idx = server.buf.indexOf('\n')) !== -1) {
      const line = server.buf.slice(0, idx).trim();
      server.buf = server.buf.slice(idx + 1);
      if (!line) continue;
      let msg;
      try { msg = JSON.parse(line); } catch { msg = null; }
      // The startup handshake is not a reply to anything — consuming a queue slot for it would
      // desync every later request from its response.
      if (msg && msg.ready) {
        server.ready = true;
        server.langs = Array.isArray(msg.langs) ? msg.langs : [];
        if (DEBUG) console.log('Windows OCR ready, languages:', server.langs.join(', ') || '(none)');
        continue;
      }
      const pending = server.queue.shift();
      if (!pending) continue;
      pending.resolve(msg || { text: '' });
    }
  });
  proc.stderr.on('data', (d) => { if (DEBUG) console.error('Windows OCR stderr:', d.toString()); });
  const onDown = (err) => {
    if (err) console.error('Windows OCR server died:', err);
    // Dying before the handshake means this machine can't run the script at all (no WinRT bridge,
    // blocked PowerShell, a syntax error). Give up for the session — without this we'd respawn
    // PowerShell and eat a 5s timeout on every single read, which during a live translation is far
    // worse than simply using tesseract.
    if (!server.ready) {
      winOcrDisabled = true;
      console.error('Windows OCR unavailable — using tesseract for this session');
    }
    if (winOcrServer === server) winOcrServer = null;
    for (const pending of server.queue) pending.resolve(null);
    server.queue = [];
  };
  proc.on('exit', () => onDown());
  proc.on('error', onDown);
  proc.stdin.on('error', () => {}); // EPIPE if the process already died mid-write
  return server;
}

function stopWinOcrServer() {
  if (!winOcrServer) return;
  const server = winOcrServer;
  winOcrServer = null;
  try { server.proc.stdin.end(); } catch {}
  try { server.proc.kill(); } catch {}
}

// A missing language pack is a setup problem the user can actually fix, so say so — once per
// language, not once per frame. Silence here would look like "the app just can't read Japanese".
// Vision is the reason mac reads are fast and accurate; tesseract is the safety net, not the plan.
// Falling back is correct — dying is worse — but doing it in silence means a user whose Vision helper
// is broken gets years of mediocre OCR and no idea there is anything to fix. Say it once, then stop.
let visionWarned = false;
function warnVisionUnavailable(why) {
  if (visionWarned) return;
  visionWarned = true;
  console.error('Vision OCR unavailable:', why);
  setHintState('Apple Vision unavailable — reading with the slower engine');
}

function warnMissingOcrPack(tag) {
  if (winOcrWarned.has(tag)) return;
  winOcrWarned.add(tag);
  console.error(`Windows OCR has no data for ${tag} — falling back to tesseract`);
  // This used to be the whole Settings path in the pill: 130 characters into a 109px slot, which is a
  // marquee — text that warps off the right edge and slides back while you are mid-game, for the one
  // message that most needs reading. Worse, reciting a path is exactly what the permission banner's
  // button exists to replace, and Windows has had the deep link the whole time. Two words in the slot,
  // the sentence and the button in the banner. Same shape as the mic's privacy/mic errors.
  const name = WINOCR_LANG_LABELS[tag] || tag;
  setHintState(`No ${name} pack`);
  sendMain('permission:setting', {
    pane: 'ocr',
    // TWO different situations wearing one sentence until now. If the AI reader is on and has
    // allowance, nothing is broken — the pictures are being read, they are just being read the
    // expensive way — and a banner that opens with an instruction is asking for a chore that is not
    // due. If it is not on, the backup engine really is the whole story and the install matters.
    // Naming the state first and the errand second is the difference between the two (jek,
    // 2026-08-19: "คนใช้มันยุ่งยากไง" — of being sent down a six-step Settings path to fix something
    // the app had already worked around).
    // State first, errand second — and now in two SPANS, not one paragraph. Four lines of one weight
    // is a wall a reader mid-game skips whole, which loses the half that matters: nothing is broken.
    // The steps carry no news, only keystrokes, so they go to the dim second line the banner already
    // owns for exactly this (jek, 2026-08-20).
    msg: aiCovers()
      ? `No ${name} reading pack on this PC, so AI is reading these from the picture — accurate, but it spends your AI allowance.`
      : `No ${name} reading pack on this PC — reading with the slower engine until one is installed.`,
    // Spelled from the pane the button opens (ms-settings:regionlanguage), not from the root of
    // Settings: naming a screen the reader is already looking at is the half of a path that costs
    // nothing to read and everything to get wrong. The language's own NAME is the hop that was
    // missing — "(the language)" never said which list it was in (jek, 2026-08-19).
    detail: `Free and instant once installed — Open Settings › ${name} › ⋯ › Language options › Optional features › Optical character recognition › Install.`,
  });
}

function winOcrServerRecognize(pngBuffer, tag, boxes = false) {
  return new Promise((resolve) => {
    if (!winOcrServer) winOcrServer = startWinOcrServer();
    if (!winOcrServer) return resolve(null);
    const server = winOcrServer;

    let file;
    try {
      const dir = app.getPath('temp');
      file = path.join(dir, `gloss-ocr-${winOcrSlot}.png`);
      winOcrSlot = (winOcrSlot + 1) % WINOCR_SLOTS;
      fs.writeFileSync(file, pngBuffer);
    } catch (err) {
      console.error('Windows OCR temp write failed:', err);
      return resolve(null);
    }

    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try { fs.unlinkSync(file); } catch {}
      resolve(result);
    };
    // On timeout the queue entry stays put on purpose: a late reply still lines up with its own
    // request, so the FIFO pairing survives instead of shifting every later response by one.
    const timer = setTimeout(() => finish(null), WINOCR_TIMEOUT_MS);

    server.queue.push({ resolve: finish });
    try {
      // `boxes` only when asked: building the per-character geometry costs the helper real work on
      // a line of text, and every ordinary read (snip, CC, typed) has no use for it.
      server.proc.stdin.write(JSON.stringify(boxes ? { lang: tag, path: file, boxes: true } : { lang: tag, path: file }) + '\n');
    } catch (err) {
      finish(null);
    }
  });
}

async function winOcrRecognize(pngBuffer, sourceLang) {
  if (!IS_WIN) return { text: '', confidence: 0 };
  const tag = WINOCR_LANG_MAP[sourceLang] || 'en-US';
  const res = await winOcrServerRecognize(pngBuffer, tag).catch(() => null);
  if (!res) return { text: '', confidence: 0 };
  if (res.error === 'no-pack') {
    warnMissingOcrPack(tag);
    return { text: '', confidence: 0 };
  }
  if (res.error && DEBUG) console.error('Windows OCR error:', res.error);
  const text = String(res.text || '').replace(/\n+$/, '');
  // Same confidence Vision reports: the native engines don't hand back a usable per-read score, and
  // ocrScaled() only needs a number good enough to pick between the plain and binarized attempts.
  return { text, confidence: text.trim() ? 90 : 0 };
}

// ---------- ⌘⇧M speak-to-translate (macOS only) ----------
// Say it instead of typing it: press the shortcut, talk, and the sentence you spoke becomes the
// source text for a normal translation card — same card, same history row, same vocab tapping as a
// snip. Stops on its own ~1.6s after you finish talking, or press the shortcut again.
//
// Recognition runs in native/Speak.app (SFSpeechRecognizer, on-device). It has to be its own bundle:
// requesting speech authorization without NSSpeechRecognitionUsageDescription in the requesting
// process's Info.plist is an instant crash, and Electron's bundled plist only carries the microphone
// key. Both permissions are asked once, on the first use.
const SPEAK_BIN = nativeBin('Speak.app', 'Contents', 'MacOS', 'speak');
// Windows has a recogniser in the box too (the one Voice Typing uses), reached through WinRT from
// PowerShell exactly the way winocr.ps1 reaches Windows.Media.Ocr — so "macOS-only" stopped being a
// property of the feature and started being a property of the code. See native/winspeak.ps1 for what
// differs (no live partials there) and why.
const WINSPEAK_PS1 = nativeBin('winspeak.ps1');
const SPEAK_HELPER = IS_WIN ? WINSPEAK_PS1 : SPEAK_BIN;
// Our OCR language codes → the BCP-47 tags the recogniser wants. You dictate in the SOURCE language
// (the one being translated from), which is exactly what sourceLang already means. Windows takes the
// script-qualified tag for Chinese; the others are the same on both.
const SPEAK_LOCALES = { eng: 'en-US', jpn: 'ja-JP', chi_sim: 'zh-CN', kor: 'ko-KR' };
const SPEAK_LOCALES_WIN = { eng: 'en-US', jpn: 'ja-JP', chi_sim: 'zh-Hans-CN', kor: 'ko-KR' };
let speakProc = null;
let speakBuf = '';
let speakHeard = '';
let speakErrored = false; // the helper reported a reason before exiting — don't overwrite it on close
let speakCancelled = false; // a Windows second-press killed the helper: the words are gone, say so
let speakFinishing = false; // "I'm done" pressed on Windows — waiting out the end-silence, not killing
// Holding a global shortcut makes Windows resend WM_HOTKEY (~30/s once the OS repeat delay elapses),
// and every repeat reaches the action looking like a fresh press. On a TOGGLE that is visible as the
// thing flickering on and off in your hand. Same shape as the snip flicker and the same two-part fix:
// swallow the repeat burst, and refuse a "stop" that lands too soon after the "start" — the first
// repeat arrives one OS repeat-delay later, which clears any burst window worth having.
let lastSpeakKeyAt = 0;
let speakStartedAt = 0;
const SPEAK_REPEAT_MS = 250; // the burst itself
const SPEAK_MIN_ON_MS = 900; // how soon a second press may legitimately mean "I'm done"

function speakStop() {
  if (!speakProc) return;
  // Windows has no stdin protocol: winspeak.ps1 is a single blocking RecognizeAsync, so there is no
  // way to ask it to wrap up — ending it IS killing it, and everything said so far dies with the
  // process. That makes the second press a CANCEL on Windows and a FINISH on macOS, and the app has
  // to stop pretending otherwise: the close handler used to report the kill as "Heard nothing",
  // which reads as "your mic isn't working" when what actually happened is "you threw it away".
  // (jek, 2026-08-07.) On Windows this is now only reached as a DELIBERATE cancel — a press that
  // arrives while the pill already says "Finishing…". The ordinary "I'm done" press never comes here,
  // because killing is exactly what it must not do; see toggleSpeak.
  if (IS_WIN) { speakCancelled = true; try { speakProc.kill(); } catch { /* already gone */ } return; }
  try { speakProc.stdin.write('stop\n'); } catch { /* already gone */ }
}

function toggleSpeak() {
  const now = Date.now();
  const sinceKey = now - lastSpeakKeyAt;
  lastSpeakKeyAt = now; // bumped on EVERY call: while the key is held the gap never reopens
  if (sinceKey < SPEAK_REPEAT_MS) return;
  if (speakProc) {
    // A real second press means "I'm done". A repeat of the press that STARTED this one does not, and
    // it arrives about half a second in — long enough to clear the burst test above.
    if (now - speakStartedAt < SPEAK_MIN_ON_MS) return;
    // Windows: "I'm done" must NOT kill the helper. RecognizeAsync cannot be asked to wrap up, and
    // killing it throws away every word — which is what made a deliberate finish report itself as
    // "Heard nothing". But it does not have to be killed: you press this because you have STOPPED
    // TALKING, so the 2s end-silence timer is already running and will land the phrase by itself
    // within a moment. Doing nothing but saying so is therefore the whole fix, and it keeps the words.
    //
    // (The graceful StopAsync lives on SpeechContinuousRecognitionSession, which delivers its results
    // through the ResultGenerated EVENT — and PowerShell 5.1 answers "Windows PowerShell cannot
    // subscribe to Windows RT events", measured 2026-08-07. That road needs a compiled helper, not a
    // bigger script, so it is not this one.)
    if (IS_WIN && !speakFinishing) {
      speakFinishing = true;
      setHintState('Finishing…');
      return;
    }
    speakStop(); // macOS: the graceful stdin stop. Windows: pressed AGAIN while finishing = cancel.
    return;
  }
  if (!fs.existsSync(SPEAK_HELPER)) { setHintState('Voice helper missing from this build'); return; }
  speakBuf = '';
  speakHeard = '';
  speakErrored = false;
  speakCancelled = false;
  speakFinishing = false;
  speakStartedAt = now;
  const locale = (IS_WIN ? SPEAK_LOCALES_WIN : SPEAK_LOCALES)[settings.sourceLang] || 'en-US';
  let proc;
  try {
    proc = IS_WIN
      // -File, not -Command: the path can contain spaces and a user folder can contain anything.
      // powershell.exe (5.1), never pwsh — the WinRT Await bridge is .NET Framework only.
      ? spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass',
              '-File', WINSPEAK_PS1, locale], { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true })
      : spawn(SPEAK_BIN, [locale], { stdio: ['pipe', 'pipe', 'pipe'] });
  } catch (err) { console.error('speak spawn failed:', err); setHintState('Voice input failed to start'); return; }
  speakProc = proc;
  // No "Listening…" here. The helper reports ready ~400ms later and that sets "Speak now" — two nearly
  // identical statuses 0.4s apart read as a flicker in the slot (measured 2026-07-30, jek reported it).
  // The mic button flips to .listening on this same event, so the click already has instant feedback;
  // the slot only speaks up when speaking will actually be heard.
  sendMain('speak:state', { on: true });

  proc.stdout.on('data', (d) => {
    speakBuf += d.toString('utf8');
    let idx;
    while ((idx = speakBuf.indexOf('\n')) !== -1) {
      const line = speakBuf.slice(0, idx).trim();
      speakBuf = speakBuf.slice(idx + 1);
      if (line) handleSpeakLine(line);
    }
  });
  proc.stderr.on('data', (d) => console.warn('speak:', d.toString('utf8').trim()));
  proc.on('error', (err) => { console.error('speak error:', err); speakProc = null; sendMain('speak:state', { on: false }); setHintState('Voice input failed'); });
  proc.on('close', () => {
    speakProc = null;
    sendMain('speak:state', { on: false });
    // The helper emits {"final"} before exiting; if we never got any words, say so instead of
    // leaving "Listening…" frozen on the pill.
    //
    // But NOT when the helper already said why it failed. An error line is followed immediately by
    // the process exiting, so this ran a few milliseconds later and replaced the one message that
    // could have been acted on — "Turn on Online speech recognition" became "Heard nothing", which
    // reads as "your microphone is fine, you just didn't speak" and sends the user looking in the
    // wrong place entirely. (jek, Win11 2026-08-07)
    // Three different silences, three different things to say. "Heard nothing" is only true for the
    // first one; using it for all three is what turned a self-inflicted cancel into a bug report.
    if (speakCancelled) setHintState('Cancelled — nothing kept');
    else if (!speakHeard && !speakErrored) setHintState('Heard nothing');
  });
}

function handleSpeakLine(line) {
  let msg;
  try { msg = JSON.parse(line); } catch { return; }
  // "Speak now", not "Listening… speak now": the pill's slot is 109px and that string measured 115px,
  // so the SECOND status of the mic flow overflowed and had to start a marquee — which pops the text out
  // to the right edge before sliding in. That is the warp-then-vanish-then-slide jek saw right after
  // clicking the mic (measured 2026-07-30). Both mic statuses fit the slot now: clean swaps, no ticker.
  if (msg.state === 'ready') { setHintState('Speak now'); return; }
  if (msg.partial) {
    speakHeard = msg.partial;
    sendMain('speak:partial', msg.partial); // live text on the pill while you talk
    return;
  }
  if (typeof msg.final === 'string') {
    const text = msg.final.trim();
    speakHeard = text;
    // 'speak' so the row can say where it came from. Everything after this point is an ordinary
    // translation: card + history + vocab — only the origin mark differs.
    if (text) translateText(text, 'speak');
    return;
  }
  if (msg.error) {
    speakErrored = true; // so the close handler doesn't paint "Heard nothing" over the real reason
    // Where the fix lives is different on each OS, and sending a Windows user to "System Settings →
    // Privacy → Speech Recognition" is worse than saying nothing: they go hunting for a pane that
    // does not exist and conclude the app is broken.
    const why = (IS_WIN ? {
      speech: 'Voice input failed — try again',
      // The one every Windows box hits first: "Online speech recognition" ships OFF, and until it is
      // on, RecognizeAsync refuses before the mic is ever opened. Named separately from 'mic' because
      // the fix is a different pane — sending someone to Privacy › Microphone, where every switch
      // already says Allow, is how a fixable setting turns into "this app is broken".
      privacy: 'Turn on Settings › Privacy & security › Speech › Online speech recognition',
      mic: 'Microphone access denied — Settings › Privacy & security › Microphone',
      recognizer: 'No speech pack for this language — Settings › Time & language › Language & region › (language) › Speech',
      engine: 'No microphone available',
      // Short on purpose. The slot is 109px; a longer sentence starts a marquee, which hides the text
      // for a frame and slides it in from the right — and that stutter, arriving a second after the
      // mic lit up and went dark again, is exactly what the offline mic looked like. (jek, 2026-08-07)
      network: 'No internet',
    } : {
      speech: 'Speech recognition permission denied — System Settings → Privacy → Speech Recognition',
      privacy: 'Speech recognition permission denied — System Settings → Privacy → Speech Recognition',
      mic: 'Microphone permission denied — System Settings → Privacy → Microphone',
      recognizer: 'No speech model for this language',
      engine: 'No microphone available',
      network: 'No internet',
    })[msg.error] || 'Voice input failed';
    setHintState(why);
    // A pill hint is 109px of sliding text and it is gone in a few seconds — fine for "try again",
    // useless for "go turn a switch on in another app". The two errors that are FIXABLE get the same
    // banner-with-a-button the screen-recording refusal already had on macOS, now that
    // permission:open-settings knows how to reach a Windows pane.
    const pane = { privacy: 'speech', mic: 'mic' }[msg.error];
    if (pane) sendMain('permission:setting', { pane, msg: why });
  }
}

// ---------- ⌃⌥ hold-drag-to-translate (macOS only) ----------
// `mousehook` is a tiny always-listening CGEventTap: install Accessibility once, then it streams
// "down x y" / "move x y" / "up x y" lines (global display points, top-left origin) for the middle
// combo is held, ANYWHERE on screen. listenOnly, so every other app's use of ⌃/⌥ is untouched.
const MOUSEHOOK_BIN = nativeBin('mousehook');
let mouseHookProc = null;
let mouseHookMods = ''; // the arming set the running helper was spawned with — '' when it isn't running
let mouseHookBuf = '';
let mouseHookRespawnTimer = null;

let macHoldActive = false; // a 'hold' session opened by the event tap is in progress
function handleMouseHookLine(line) {
  if (!line) return;
  if (line === 'PERM_NEEDED') {
    mouseHookPermNeeded();
    return;
  }
  const parts = line.split(' ');
  if (parts.length !== 3) return;
  const [kind, xs, ys] = parts;
  const x = parseInt(xs, 10);
  const y = parseInt(ys, 10);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;

  // Same branch as the Windows hook (startWinComboHook): the tap is watching a modifier-only trigger,
  // which the OS cannot register as a shortcut, so this is the ONLY way that key reaches the app —
  // in every style, not just 'hold'. In the press styles its down edge is the press and the stream of
  // moves and the release are nothing at all.
  if (kind === 'down') {
    // 'drag' style has no release edge to work with - the press IS the whole trigger - so the keep
    // gesture lives on the press instead: a trigger press within KEEP_TAP_MS of a snip firing means
    // "keep that one", not "start another". This is the mode jek actually runs, and without it the
    // second press simply opened a new snip, which is exactly what he reported (2026-08-15).
    // NOT extended to 'point' style: there the second press is the shutter (see doSnipStart's note).
    if (effectiveSnipStyle() === 'drag' && Date.now() - lastSnipFiredAt <= KEEP_TAP_MS) {
      macHoldActive = false;
      lastSnipFiredAt = 0; // one press, one keep - the next press is a snip again
      keepLastSnip();
      return;
    }
    if (effectiveSnipStyle() !== 'hold') { macHoldActive = false; doSnipStart(); return; }
    macHoldActive = true;
    mouseHookDown(x, y);
  } else if (kind === 'move') { if (macHoldActive) mouseHookMove(x, y); }
  else if (kind === 'up') { if (macHoldActive) { macHoldActive = false; mouseHookUp(x, y); } }
}

// One dialog per app run — a permanently-denied permission shouldn't nag on every attempted drag.
let mouseHookPermDialogShown = false;
function mouseHookPermNeeded() {
  // This used to say "⌘⇧S still works" — which was true when the tap only carried a SECOND, optional
  // gesture. It is the snip trigger's only delivery path now whenever that trigger is modifier-only
  // (the OS will not register one), so without this permission the key does nothing at all and saying
  // otherwise sends the user back to a shortcut that is dead. The ⧉ button on the pill still snips,
  // and re-keying to something with a letter in it goes back through the OS. (jek, 2026-08-07)
  console.warn('mousehook: Accessibility permission not granted — the snip trigger cannot be delivered; the pill\'s ⧉ button still works');
  if (mouseHookPermDialogShown) return;
  mouseHookPermDialogShown = true;
  if (!mainWindow || mainWindow.isDestroyed()) return;

  // FIRST refusal, we stay out of the way. mousehook asks with the prompting form of the API, so
  // macOS puts up its own "Gloss would like to control this computer" panel — and that panel is the
  // one that actually leads anywhere, because the OS opens the pane with our row already in it. Our
  // sheet arrives a moment later and lands ON TOP of it, hiding the working button behind an
  // explanation of the button. Watched it happen (2026-08-08). So the first time, say it in the
  // banner, which sits inside our own window and covers nothing.
  //
  // From the second run on there IS no system panel — macOS asks once per app and then goes quiet —
  // so the sheet becomes the only thing that can say why the trigger is dead, and it shows.
  if (!settings.axPromptSeenV1) {
    settings.axPromptSeenV1 = true;
    saveSettings();
    sendMain('permission:setting', {
      pane: 'accessibility',
      msg: 'Accessibility is off — the ⌃⌥ snip trigger cannot reach Gloss.',
    });
    return;
  }
  dialog.showMessageBox(mainWindow, {
    type: 'info',
    title: 'Accessibility permission needed',
    message: 'Gloss needs Accessibility access to see the snip trigger.',
    // The second paragraph is the one that matters after an update, and it used to be missing. macOS
    // remembers this permission against the exact build that was granted it, so a new build arrives
    // denied while the list still shows "Gloss ✓ on" under the same name and icon. Telling someone
    // in that state to "grant access" describes something they can already see is done — they read it
    // as the app being broken, because nothing on screen disagrees with them. It has to name the
    // already-on case out loud or it is worse than saying nothing. (jek hit this himself, 2026-08-08)
    detail: 'Until then, snip with the ⧉ button on the pill — or set a trigger with a letter in it (Settings → Shortcuts), which macOS can deliver on its own.\n\n'
      + 'In System Settings → Privacy & Security → Accessibility: if Gloss is ALREADY listed and switched on, that entry belongs to an older version — switch it off and on again, or remove it with − and add it back with +. Use “Show me the app” so you add the right copy. Then relaunch Gloss.',
    buttons: ['Open System Settings', 'Show me the app', 'Later'],
    defaultId: 0,
    cancelId: 2,
  }).then((res) => {
    if (res.response === 0) {
      shell.openExternal('x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility');
    } else if (res.response === 1) {
      // Same reveal the banner's button uses, for the same reason: the + picker gives no hint which
      // copy is the running one, and two identically-named copies is the normal case here.
      shell.showItemInFolder(appBundlePath());
      // Reopening is what makes this button usable instead of a dead end — you look at the file, then
      // you still need the pane to drop it into. Dismissing the dialog to show Finder would otherwise
      // end the flow and the one-dialog-per-run guard means it never comes back.
      mouseHookPermDialogShown = false;
    }
  }).catch(() => {});
}

// ---- External hold-drag session driven by the hook (either trigger) ----
// { display, win, startX, startY } in global screen coords — null when no drag is in progress.
let externSession = null;
let externMoveThrottle = 0;

function externOverlayFor(display) {
  ensureSnipWindows();
  const displays = screen.getAllDisplays();
  const idx = displays.findIndex((d) => d.id === display.id);
  return idx === -1 ? null : snipWindows[idx];
}

// combo=true means the ⌃⌥-held trigger specifically. Windows reaches this function two ways — the
// ⌘⇧S left-drag (winhook.js) and ⌃⌥ (winkeyhook.js) — and the overlay's hint has to name the right
// one. macOS passes nothing: the hold-drag is the only way it reaches this function.
function mouseHookDown(x, y, combo = false) {
  // A new drag is a new question. Whatever the last one's tap asked for, it is not this one's answer.
  keepArmedAt = 0;
  // Don't stack on top of an active ⌘⇧S/CC session, or re-enter while a drag is already open
  // (flags/button glitches could otherwise fire a second down before the matching up).
  if (snipping || externSession) return;
  const display = screen.getDisplayNearestPoint({ x, y });
  const win = externOverlayFor(display);
  console.log('snip down at', x, y, '→ display', display.id, JSON.stringify(display.bounds),
    'overlay?', !!win, win && !win.isDestroyed() ? JSON.stringify(win.getBounds()) : '');
  if (!win || win.isDestroyed()) return;
  externSession = { display, win, startX: x, startY: y };
  // Hold-⌃⌥ path: same follow rule as the ⌘⇧S path (see followCursorMonitor). We already know the
  // display here, so use it directly rather than re-reading the cursor.
  if (settings.followMonitor && displayList().length > 1) moveToDisplay(display);
  sendMain('snip:state', true); // light the ⧉ button for the hold-⌃⌥ path too, not just ⌘⇧S
  const b = display.bounds;
  // The overlay was already created at this display's bounds (macOS clamps its top below the menu
  // bar, e.g. y:0→30, and it STAYS there). Re-calling setBounds every down re-triggers that clamp
  // asynchronously, so the getBounds read right after was STALE — the box started at the wrong spot
  // and only snapped right on the first move (which reads the settled bounds). Only reposition if the
  // window is actually on the wrong display/size; otherwise read its already-settled origin.
  const cur = win.getBounds();
  // macOS clamps the overlay's top below the menu bar and LEAVES it there, so a y that differs from
  // the display's is CORRECT on that platform — testing it would re-set the bounds on every press and
  // re-trigger the async clamp, which is the stale read this comment is about. Windows has no such
  // intentional offset, but it does clamp HEIGHT to the work area (1080 asked → 1032 given, measured
  // 2026-08-08), and an x/width-only test can never see that. So the two platforms get the test that
  // is true for them, and the reposition goes through the resizable dance so the read below is settled
  // rather than stale — that stale origin is what made the armed ring appear away from the cursor for
  // a frame and then slide to it, on Windows only. (jek, 2026-08-08)
  const wrongBounds = IS_WIN
    ? (cur.x !== b.x || cur.y !== b.y || cur.width !== b.width || cur.height !== b.height)
    : (cur.x !== b.x || cur.width !== b.width);
  if (wrongBounds) setFixedWindowBounds(win, { x: b.x, y: b.y, width: b.width, height: b.height });
  const wb = win.getBounds();
  // Keep the overlay out of its own reading. The live preview OCRs WHILE this is on screen, so the
  // box wash, border and handles land inside the crop — and the crop's top pad pulls the border in even when the
  // box was drawn clear of the text. Windows sets this once in ensureSnipWindows (setProtect(win,
  // IS_WIN)); mac left it off so a normal ⌘⇧S drag stays visible in a screen recording, but that
  // decision never accounted for the hold-drag, which reads with the overlay up the whole time.
  // showSnipWindows re-derives this per snip, so the ⌘⇧S path is unaffected.
  setProtect(win, true);
  win.webContents.send('snip:reset', { external: true, combo });
  // Click-through for the ENTIRE session — the hook drives the box, not the overlay's own mouse
  // handling, so the game underneath must keep receiving every click/move throughout.
  win.setIgnoreMouseEvents(true, { forward: true });
  win.showInactive();
  hidePillFromCapture(); // keep our own pill text out of the OCR if the box overlaps it
  win.webContents.send('extern:start', { x: x - wb.x, y: y - wb.y });
  syncEscape(); // the session is live now — arm Esc so a lost release can't strand it
}

function mouseHookMove(x, y) {
  if (!externSession) return;
  const now = Date.now();
  if (now - externMoveThrottle < 16) return; // ~60fps, matches the hook's own move throttle
  externMoveThrottle = now;
  const { win, startX, startY } = externSession;
  if (win.isDestroyed()) { abortExternSession(); return; }
  const b = win.getBounds(); // real window origin (macOS clamps it below the menu bar) — see mouseHookDown
  const gb = { x: Math.min(startX, x), y: Math.min(startY, y), width: Math.abs(x - startX), height: Math.abs(y - startY) };
  win.webContents.send('extern:update', { x: gb.x - b.x, y: gb.y - b.y, width: gb.width, height: gb.height });
  // Live preview like the ⌘⇧S drag has — the renderer can't drive it here (it's fully click-through),
  // so main OCRs the current box once the drag settles and pushes the reading to the overlay.
  // Windows used to skip this: the capture alone cost ~400ms (desktopCapturer grabbed every screen at
  // full res) so previewing mid-drag stuttered the whole PC. BitBlt made that ~15ms, so it's back —
  // just with a longer settle, because tesseract-WASM is slower than macOS's Vision engine.
  // computePreview's own previewBusy guard drops any tick that lands while a read is still running.
  clearTimeout(externPreviewTimer);
  externPreviewTimer = setTimeout(() => runExternPreview(gb, b), IS_WIN ? 260 : 180);
}

// Tear down a half-finished ⌃⌥ session (the native helper crashed mid-drag, or the overlay windows
// got rebuilt on a display change). Without this, externSession stays truthy forever → mouseHookDown
// refuses every future drag, AND the pill stays hidden-from-capture for the rest of the run.
function abortExternSession() {
  if (!externSession) return;
  externSession = null;
  sendMain('snip:state', false);
  syncEscape();
  clearTimeout(externPreviewTimer);
  closeSnipWindows();       // hides the overlay + restores capture (calls applyContentProtection)
  applyContentProtection(); // belt-and-suspenders if no snip window was open to restore it
}

let externPreviewTimer = null;
async function runExternPreview(gb, winBounds) {
  if (!externSession) return;
  const rect = { x: gb.x - winBounds.x, y: gb.y - winBounds.y, width: gb.width, height: gb.height };
  if (gb.width < 20 || gb.height < 12) { // box shrank below readable — hide the stale card (renderer path does this too)
    externSession.win.webContents.send('extern:preview', { status: 'hide', rect });
    return;
  }
  // Immediate feedback so the box doesn't sit silent through the OCR+translate (felt "so delayed").
  externSession.win.webContents.send('extern:preview', { status: 'reading', rect });
  const result = await computePreview(gb, null);
  if (!externSession) return;
  if (result && result.busy) { // a read is already in flight — retry shortly (mirror the ⌘⇧S path) so a held box doesn't stall
    clearTimeout(externPreviewTimer);
    externPreviewTimer = setTimeout(() => runExternPreview(gb, winBounds), IS_WIN ? 260 : 180);
    return;
  }
  if (!result || !result.en) { // OCR found nothing usable here
    externSession.win.webContents.send('extern:preview', { status: 'unreadable', rect });
    return;
  }
  externSession.lastPreview = { en: result.en, gb }; // let release skip a duplicate OCR (see mouseHookUp)
  externSession.win.webContents.send('extern:preview', { result, rect });
}

// Returns true when the release actually kicked off a read, so callers know not to flash the idle
// hint (see startWinSnip): '⌘⇧S' → 'Reading…' → 'Translating…' inside one frame made the pill resize
// three times in a blink, which read as a stutter.
// ---- Sweep, release, tap the KEYS again: keep the word you just snipped ------------------------
// TAP means the MODIFIER, never the mouse button. native/mousehook.swift's event mask is
// flagsChanged | mouseMoved and nothing else — a click is not in it, and what arrives here as
// `down`/`up` is ⌃⌥ pressed and ⌃⌥ released. The snip gesture has never involved the mouse button on
// either platform (Windows runs the same wire protocol through winkeyhook). Called "click again" it
// reads as a mouse gesture and then does nothing at all, which is exactly what jek hit (2026-08-15,
// twice: once because the card did not exist yet, once because he was clicking a button nobody is
// listening to).
//
// So the gesture is: hold ⌃⌥, sweep the box, release to fire the snip — then TAP ⌃⌥ once more
// without moving. That tap is already free: a modifier tap with no sweep in it hits the
// `bounds.width < 10` guard below and has always been discarded in silence.
//
// Window, not a mode: a tap much later is somebody doing something else, and keeping a word they
// snipped a minute ago would be a save nobody asked for.
const SNIP_KEEP_MS = 1200;
// …and the other way round, which is the case that actually happens. The tap lands a fraction of a
// second after the release, while the box is still being READ and translated — seconds before there
// is any card to keep (measured 2026-08-15: jek tapped, nothing was kept, because translateOnce only
// files the card after the OCR and the network call). So the tap ARMS the intent and the card is
// kept when it arrives. Generous window: it is bounded by the snip it belongs to, not by a clock —
// a fresh drag clears it (see mouseHookDown), so it can never leak into the next one.
const SNIP_ARM_MS = 15000;
let lastSnipCard = null; // { payload, at } — the card the last drag produced
let keepArmedAt = 0;     // when a tap asked for the NEXT card to be kept
// When a snip last FIRED (the box was taken), whatever style produced it. In 'drag' style the trigger
// press is not a hold, so there is no release edge to hang the keep gesture on - the second press
// itself has to mean it, and this is what tells a "keep" press apart from "start another snip".
let lastSnipFiredAt = 0;
const KEEP_TAP_MS = 1500;

function keepCard(card) {
  const en = String(card.en || '').trim();
  // A sentence has no single word to keep, and putting a whole line in a vocabulary list is the thing
  // the ★ on the card refuses to do too (it opens the word picker instead). Say which gesture does
  // work rather than silently doing nothing.
  if (!isOneWord(en)) { setHintState('Snip one word to keep it — or tap a word on the card'); return true; }
  const detail = wordStudyDetail(en);
  const entry = { word: en, meaning: card.th || '', reading: card.pronunciation || '', ts: Date.now(),
    src: en, seen: 1, from: 'snip' };
  if (detail.pos) entry.pos = detail.pos;
  if (detail.senses && detail.senses.length > 1) entry.senses = detail.senses;
  if (detail.defs) entry.defs = detail.defs;
  const res = addVocabEntry(entry);
  if (res === 'full') { setHintState(`Collection is full (${MAX_VOCAB})`); return true; }
  // 'dup' lights the same star as 'added' — the question the gesture asks is "is this word mine",
  // and the answer is yes either way (the same reasoning saveHoverWord's own comment gives).
  setHintState(res === 'dup' ? `★ ${en} — already kept` : `★ ${en}`);
  // No extra channel: addVocabEntry already broadcasts vocab:changed, which is what every star in
  // every window repaints from. A second message would be a second mechanism for one fact.
  return true;
}

// The tap. Two orders are possible and both are the same gesture: the card is already here (a slow
// tap, or a cached re-read that answered instantly), or it is still coming.
function keepLastSnip() {
  if (DEBUG) console.error('snip keep: modifier tap', JSON.stringify({ haveCard: !!lastSnipCard,
    age: lastSnipCard ? Date.now() - lastSnipCard.at : null }));
  if (lastSnipCard && (Date.now() - lastSnipCard.at) <= SNIP_KEEP_MS) {
    const card = lastSnipCard.payload;
    lastSnipCard = null; // one tap, one save — a second tap must not re-run this
    keepArmedAt = 0;
    return keepCard(card);
  }
  keepArmedAt = Date.now();
  setHintState('★ keeping the word this reads…');
  return true;
}

// Called by translateOnce the moment a card exists. Returns whether it consumed the arm.
function keepArmedCard(payload) {
  if (!keepArmedAt || Date.now() - keepArmedAt > SNIP_ARM_MS) return false;
  keepArmedAt = 0;
  lastSnipCard = null; // it has been dealt with; a later tap must not keep it twice
  return keepCard(payload);
}

function mouseHookUp(x, y) {
  if (!externSession) return false;
  const { win, startX, startY, lastPreview } = externSession;
  externSession = null;
  sendMain('snip:state', false);
  syncEscape();
  clearTimeout(externPreviewTimer); // no late preview after release
  if (!win.isDestroyed()) {
    win.webContents.send('extern:finish');
    win.setIgnoreMouseEvents(false); // restore default capture so the next normal ⌘⇧S drag still works
  }
  closeSnipWindows(); // same hide/reset/Escape-unregister path a normal snip uses
  const bounds = {
    x: Math.min(startX, x),
    y: Math.min(startY, y),
    width: Math.abs(x - startX),
    height: Math.abs(y - startY),
  };
  // A tap with no drag in it. Until now that was always a slip and was ignored; a tap that lands
  // within SNIP_KEEP_MS of the card the LAST drag produced is the keep gesture (jek, 2026-08-15).
  // Everything else still ends here exactly as before.
  if (bounds.width < 10 || bounds.height < 10) return keepLastSnip(); // a stray tap, not a drag — stay silent (jek 2026-07-26)
  // Release over the SAME box the live preview just read → reuse that OCR: instant, no re-capture.
  // Both calls below hand over RAW bounds: translateOnce pads internally before it captures, so
  // passing padBounds(bounds) padded twice and the release capture came out two pads taller than the
  // box actually drawn — pulling in whatever line sat above or below it. snip:complete always passed raw.
  const near = (a, b) => Math.abs(a - b) <= 8;
  if (lastPreview && near(bounds.x, lastPreview.gb.x) && near(bounds.y, lastPreview.gb.y)
      && near(bounds.width, lastPreview.gb.width) && near(bounds.height, lastPreview.gb.height)) {
    translateOnce(bounds, lastPreview.en);
    lastSnipFiredAt = Date.now();
    return true;
  }
  hidePillFromCapture(); // closeSnipWindows just restored it — re-hide for the release capture (80ms lets it apply)
  setTimeout(() => translateOnce(bounds), 80); // same settle delay snip:complete uses
  lastSnipFiredAt = Date.now();
  return true;
}

function startMouseHook() {
  if (process.platform !== 'darwin') return;
  if (mouseHookProc) return;
  // No hold-style trigger set → the gesture is off, and running a system-wide event tap to listen
  // for a combo nobody armed is pure cost (plus an Accessibility prompt for a feature not in use).
  const mods = snipHoldMods();
  if (!mods) return;
  mouseHookMods = mods;
  let proc;
  try {
    proc = spawn(MOUSEHOOK_BIN, [mods]);
  } catch (err) {
    // Not the same thing as the Accessibility refusal below, which has its own dialog. This is the
    // helper being missing or unrunnable, and without a word the hold trigger is just a gesture that
    // does nothing — indistinguishable from not having pressed it.
    console.error('mousehook spawn failed:', err);
    setHintState('Hold-drag helper failed to start — use the ⧉ button or set a key trigger');
    return;
  }
  mouseHookProc = proc;
  mouseHookBuf = '';
  proc.stdout.on('data', (d) => {
    mouseHookBuf += d.toString('utf8');
    let idx;
    while ((idx = mouseHookBuf.indexOf('\n')) !== -1) {
      const line = mouseHookBuf.slice(0, idx).trim();
      mouseHookBuf = mouseHookBuf.slice(idx + 1);
      handleMouseHookLine(line);
    }
  });
  proc.stderr.on('data', (d) => { if (DEBUG) console.error('mousehook stderr:', d.toString()); });
  proc.on('exit', (code) => {
    if (mouseHookProc === proc) mouseHookProc = null;
    abortExternSession(); // the helper died — if a drag was mid-flight, don't leave it (and the pill's capture-hide) stuck

    // code 2 = PERM_NEEDED (already handled via stdout line above) — don't respawn-loop on that;
    // any other unexpected exit gets one retry after a short backoff (a crash shouldn't need a
    // full app restart to recover, but this must never turn into a tight respawn loop).
    if (code === 2) return;
    if (mouseHookRespawnTimer) return;
    mouseHookRespawnTimer = setTimeout(() => {
      mouseHookRespawnTimer = null;
      startMouseHook();
    }, 3000);
  });
  proc.on('error', (err) => console.error('mousehook process error:', err));
}

// The arming modifiers live in the helper's argv, so changing the trigger means respawning it. Called
// after anything that can rewrite settings.shortcuts; a no-op when the set didn't actually move,
// which is most calls (any other row being re-keyed lands here too).
function applySnipHold() {
  // Windows keeps its arming set inside the hook rather than in an argv, so startWinComboHook can
  // decide for itself whether anything moved — it compares against winComboMods and stops the hook
  // outright when the trigger stops being modifier-only.
  if (IS_WIN) { startWinComboHook(); return; }
  if (process.platform !== 'darwin') return;
  const mods = snipHoldMods();
  if (mods === mouseHookMods) return;
  stopMouseHook();
  mouseHookMods = '';
  startMouseHook(); // returns straight back out when the new trigger is press-style
}

function stopMouseHook() {
  if (mouseHookRespawnTimer) { clearTimeout(mouseHookRespawnTimer); mouseHookRespawnTimer = null; }
  if (!mouseHookProc) return;
  const proc = mouseHookProc;
  mouseHookProc = null;
  try { proc.kill(); } catch {}
}

// ---- Windows modifier-only snip trigger: same engine as macOS, different plumbing ----
// The macOS tap streams cursor moves itself. WH_KEYBOARD_LL reports only the combo's press/release,
// so the box is driven by polling the cursor in between. Deliberately NOT a second low-level hook:
// with no button held there is nothing to swallow, and polling keeps the input path one hook lighter.
const COMBO_POLL_MS = 16; // ~60fps — matches the move throttle in mousehook.swift
let comboPollTimer = null;
let winComboMods = '';     // the modifier set the hook is currently armed for; '' = not running
let winComboHolding = false; // a 'hold' session opened by THIS hook is in progress

function stopComboPoll() {
  if (comboPollTimer) { clearInterval(comboPollTimer); comboPollTimer = null; }
}

function startWinComboHook() {
  if (!IS_WIN) return;
  // This used to run unconditionally, which is how Windows ended up with TWO snip triggers: the
  // registered shortcut AND an always-on ⌃⌥ that no Settings row admitted to. macOS gated the same
  // thing on snipHoldMods() from the start, so only Windows had the extra one. Now both platforms ask
  // the same question — is the snip trigger something the OS can deliver? — and the hook runs only
  // when the answer is no. (jek, Win11 2026-08-07)
  const mods = snipHoldMods();
  if (!mods) { stopWinComboHook(); return; }
  if (mods === winComboMods) return; // already armed for exactly this trigger
  const ok = startComboHook({
    down: () => {
      // Not a hold: the OS cannot report a modifier-only accelerator at all, so for 'drag'/'point'
      // this edge IS the press. Hand it to the same entry point a registered shortcut would have hit
      // and let doSnipStart pick the style — the alternative is a trigger that works in one style and
      // does nothing in the others.
      if (effectiveSnipStyle() !== 'hold') { doSnipStart(); return; }
      winComboHolding = true;
      const p = screen.getCursorScreenPoint();
      mouseHookDown(p.x, p.y, true);
      // Refused (a snip/CC session is already open, no overlay for this display) — don't spin a poll
      // that would just call into a dead session 60 times a second.
      if (!externSession) return;
      stopComboPoll();
      comboPollTimer = setInterval(() => {
        if (!externSession) { stopComboPoll(); return; } // aborted under us (display change, Escape)
        const q = screen.getCursorScreenPoint();
        mouseHookMove(q.x, q.y);
      }, COMBO_POLL_MS);
    },
    up: () => {
      // In the press styles the release is not a shutter, it is just the hand coming off the keys —
      // and in 'drag' it lands in the MIDDLE of the mouse-drag the press just armed, so firing here
      // would cut the capture short. Only a session this hook itself opened ends here; the flag is
      // what says so, since by now externSession may belong to the drag hook instead.
      if (!winComboHolding) return;
      winComboHolding = false;
      stopComboPoll();
      const p = screen.getCursorScreenPoint();
      mouseHookUp(p.x, p.y);
    },
  }, mods);
  if (!ok) {
    winComboMods = '';
    console.warn(`winkeyhook: hold trigger (${mods}) unavailable — snip still works from the pill's ⧉ button`);
    return;
  }
  winComboMods = mods;
}

function stopWinComboHook() {
  if (!IS_WIN || !winComboMods) return;
  stopComboPoll();
  winComboHolding = false;
  try { stopComboHook(); } catch { /* non-fatal */ }
  winComboMods = '';
}

// Single entry point translateOnce/livePoll call for any crop — picks Vision on
// macOS when it's available and returns real text, otherwise falls back to the
// tesseract renderer path (Windows/Linux, or Vision failure/missing binary).
// Tesseract wants glyphs roughly 30px tall. A snipped UI label is often 11-14px, and at that size it
// reads as nothing at all — empty string, confidence 0, which the app then reports as "Blurry, try a
// bigger box" even though the capture is pin sharp (dragging a box around the "New folder" desktop
// icon did exactly that). Upscaling the crop first is the standard fix and costs a millisecond.
// Tesseract wants glyphs around 30px tall. UI labels and subtitles are often 11-14px, and at that
// size it hands back an empty string at confidence 0 — which the app then reports as "Blurry, try a
// bigger box" even though the capture is pin sharp. Upscaling first costs about a millisecond.
// How tall a LINE of text is in this crop, from horizontal bands of ink. The background is taken as
// the most common luminance (true for a UI panel, a speech bubble or a subtitle plate alike), a row
// counts as ink when enough of it sits far from that, and consecutive ink rows are one band. The
// median band is the line height. Returns 0 when there are no bands to measure.
function inkLineHeight(image) {
  const { width, height } = image.getSize();
  if (!width || !height) return 0;
  const px = image.toBitmap(); // BGRA
  const n = width * height;
  const lum = new Uint8Array(n);
  const hist = new Uint32Array(256);
  for (let i = 0, p = 0; i < n; i++, p += 4) {
    const g = (px[p + 2] * 299 + px[p + 1] * 587 + px[p] * 114) / 1000 | 0; // Rec. 601 luma
    lum[i] = g;
    hist[g]++;
  }
  let bg = 0, best = -1;
  for (let v = 0; v < 256; v++) if (hist[v] > best) { best = hist[v]; bg = v; }

  const minInk = Math.max(1, Math.round(width * 0.02));
  const bands = [];
  let run = 0;
  for (let y = 0; y < height; y++) {
    let ink = 0;
    const row = y * width;
    for (let x = 0; x < width; x++) if (Math.abs(lum[row + x] - bg) > 40) ink++;
    if (ink > minInk) run++;
    else if (run) { bands.push(run); run = 0; }
  }
  if (run) bands.push(run);
  if (!bands.length) return 0;
  bands.sort((a, b) => a - b);
  return bands[bands.length >> 1];
}

// Scale so a LINE of text lands near this tall. Both engines want roughly the same thing and neither
// gets it from the raw crop: measured on the Windows overlay pill (11px glyphs) Windows.Media.Ocr
// read NOTHING at 1x and "Ctrl+Alt" at 4x.
const OCR_TARGET_LINE_PX = 40;
// Upscaling a whole frame is quadratic. The live poll hands this full-screen captures, and a 4x pass
// over 1920x1080 is 33 megapixels of resize per tick — so cap the result instead of the input.
const OCR_MAX_SCALED_PX = 8e6;

// The scale comes from the TEXT height, not the crop height. The old rule read the crop: a 40px-tall
// box holding 28px letters was still upscaled 3x, and measured on jek's webtoon crop (2026-08-10)
// that made the read worse, not better — Windows.Media.Ocr went from "PIS&UISE" at 1x to "P15&U15E"
// at 3x, turning S into 5 and I into 1. Measuring the ink puts the same crop at lineH 30 and leaves
// it alone, while the 11px pill still scales 4x. Falls back to the crop-height rule when there is no
// ink to measure.
function ocrScaled(image) {
  const { width, height } = image.getSize();
  if (!height) return image;
  const lineH = inkLineHeight(image);
  let s;
  if (lineH > 0) {
    s = Math.min(4, Math.max(1, Math.round(OCR_TARGET_LINE_PX / lineH)));
  } else {
    if (height >= 120) return image;
    // Aim for ~120px of crop height, not 60: measured on the "New folder" icon, 2x scored 45 and 4x
    // scored 69 on the same binarisation.
    s = Math.min(4, Math.max(2, Math.ceil(120 / height)));
  }
  while (s > 1 && width * height * s * s > OCR_MAX_SCALED_PX) s--;
  if (s <= 1) return image;
  return image.resize({ width: width * s, height: height * s, quality: 'best' });
}

// Keep only the brightest slice of the image as ink, everything else goes white.
//
// Game text — and Windows' own desktop icon labels — is light with a dark outline sitting over a
// photo or a scene: mid-tones everywhere, no page. Measured on the "New folder" icon: raw read
// nothing (confidence 0-4), grey nothing, Otsu (either polarity) nothing, this at cutoff 200 read
// "Mew folder" at confidence 69. Otsu fails because the split it finds is scene-vs-scene, not
// text-vs-everything; text is a small bright minority, so a high percentile finds it instead.
function binarizeBright(image, pct = 0.88) {
  const { width, height } = image.getSize();
  const px = image.toBitmap(); // BGRA
  const n = width * height;
  const hist = new Uint32Array(256);
  const grey = new Uint8Array(n);
  for (let i = 0, p = 0; i < n; i++, p += 4) {
    const g = (px[p + 2] * 299 + px[p + 1] * 587 + px[p] * 114) / 1000 | 0; // Rec. 601 luma
    grey[i] = g;
    hist[g]++;
  }
  // Cutoff = the pct-th percentile, floored at 140 so a washed-out crop can't turn half the frame
  // into ink.
  let seen = 0, cut = 255;
  const want = n * pct;
  for (let v = 0; v < 256; v++) {
    seen += hist[v];
    if (seen >= want) { cut = v; break; }
  }
  cut = Math.max(140, cut);

  const out = Buffer.alloc(n * 4);
  for (let i = 0, p = 0; i < n; i++, p += 4) {
    const v = grey[i] > cut ? 0 : 255; // bright pixels become black ink on a white page
    out[p] = v; out[p + 1] = v; out[p + 2] = v; out[p + 3] = 255;
  }
  return nativeImage.createFromBitmap(out, { width, height });
}

// How much of a read is real WORDS, judged by the dictionary the app already ships for
// point-at-a-word. Returns { known, total }; total 0 means "nothing here decides anything".
//
// Only the languages a dictionary actually ships for. Without the guard lookupAt's normLang would
// quietly answer a Chinese or Korean read out of the JAPANESE dictionary and score it as nonsense.
function dictScore(text, lang) {
  const out = { known: 0, total: 0 };
  if (!HOVER_LANGS[lang] || !text) return out;
  for (const tok of String(text).split(/\s+/)) {
    const w = tok.replace(/^[^\p{L}\p{N}\p{M}]+|[^\p{L}\p{N}\p{M}]+$/gu, '');
    if (w.length < 2) continue; // "a", "8", punctuation — true either way, so they decide nothing
    out.total++;
    const hit = hoverDict.lookupAt(w, 0, lang);
    if (!hit) continue;
    // English: the match has to cover the WHOLE token. lookupAt answers a hover question — "what
    // word starts at this character" — so it is happy to match a PREFIX, and a prefix match is
    // exactly what a misread token looks like. Measured: "PIS&UISE" scored 1/1 known, because `&`
    // ends an English word and `pis` is in the dictionary. Japanese is left on longest-match: a
    // whitespace-split jpn token is a whole line and is never covered by one word.
    if (lang === 'eng' && hit.length !== Array.from(w).length) continue;
    out.known++;
  }
  return out;
}

// The native engine read SOMETHING — but is it words? Confidence cannot answer that here, and both
// halves of it are broken in opposite directions: winOcrRecognize hands back a flat 90 for anything
// non-empty (Windows.Media.Ocr reports no per-read score), so the gate below can never reject a
// native read, while tesseract scores a CORRECT read of stylised text as low as 37.
//
// Measured on the comic lettering jek hit on 2026-08-10 (a webtoon speech bubble, black on white,
// hand-lettered caps). Windows read the word as "PIS&UISE" alone and "MERELY A PISCUISE" in
// context; tesseract read "DISGUISE" and "MERELY A DISGUISE" — confidence 37 and 89. Picking by
// confidence ships the wrong one every time; picking by how many words a dictionary recognises
// ships the right one. That is the same judgement recognizeBoxes already makes for hover, and the
// reason it exists there: the native engine's own score is not a score.
//
// Only pays for the second read when the first one fails the dictionary, so clean UI text, chat and
// documents cost nothing extra.
//
// The trigger is ONE unknown token, not a ratio. A ratio was tried first and measured wrong on the
// case that started this: "MERELY A PISCUISE" inside the full bubble scores 11 known out of 12, which
// clears any sane ratio and ships the one word that was actually broken. One bad word in a sentence
// is the normal shape of this failure, so one bad word has to be enough to ask again.
async function withSecondOpinion(scaled, native) {
  if (!native) return native;
  // English only: this is the pair that was measured, and a whitespace-split token list is the wrong
  // question to ask of Japanese, which lookupAt answers by longest-match from position 0.
  const lang = settings.sourceLang;
  if (lang !== 'eng') return native;
  // Tesseract already answered, so there is no second engine to ask — but the dictionary still has
  // something to say, and it is the half that matters. Tesseract's SCORE is not a measure of whether
  // it read the words right; it is a measure of how much context it had. Measured on jek's
  // "assurances" crop (2026-08-31), tesseract read the word EXACTLY RIGHT at confidence 53 / 23 / 0
  // across 1x / 2x / 3x, while the identical word inside its own line scored 95. A lone word is the
  // shape that scores badly, not the shape that reads badly — and a lone word is precisely what
  // "translate this one word" hands us, so the confidence gate was rejecting the app's own core
  // gesture whenever Windows.Media.Ocr came back empty and left tesseract holding the read.
  //
  // Vouching is deliberately strict: EVERY token has to be a whole-token dictionary hit. One unknown
  // word and this does nothing, so real garbage still meets the gate (and looksLikeGarbage after it).
  if (native.engine === 'tesseract') {
    const own = dictScore(native.text, lang);
    return (own.total && own.known === own.total) ? { ...native, arbitrated: true } : native;
  }
  const a = dictScore(native.text, lang);
  if (!a.total || a.known === a.total) return native;

  const alt = await recognizeTesseract(scaled.toPNG());
  if (!alt || !alt.text || !alt.text.trim()) return native;
  const b = dictScore(alt.text, lang);
  if (DEBUG) console.log(`second opinion: native ${a.known}/${a.total} vs tesseract ${b.known}/${b.total}`);
  // Judged on the count of UNKNOWN tokens, not on known ones: the two reads rarely split the same
  // text into the same number of tokens (Windows read "IRON IS", tesseract "IRON |S", and the
  // one-character token is dropped by both), so equal known counts do not mean equal quality —
  // 11 known of 12 lost to 11 of 11 on the bubble that started this. Ties keep the native read: it
  // is faster and right far more often, and a tie is the dictionary declining to choose.
  const unknownA = a.total - a.known;
  const unknownB = b.total - b.known;
  // `arbitrated` travels with the winner so the confidence gate downstream knows this read was
  // chosen on its WORDS and must not be re-judged on tesseract's score — see lowConfidence().
  if (unknownB < unknownA) return { ...alt, arbitrated: true };
  if (unknownB === unknownA && b.known > a.known) return { ...alt, arbitrated: true };
  return native;
}

// Read a crop, and if the plain read comes back unusable, try again with the bright-text
// binarisation. Dark-text-on-light (web pages, chat, documents) passes on the first attempt and
// costs nothing extra; light-text-on-scene only pays the second pass when it actually needs it.
//
// `arbitrate` turns on the dictionary second opinion above. The snip path asks for it — one crop,
// one translation, accuracy is the whole product. The live poll does not: it fires on a timer and
// the extra tesseract pass would land on every frame of a busy scene.
async function recognizeImage(image, arbitrate = false) {
  const scaled = ocrScaled(image);
  const first = await recognize(scaled.toPNG());
  if (first.text && first.text.trim() && first.confidence >= MIN_CONFIDENCE) {
    return arbitrate ? withSecondOpinion(scaled, first) : first;
  }

  const second = await recognize(binarizeBright(scaled).toPNG());
  const firstScore = (first.text || '').trim() ? first.confidence : -1;
  const secondScore = (second.text || '').trim() ? second.confidence : -1;
  const best = secondScore > firstScore ? second : first;
  return arbitrate ? withSecondOpinion(scaled, best) : best;
}

async function recognize(png) {
  if (process.platform === 'darwin') {
    try {
      const vision = await visionRecognize(png, settings.sourceLang);
      if (vision.text && vision.text.trim()) {
        if (DEBUG) console.log('OCR via Vision');
        // Who answered, so withSecondOpinion knows whether a second opinion is even available.
        return { ...vision, engine: 'vision' };
      }
    } catch (err) {
      console.error('Vision OCR failed, falling back to tesseract:', err);
    }
  }
  if (IS_WIN) {
    try {
      const native = await winOcrRecognize(png, settings.sourceLang);
      if (native.text && native.text.trim()) {
        if (DEBUG) console.log('OCR via Windows.Media.Ocr');
        return { ...native, engine: 'winocr' };
      }
    } catch (err) {
      console.error('Windows OCR failed, falling back to tesseract:', err);
    }
  }
  // Only fall back to an engine that can actually read this language. Tesseract is handed one
  // traineddata by name and the build ships four; asking it for `tha` fetches a file that isn't there,
  // and the worker then answers nothing at all — after the 30s ceiling in recognizeTesseract. A blank
  // result now is the same answer, thirty seconds earlier.
  if (!TESS_LANGS.has(settings.sourceLang)) {
    if (DEBUG) console.log(`OCR: no engine left for ${settings.sourceLang} — Vision was the only one that reads it`);
    return { text: '', confidence: 0, engine: 'none' };
  }
  if (DEBUG) console.log('OCR via tesseract');
  const tess = await recognizeTesseract(png);
  // Cleaned here, not at the call sites: everything downstream (translation, history, vocab, the
  // garbage check) has to see the same text, and this is the one place a tesseract read is minted.
  return { ...tess, text: tidyCjkRead(tess.text, settings.sourceLang), engine: 'tesseract' };
}

ipcMain.on('ocr:result', (_e, { id, text, confidence, debugPng, error }) => {
  if (error) console.error('OCR error:', error);
  const resolve = ocrPending.get(id);
  if (!resolve) return;
  ocrPending.delete(id);
  resolve({ text: text || '', confidence: confidence || 0, debugPng });
});

// Diagnostic dump (GT_DEBUG only): the raw + preprocessed crop and what OCR read,
// so a bad read can be inspected. Off in normal use.
const DEBUG_DIR = path.join(app.getPath?.('temp') || '/tmp', 'gametranslator-debug');
function dumpOcrDebug(rawPng, res, extra) {
  if (!DEBUG) return;
  try {
    fs.mkdirSync(DEBUG_DIR, { recursive: true });
    if (rawPng) fs.writeFileSync(path.join(DEBUG_DIR, 'raw.png'), rawPng);
    if (res.debugPng) fs.writeFileSync(path.join(DEBUG_DIR, 'preprocessed.png'), Buffer.from(res.debugPng));
    const report = [
      'confidence: ' + Math.round(res.confidence),
      'kept-confidence: ' + (extra.keptConfidence != null ? Math.round(extra.keptConfidence) : 'n/a'),
      'garbage-filter: ' + extra.garbage,
      '--- OCR text ---',
      res.text,
    ].join('\n');
    fs.writeFileSync(path.join(DEBUG_DIR, 'read.txt'), report, 'utf8');
    console.log('OCR debug dumped to', DEBUG_DIR);
  } catch (err) {
    console.error('debug dump failed:', err);
  }
}

ipcMain.on('ocr:ready', () => console.log('OCR worker ready'));

// How much of a display the overlay canvas covers.
//
// macOS: the WORK AREA. The menu bar owns the top of the screen and an overlay drawn under it is
// simply lost — this project has had that bug once already ("warped the pill off the top of the
// screen and lost it behind the menu bar").
//
// Windows: the WHOLE DISPLAY. Measured on this machine: bounds 1920x1080, workArea 1920x1032 — the
// missing 48px is the taskbar, which a fullscreen game covers. So the canvas stopped 48px short of
// the screen exactly where a game draws its subtitles, the pill could not be parked in that strip,
// and every dock row sat 48px higher than the same row on a Mac of the same resolution. The overlay
// is click-through everywhere except the pill itself, so covering the taskbar costs nothing beyond
// the few pixels the pill is actually sitting on. (jek, 2026-07-31)
function overlayArea(display) {
  return IS_WIN ? display.bounds : display.workArea;
}

// Windows CLAMPS A NON-RESIZABLE WINDOW TO THE WORK AREA. Measured: asking for 1920x1080 returned
// 1920x1032 from `new BrowserWindow` itself, before any of our code ran, and no later resize event
// ever fired — the taskbar-shaped gap was baked in at creation and `resizable: false` then froze it
// there. Lifting the lock just long enough to set the bounds is what buys back the last 48px. The
// window is never resizable at any moment a user could reach, and macOS is left on the plain path
// since it has nothing to work around.
// Windows CLAMPS a resizable:false window to the work area, both at creation and on setBounds, so a
// full-screen overlay silently loses the taskbar strip. Measured 2026-08-08 on both displays here:
// asked 1920×1080, got 1920×1032; the same window after this dance reports the full 1080.
// The fix was written for the pill's window and — for a year — applied only there. Every fixed-size
// overlay this app makes needs it, which is why it takes a window now instead of assuming one.
function setFixedWindowBounds(win, rect) {
  if (!win || win.isDestroyed()) return;
  if (!IS_WIN) { win.setBounds(rect); return; }
  win.setResizable(true);
  win.setBounds(rect);
  win.setResizable(false);
}
function setOverlayBounds(rect) { setFixedWindowBounds(mainWindow, rect); }

// The window is a FIXED, FULL-SCREEN transparent canvas — it covers the whole overlay area and
// never moves or resizes. The pill/panel live inside it and are dragged around purely in CSS
// (see the drag handler in index.js), so the pill can be parked anywhere on screen without the
// old "window can't slide off the top" wall. Everywhere the cursor isn't over real content, the
// window is click-through so the game underneath still gets the clicks.
function createMainWindow() {
  // The monitor you last parked it on, primary if there isn't one or it's gone. loadSettings() runs
  // before this (see the ready handler), so settings.pillDisplay is already final here.
  const remembered = rememberedDisplay();
  const wa = overlayArea(remembered || screen.getPrimaryDisplay());
  // Which screen the overlay opened on, and why. Every other window at these coordinates is a
  // per-display SNIP overlay, so from outside the process the two are indistinguishable — this line
  // is the only way to tell "it opened where I left it" from "it opened on the primary again".
  if (DEBUG) console.log('overlay opens on', remembered ? 'REMEMBERED display' : 'primary display', JSON.stringify(wa));
  mainWindow = new BrowserWindow({
    width: wa.width,
    height: wa.height,
    x: wa.x,
    y: wa.y,
    resizable: false,
    alwaysOnTop: true,
    frame: false,
    transparent: true,
    hasShadow: false,
    skipTaskbar: true,
    backgroundColor: '#00000000',
    // The overlay lives OVER another app, so it is almost never the active app. Without this, macOS
    // spends the first click on an inactive window just activating us and never delivers it to the
    // page — every "the pill ignored my click" report starts here. Deliver it straight to the UI.
    acceptFirstMouse: true,
    // WINDOWS: never let a click on the pill ACTIVATE us (WS_EX_NOACTIVATE). A focusable overlay is
    // taken foreground by the very first click, the game drops to background, and a game that mutes
    // itself when it isn't the active app goes silent the moment you open History or Settings (jek
    // 2026-08-29). WS_EX_NOACTIVATE blocks activation only — mouse messages still arrive, which is
    // why the hover window (createHoverWindow) and the snip overlays already run this way. Keyboard
    // is the one thing it costs, so `ui:focusable` lifts it for exactly as long as a text field is
    // focused and hands the foreground straight back afterwards.
    // macOS keeps the old behaviour: focusable:false there HID the window and did not stop the
    // focus-steal anyway (that is the revert the ui:focusable no-op used to record).
    focusable: !IS_WIN,
    webPreferences: {
      preload: path.join(__dirname, 'preload-main.js'),
      contextIsolation: true,
      nodeIntegration: false,
      // How capabilities.js reaches the preload. A preload runs SANDBOXED, where `require` resolves
      // only Electron's own polyfills — requiring a file of ours there silently kills the whole
      // preload, and with it every window.api the page depends on (measured 2026-08-15: window.api
      // came back undefined and the panel rendered with no controls at all). additionalArguments is
      // the sanctioned way across that line: main stays the ONE place the rule is written, and the
      // preload only carries the answer over. Anything added here must be a primitive — it arrives
      // as a command-line string.
      additionalArguments: [`--gloss-hover-capable=${HOVER_CAPABLE ? '1' : '0'}`,
        `--gloss-thai-source=${THAI_SOURCE ? '1' : '0'}`,
        `--gloss-pair-lock=${PAIR_LOCK ? '1' : '0'}`],
      // The pill spends its life BEHIND something — a fullscreen game, or any window the user is
      // actually looking at — and Chromium throttles an occluded window's timers and frame callbacks
      // to about 1/s. Measured it: while the pill sat under a Terminal window, an in-page 16ms sampler
      // fired 3 times in 1.4s, so every card animation ran on ~1fps and read as a jolt (jek reported
      // the card "กระตุก" when switching words). An always-on-top overlay is never really in the
      // background, so opt out. showResult's own comment already blamed this.
      backgroundThrottling: false,
    },
  });
  mainWindow.setAlwaysOnTop(true, 'screen-saver');
  // WINDOWS: tell the compositor this window is NOT opaque, or every Chromium browser under it stops
  // painting. Measured 2026-08-12: pressing a pill button over a playing YouTube video killed the
  // PICTURE while the sound carried on, and `chrome.exe --disable-features=CalculateNativeWinOcclusion`
  // removed it with no change to Gloss at all. Chrome's occlusion detector adds up the opaque windows
  // above it, sees our full-screen always-on-top overlay covering it completely, concludes nobody can
  // see it, and stops drawing to save power. Edge does it too — it is the same Chromium.
  // `transparent: true` alone does not save us: Electron paints that through DWM/DirectComposition
  // rather than a layered window, so from the outside the overlay still looks like a solid rectangle.
  // setOpacity is the documented way to make it a layered window with an alpha the detector can read;
  // 0.99 is below the "fully opaque" line it tests for and is invisible to the eye.
  if (IS_WIN) mainWindow.setOpacity(0.99);
  mainWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  applyContentProtection();
  // Click-through by default; the renderer flips it on while the cursor is over
  // real content so the transparent area never eats the game's clicks.
  mainWindow.setIgnoreMouseEvents(true, { forward: true });
  setOverlayBounds({ x: wa.x, y: wa.y, width: wa.width, height: wa.height }); // undo the creation-time clamp
  mainWindow.on('focus', updateCursorFeed);
  mainWindow.on('blur', () => { updateCursorFeed(); captureFrontApp(); });
  // GT_DEBUG only: the overlay's console, on the terminal. Renderer logs and errors otherwise go
  // nowhere a developer can see without attaching DevTools over a game — which is why every renderer
  // question so far has had to be answered by reading code instead of by looking.
  if (DEBUG) {
    mainWindow.webContents.on('console-message', (_e, level, message, line, sourceId) => {
      const where = sourceId ? ` (${path.basename(sourceId)}:${line})` : '';
      console.log(`[renderer]${where} ${message}`);
    });
  }
  mainWindow.loadFile(path.join(__dirname, 'renderer', 'main', 'index.html'));
  // Windows starts in the click-through state that gets no forwarded mousemove (case (c) in
  // needsCursorFeed), so the feed has to be armed here rather than waiting for a focus change or a
  // setInteractive call — nothing else would ever arrive to trigger one.
  mainWindow.webContents.once('did-finish-load', updateCursorFeed);
  startFollowPoll();
}

// ---------- multi-monitor ----------
// The overlay is ONE display's work area, so "moving to another monitor" means re-homing the window,
// not moving anything inside it. Deliberately not a window spanning every display: with macOS's
// default "Displays have separate Spaces", a transparent always-on-top window across two screens gets
// clipped and mis-placed, and it would break the per-display snip overlays that already work.
// NOTE (2026-07-22): written on a single-monitor machine — the single-display paths are exercised,
// the actual cross-monitor move is NOT verified on real hardware.
function displayList() { return screen.getAllDisplays(); }

// The monitor settings.pillDisplay names, or null when it can't be found (unplugged, or nothing saved
// yet) so the caller falls back to the primary display the way it always did.
//
// Matched by id FIRST and by origin second, because neither one is trustworthy alone: display.id is
// exact but Windows renumbers it across a driver update or a cable swap, while the origin survives
// that and is also what a person means by "the right-hand monitor" — but two displays can share an
// origin transiently while Windows re-lays-out the desktop. Id then origin gets the common case right
// and degrades to the sensible answer instead of to the primary display.
function rememberedDisplay() {
  const saved = settings.pillDisplay;
  if (!saved || typeof saved !== 'object') return null;
  const list = displayList();
  return list.find((d) => d.id === saved.id)
      || list.find((d) => d.bounds.x === saved.x && d.bounds.y === saved.y)
      || null;
}

// Written on the way OUT of moveToDisplay, not from a Settings row: the pill's monitor is decided by
// moving it, so the move is the only event that knows the answer.
function rememberDisplay(display) {
  if (!display) return;
  const next = { id: display.id, x: display.bounds.x, y: display.bounds.y };
  const cur = settings.pillDisplay;
  // Don't rewrite settings.json on every snip when followMonitor keeps re-homing to the same screen.
  if (cur && cur.id === next.id && cur.x === next.x && cur.y === next.y) return;
  settings.pillDisplay = next;
  saveSettings();
}

function currentDisplay() {
  if (!mainWindow || mainWindow.isDestroyed()) return screen.getPrimaryDisplay();
  const b = mainWindow.getBounds();
  return screen.getDisplayNearestPoint({ x: b.x + Math.round(b.width / 2), y: b.y + Math.round(b.height / 2) });
}

// Re-home the overlay onto `display`. Returns false when there's nothing to do, so callers can stay
// quiet on a single-monitor machine instead of announcing a move that never happened.
function moveToDisplay(display) {
  if (!display || !mainWindow || mainWindow.isDestroyed()) return false;
  if (display.id === currentDisplay().id) return false;
  const wa = overlayArea(display); // same rule, and the same clamp to work around — see setOverlayBounds
  setOverlayBounds({ x: wa.x, y: wa.y, width: wa.width, height: wa.height });
  // The canvas is a different size now, so every dock anchor the renderer computed is stale. It
  // re-derives them on its own resize event; this just tells it WHY, so it can re-park rather than
  // leave the pill wherever the old geometry put it (possibly off the new screen).
  sendMain('display:moved');
  rememberDisplay(display); // where you left it is where it opens next time
  return true;
}

// Called at the start of every snip: with more than one monitor, the pill should be on the screen you
// just pointed at, not the one it happened to launch on. Silent — no hint, no announcement — because
// on a single display it does nothing at all and on two it's the obvious outcome of what you just did.
function followCursorMonitor() {
  if (!settings.followMonitor) return;
  if (displayList().length < 2) return;
  moveToDisplay(screen.getDisplayNearestPoint(screen.getCursorScreenPoint()));
}

// The monitor the pointer is on. Two other signals were tried first and jek chose this one after
// using each: the snip-only follow left the pill on the screen he had finished with, and the
// foreground-window follow only moved once he clicked into something, which is later than the
// moment he had already turned his head. Where the mouse goes is where he is going.
//
// The dwell below is what makes that liveable: a pointer crossing a second monitor on its way
// somewhere else is not a decision, and an overlay that tracks the pointer continuously is the
// version that was tried this morning and felt like it was wandering.
// 120ms, not 700. At 700 the wait before the pill even started moving was over a second, which
// reads as the overlay lagging behind you rather than following you — jek measured it against
// Wispr Flow, which lands on the new screen the moment the pointer does. GetCursorScreenPoint is
// a syscall on a number, not a scan: eight of them a second costs nothing measurable.
const FOLLOW_POLL_MS = 120;
// Samples on the other screen before the pill goes there — about a quarter second at the rate above.
// Enough that a pointer thrown across two screens in one flick does not drag the overlay onto the
// middle one, and short enough that arriving somewhere and the pill arriving are the same moment.
const FOLLOW_CONFIRM = 2;
// A manual move is a decision — "keep the pill off the screen the game is on" is a real thing to
// want — so following stands down for a while rather than overruling it two seconds later.
const FOLLOW_MANUAL_HOLD_MS = 120000;
let followPollTimer = null;
let followSeenId = 0;
let followSeenCount = 0;
let followPausedUntil = 0;
let pillDragging = false;

function startFollowPoll() {
  if (!IS_WIN || followPollTimer) return;
  followPollTimer = setInterval(() => {
    if (!settings.followMonitor) return;
    if (snipping || externSession || winComboHolding) return;   // mid-snip the display is already decided
    if (pillDragging) return;   // a hand is holding it; the cursor may cross a screen the pill cannot
    if (Date.now() < followPausedUntil) return;
    if (displayList().length < 2) return;
    const d = screen.getDisplayNearestPoint(screen.getCursorScreenPoint());
    if (!d || d.id === currentDisplay().id) { followSeenId = 0; followSeenCount = 0; return; }
    if (d.id !== followSeenId) { followSeenId = d.id; followSeenCount = 1; return; }
    if (++followSeenCount < FOLLOW_CONFIRM) return;
    followSeenId = 0; followSeenCount = 0;
    moveToDisplay(d);
  }, FOLLOW_POLL_MS);
}

function cycleDisplay() {
  const list = displayList();
  if (list.length < 2) { setHintState('Only one monitor'); return; }
  const idx = list.findIndex((d) => d.id === currentDisplay().id);
  const next = list[(idx + 1) % list.length];
  followPausedUntil = Date.now() + FOLLOW_MANUAL_HOLD_MS;   // moved on purpose: leave it there
  if (moveToDisplay(next)) setHintState(`Monitor ${(idx + 1) % list.length + 1} of ${list.length}`);
}

// A normal, resizable window for the learning dashboard (Learn/Vocab/History — M4). Built lazily on
// first open and reused after that: closing it just hides it (see the 'close' handler below) so
// re-opening is instant and its in-memory state survives. Fully separate from mainWindow's
// click-through/transparent setup — nothing here should ever touch mainWindow's mouse-events logic.
function createLearnWindow() {
  learnWindow = new BrowserWindow({
    width: 900,
    height: 640,
    minWidth: 600,
    minHeight: 420,
    frame: true,
    // The window is #12141a inside. With the stock title bar it wears whatever the SYSTEM appearance
    // says — so on a Mac in Light Mode (the default) a light grey bar sat on top of a near-black
    // page, which is the join nobody draws on purpose. hiddenInset keeps the traffic lights, drops
    // the bar, and lets the page paint the whole window; the header inside already reads as one.
    ...(process.platform === 'darwin' ? { titleBarStyle: 'hiddenInset' } : {}),
    resizable: true,
    transparent: false,
    show: false,
    // Without this the window paints the default WHITE while the page loads — a full-screen flash on a
    // dark app. Matches --bg in the learn window's CSS, so the very first frame is already the app.
    backgroundColor: '#12141a',
    icon: APP_ICON,
    title: 'Gloss',
    webPreferences: {
      preload: path.join(__dirname, 'preload-learn.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });
  learnWindow.loadFile(path.join(__dirname, 'renderer', 'learn', 'index.html'));
  // Same replay mainWindow gets on boot (see app.whenReady below) — the learn window is created
  // lazily on first open, so it needs its own one-time history:load once its page is ready. After
  // that translation:new is broadcast (sendAll) to every window, so it stays current on its own —
  // even while hidden, since hiding never destroys/reloads the page.
  learnWindow.webContents.once('did-finish-load', () => {
    if (history.length) learnWindow.webContents.send('history:load', history);
  });
  // Hide instead of destroy on the window's own close button — keeps it warm (and its state intact)
  // for the next open. app.isQuitting (set in before-quit) lets a real ⌘Q/Quit still close it for real.
  learnWindow.on('close', (e) => {
    if (!app.isQuitting) {
      e.preventDefault();
      learnWindow.hide();
    }
  });
  learnWindow.on('closed', () => { learnWindow = null; });
}

function openLearnWindow() {
  const fresh = !learnWindow || learnWindow.isDestroyed();
  if (fresh) createLearnWindow();
  // First open builds the window from scratch, so showing it right away puts an empty shell on screen
  // while the page loads. Wait for the renderer's first paint instead — after that the window is only
  // hidden, never destroyed, so every later open is instant and shows immediately.
  if (fresh) {
    learnWindow.once('ready-to-show', () => {
      if (learnWindow && !learnWindow.isDestroyed()) { learnWindow.show(); learnWindow.focus(); }
    });
    return;
  }
  // Minimised counts as open, and show() on a minimised window leaves it minimised.
  if (learnWindow.isMinimized()) learnWindow.restore();
  learnWindow.show();
  // Windows will not hand the foreground to a process that does not already have it, and the pill
  // is click-through — the game or the browser keeps the foreground, so focus() alone flashes the
  // taskbar button and leaves the window behind whatever you were reading. Pressing the ✎ button
  // with the window already open therefore looked like the button was dead. A single trip through
  // always-on-top is the documented way past that rule; moveTop covers the case where the window is
  // merely buried rather than unfocused.
  if (IS_WIN) {
    const wasOnTop = learnWindow.isAlwaysOnTop();
    learnWindow.setAlwaysOnTop(true);
    learnWindow.setAlwaysOnTop(wasOnTop);
    learnWindow.moveTop();
  }
  learnWindow.focus();
}

// One overlay per display, so a region can be snipped on any monitor.
let snipping = false;

// Build the per-display overlays ONCE and keep them hidden. Recreating a
// transparent full-screen window on every snip added a visible click-to-appear
// lag — showing/hiding a pre-built one is instant.
// setContentProtection is not free on Windows: flipping display affinity makes DWM tear the window
// down and rebuild it, which the user sees as a flash. Only call it when the value actually changes.
function setProtect(win, on) {
  if (!win || win.isDestroyed() || win._gtProtected === on) return;
  win._gtProtected = on;
  win.setContentProtection(on);
}

function ensureSnipWindows() {
  const displays = screen.getAllDisplays();
  if (snipWindows.length && snipWindows.length !== displays.length) {
    for (const w of snipWindows) if (!w.isDestroyed()) w.destroy();
    snipWindows = [];
  }
  if (snipWindows.length) return;
  snipWindows = displays.map((display) => {
    const { x, y, width, height } = display.bounds;
    const win = new BrowserWindow({
      x, y, width, height,
      show: false,
      frame: false,
      transparent: true,
      alwaysOnTop: true,
      hasShadow: false,
      resizable: false,
      movable: false,
      skipTaskbar: true,
      fullscreenable: false,
      // Take the drag without ever ACTIVATING our app — so the game keeps keyboard/mouse focus and
      // you can go straight back to playing after a snip, no click-to-refocus needed.
      acceptFirstMouse: true, // macOS only — a no-op on Windows, which is what focusable:false covers
      // Windows counterpart (WS_EX_NOACTIVATE): the overlay receives the drag but is NEVER activated,
      // so the game/player stays foreground and keeps rendering. Activation — not mouse capture — is
      // the suspected cause of the "video freezes while snipping" report. Esc is a globalShortcut, so
      // the overlay never needed keyboard focus anyway.
      focusable: false,
      backgroundColor: '#00000000',
      webPreferences: {
        preload: path.join(__dirname, 'preload-snip.js'),
        contextIsolation: true,
        nodeIntegration: false,
      },
    });
    // The constructor asked for display.bounds and Windows did not give it: measured 1920×1032 for a
    // 1920×1080 request, on both displays. That is the taskbar strip missing from the BOTTOM of the
    // snip overlay — the edge of the screen where game subtitles live — and it also poisons every
    // coordinate derived from getBounds() (see mouseHookDown, where a wrong window origin is what put
    // the armed ring somewhere else for a frame before the first move corrected it).
    setFixedWindowBounds(win, { x, y, width, height });
    win.setAlwaysOnTop(true, 'screen-saver');
    win.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
    // macOS: shareable, so the drag rectangle shows up in screen recordings. The final read happens
    // after these hide (see snip:complete), so the wash and selection box never reach the OCR frame.
    // Windows: hidden from capture from the start, because the live preview OCRs WHILE the overlay is
    // up (a transparent overlay lands in a BitBlt as flat black). Set once here, never toggled per
    // snip — changing display affinity makes DWM rebuild the window, which flashes it on screen.
    // Excluded from capture unless the user asked for a recordable snip, which comes with the frozen
    // path that does not need the exclusion. See recordableSnip in DEFAULT_SETTINGS.
    setProtect(win, IS_WIN && !settings.recordableSnip);
    win.loadFile(path.join(__dirname, 'renderer', 'snip', 'snip.html'));
    return win;
  });
}

function showSnipWindows() {
  ensureSnipWindows();
  const displays = screen.getAllDisplays();
  const cursor = screen.getCursorScreenPoint();
  // Windows: an overlay that CAPTURES the mouse (setIgnoreMouseEvents false) sits over the video as a
  // real composited layer → DWM disables the video's hardware plane → the video freezes/lags. So on
  // Windows we keep the overlay CLICK-THROUGH (like the never-freezing pill) and drive the box from
  // forwarded mousemove in point style: press = anchor, move = size, press again = capture. Live video
  // keeps playing behind it. macOS composites fine, so it keeps the direct capturing drag.
  const winPoint = !livePicking && process.platform === 'win32' && !WIN_CAPTURING_SNIP;
  snipWindows.forEach((win, i) => {
    if (win.isDestroyed() || !displays[i]) return;
    // Click-through for the Windows live-point path; capturing for the macOS drag / CC picking.
    if (winPoint) win.setIgnoreMouseEvents(true, { forward: true });
    else win.setIgnoreMouseEvents(false);
    const b = displays[i].bounds;
    // CC picking: hide the overlay from capture — the box fill, handles, and the centre label sit
    // INSIDE the region the live preview keeps OCR-ing, and it was literally translating our own
    // label back at the user. Normal drag snips stay shareable (their wash never gets final-read).
    setProtect(win, IS_WIN || livePicking);
    const cursorHere = cursor.x >= b.x && cursor.x < b.x + b.width && cursor.y >= b.y && cursor.y < b.y + b.height;
    // Point style (incl. the Windows live-point path): the box anchors at the cursor when the shortcut
    // fires — only on the display the cursor is on (a box can't span displays). Window-relative.
    const point = ((winPoint || effectiveSnipStyle() === 'point') && !livePicking && cursorHere)
      ? { x: cursor.x - b.x, y: cursor.y - b.y } : null;
    // Live picking: the editable box ALWAYS opens at the standard subtitle spot (bottom-centre) —
    // jek 2026-07-17: no remembering; a stale saved position kept opening in the wrong place and
    // forced a ↺ Default click every time.
    let liveRect = null;
    if (livePicking && cursorHere) {
      liveRect = { x: Math.round(b.width * 0.15), y: Math.round(b.height * 0.76), width: Math.round(b.width * 0.70), height: Math.round(b.height * 0.14) };
    }
    setFixedWindowBounds(win, { x: b.x, y: b.y, width: b.width, height: b.height });
    // Where the cursor REALLY is when the overlay opens, so the ring is on it from the first frame
    // instead of wherever a replayed mousemove says (see feedSnipCursor).
    const ringAt = ringPoint(cursor);
    win.webContents.send('snip:reset', { live: livePicking, point, liveRect, ct: winPoint, cursor: ringAt }); // clear leftovers + pick the right hint
    clearTimeout(win._gtHideTimer); // a pending post-snip hide must not swallow this new session
    win.showInactive(); // show WITHOUT activating — the game stays the frontmost/focused app
    // `cursor` above was read when this function started; the overlay paints ~90ms later (measured),
    // and a hand that is still moving has left by then — the ring appears where the cursor WAS. One
    // fresh point now, from the frame the window actually goes up, is what makes it appear ON the
    // cursor instead of behind it. The live feed takes over from here.
    win.webContents.send('snip:cursor', ringPoint(screen.getCursorScreenPoint()));
  });
  // Whether a second shortcut press should act as the shutter (point / Windows live-point).
  snipPointActive = winPoint || effectiveSnipStyle() === 'point';
  // We deliberately DON'T focus() the overlay (that stole focus from the game, forcing a click to
  // resume play). The drag works via acceptFirstMouse; Esc-to-cancel is caught globally instead of
  // needing window focus.
  snipping = true;
  // Tell the pill a snip session is live so its ⧉ button lights up, the same way the mic lights up
  // while it's listening — the two are the same kind of state (a mode you are IN and must leave).
  sendMain('snip:state', true);
  syncEscape();
  // Force the pill window fully click-through for the whole snip session — if the cursor was over
  // the pill when the snip started (or wanders over it mid-snip), an interactive pill window would
  // swallow the overlay's clicks (see ui:interactive).
  if (mainWindow && !mainWindow.isDestroyed()) {
    interactiveState = false;
    mainWindow.setIgnoreMouseEvents(true, { forward: true });
    setClickShield(false); // snip owns the hook for its whole session — the shield must not be armed too
    holdForeground('pill', false); // a no-op since the 'pill' holder was removed — kept as the release
                                   // for any future holder that arms on the same signal
  }
  updateCursorFeed(); // click-through now → no mousemove reaches the pill; poll the OS cursor instead so it collapses on real un-hover (not the instant ⧉ was pressed)
  hidePillFromCapture(); // keep our own pill text out of the OCR if the box overlaps it
}

function closeSnipWindows(keepAside) {
  // The session is over however it got here, so give Space back to the game. disarmWinSnip already
  // does this for the drag-hook path; the point paths grab it too now and end up here instead.
  // Unregistering a key that was never taken is a no-op.
  releaseSnipTypeKey();
  for (const win of snipWindows) {
    if (win.isDestroyed()) continue;
    // Clear the selection BEFORE hiding, so the overlay is already clean when it's
    // next shown — resetting on show leaves the old box visible for a frame.
    // Park it in the state it will NEXT be shown in, not a generic blank one. On Windows every snip
    // opens in the armed/external state, and resetting to the plain-drag state here meant the next
    // snip flashed "Drag a box…" for a frame before swapping to "Left-click and drag…" — the hint
    // visibly stuttering the moment the shortcut was pressed.
    // idle: park the HINT hidden too. Windows can park the box in its next state because every snip
    // there opens the same way; mac has two triggers wanting two different lines, so instead of
    // guessing, the text is simply not shown until the next session says which one it is.
    win.webContents.send('snip:reset', IS_WIN ? { external: true, idle: true } : { idle: true });
    // ...and give it two frames to actually PAINT that clean state. A hidden window stops painting,
    // so hiding in the same tick froze the old box into the window's last frame and it flashed for
    // an instant on the next snip. Cancelled by show* if a new snip starts inside the window.
    clearTimeout(win._gtHideTimer);
    win._gtHideTimer = setTimeout(() => { if (!win.isDestroyed()) win.hide(); }, 32);
  }
  snipping = false;
  sendMain('snip:state', false);
  updateCursorFeed(); // snip over → drop the snip cursor poll (re-evaluates and stops unless still needed)
  syncEscape(); // keeps Esc alive if a Windows snip is still armed underneath this close
  snipFreeze = null; // drop the frozen shot (snip:complete grabs it into a local BEFORE this runs)
  // An Esc/cancel while picking the live strip aborts the toggle cleanly. keepAside=true (the ✓
  // path) skips the "picking over" event so the pill doesn't hop back for the instant between
  // picking-end and live-start — live:state true follows immediately and keeps it aside.
  if (livePicking && !keepAside) sendMain('live:picking', false);
  livePicking = false;
  applyContentProtection(); // undo the picking-time capture hide (startLive re-hides if confirmed)
  // showSnipWindows() force-reset main's interactiveState to false, but the RENDERER's own
  // `interactive` var may still say true (it was hovering the pill when the snip started — always
  // the case for the CC button). Both sides dedupe on their own flag, so neither would ever send
  // the next "true" → the pill stayed click-through until the cursor left and returned. Tell the
  // renderer to resync so its next mousemove over the pill re-arms interactivity.
  sendMain('ui:interactive-reset');
}

// Reports BOTH answers, and only when the answer changes. It used to report the failure only, which
// is fine for a banner you dismiss and wrong for anything that stays on screen: the pill now wears
// "Screen off" for as long as the permission is off, so it needs to be told when that stops being
// true — otherwise the label outlives the problem. Every capture path already calls this, so the
// grant is noticed on the user's next snip without anything new to poll.
let screenPermSeen = null;
function checkScreenPermission() {
  if (process.platform !== 'darwin') return true;
  const status = systemPreferences.getMediaAccessStatus('screen');
  const changed = screenPermSeen !== status;
  screenPermSeen = status;
  if (status === 'granted') {
    if (changed) sendMain('permission:ok', 'screen');
    return true;
  }
  sendMain('permission:needed', status);
  return false;
}

// Grab the whole display as a NativeImage — the expensive, async, "what does the screen look
// like right now" half of a capture. Split out from the crop math below so a single freeze-frame
// snapshot (taken once, on ⌘⇧S) can be cropped against repeatedly instead of re-capturing live.
async function captureFullDisplay(display) {
  const scale = display.scaleFactor || 1;
  const sources = await desktopCapturer.getSources({
    types: ['screen'],
    thumbnailSize: {
      width: Math.round(display.size.width * scale),
      height: Math.round(display.size.height * scale),
    },
  });
  let source = sources.find(s => s.display_id === String(display.id));
  if (!source) {
    // display_id can fail to match on some multi-monitor setups; falling back to
    // sources[0] silently would OCR the wrong screen — at least surface it.
    if (sources.length > 1) console.warn('capture: no display_id match, falling back to first of', sources.length, 'screens');
    source = sources[0];
  }
  if (!source) return null;

  const fullImg = source.thumbnail;
  return { fullImg, fullSize: fullImg.getSize() };
}

// Pure math: crop an already-captured full-display image down to `bounds` (absolute screen
// coords). No I/O, so it works identically against a fresh capture or a frozen one from earlier.
function cropRegion(fullImg, display, bounds) {
  const fullSize = fullImg.getSize();
  const ratioX = fullSize.width / display.size.width;
  const ratioY = fullSize.height / display.size.height;

  const relX = bounds.x - display.bounds.x;
  const relY = bounds.y - display.bounds.y;

  const cropX = Math.max(0, Math.round(relX * ratioX));
  const cropY = Math.max(0, Math.round(relY * ratioY));
  const cropRect = {
    x: cropX,
    y: cropY,
    // Clamp against the space left from the crop origin, not the whole image,
    // or a region flush with the right/bottom edge overflows the bitmap.
    width: Math.min(fullSize.width - cropX, Math.round(bounds.width * ratioX)),
    height: Math.min(fullSize.height - cropY, Math.round(bounds.height * ratioY)),
  };
  if (cropRect.width < 4 || cropRect.height < 4) return null;

  // ratios come back with the image: OCR word boxes are in captured pixels and
  // have to be mapped to screen points to place the tooltip.
  return { image: fullImg.crop(cropRect), ratioX, ratioY, origin: { x: bounds.x, y: bounds.y } };
}

async function captureRegion(bounds) {
  // Windows: BitBlt just the boxed region (~15ms). desktopCapturer grabs every screen at full
  // resolution (~300-400ms here) and that wait was the visible hitch on releasing a snip drag.
  // Any failure falls through to the portable path below, so this can only make things faster.
  if (winCaptureAvailable()) {
    const native = captureRegionNative(bounds);
    if (native) return native;
  }
  const display = screen.getDisplayMatching(bounds);
  const full = await captureFullDisplay(display);
  if (!full) return null;
  return cropRegion(full.fullImg, display, bounds);
}

// VERTICAL padding only, then clamp to the display so a box dragged past the edge stays valid.
// Horizontal padding is deliberately NOT done: a side margin reaches into the neighbouring word on
// the same line (it used to grab the "st" off "Best" next to "Prompt"). Vertically there is no
// neighbouring word to steal — just the ascender/descender room Tesseract wants, which a box dragged
// tight against the glyph tops otherwise denies it.
//
// The bottom gets more room than the top (jek, 2026-07-30): a box drawn across the BOTTOM of a glyph
// loses the part that tells letters apart, and no engine can read back pixels that were never
// captured — "UNION" came through as "LINION" because the U's bowl was cut, leaving two stems. Round
// bottoms (U O C G J) and descenders (g j p q y) all live down there; the top only risks losing
// ascender tips, which cost far less. Still under one line height, so neither edge pulls in the
// neighbouring line.
const PAD_TOP = 8;
const PAD_BOTTOM = 14;
function padBounds(b) {
  const db = screen.getDisplayMatching(b).bounds;
  const x = Math.max(db.x, b.x);
  const y = Math.max(db.y, b.y - PAD_TOP);
  const right = Math.min(db.x + db.width, b.x + b.width);
  const bottom = Math.min(db.y + db.height, b.y + b.height + PAD_BOTTOM);
  return { x, y, width: right - x, height: bottom - y };
}

function normalizeLines(rawText) {
  const lines = rawText.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
  if (lines.length === 0) return '';
  const wordCount = s => s.split(/\s+/).filter(Boolean).length;
  const out = [];
  let current = lines[0];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    const endsSentence = /[.!?:;)\]"”]$/.test(current);
    const nextStartsUpper = /^[A-Z\(\[\"“]/.test(line);
    // A sentence that OCR wrapped across visual lines gets rejoined — but two SHORT standalone lines
    // (game menu / skill / inventory items: ≤3 words each, current not trailing a comma) must stay
    // separate. Force-joining them flattened e.g. "Attack / Defense / Magic / Items" into one fake
    // phrase the model can't translate word-by-word (jek 2026-07-26).
    const bothShortItems = wordCount(current) <= 3 && wordCount(line) <= 3 && !/,$/.test(current);
    if ((endsSentence && nextStartsUpper) || bothShortItems) {
      out.push(current);
      current = line;
    } else {
      current += ' ' + line;
    }
  }
  out.push(current);
  return out.join('\n');
}

// OCR on game fonts produces confident-looking gibberish ("Th3 kn1ght s@id").
// Translating that just launders the noise into Thai, so drop it here instead.
function looksLikeGarbage(text) {
  const stripped = text.replace(/\s+/g, '');

  // Numbers are the one real read with no letters in it — damage, HP, gold, prices, timers.
  // The letter-ratio and real-word rules below would call every one of them noise, so let a
  // digits-and-number-punctuation read through first.
  if (/\d/.test(stripped) && /^[\d.,:;%\-+/*x×()[\]$€£¥฿°]+$/i.test(stripped)) return false;

  if (stripped.length < 3) return true;

  // \p{L}, NOT [a-zA-Z]: the ASCII-only version scored every Japanese/Chinese/Korean/Thai read at
  // 0% letters and threw it away — the app shipped four traineddata files and could only ever show
  // "Blurry — try a bigger box" for three of them.
  const letters = (stripped.match(/\p{L}/gu) || []).length;
  if (letters / stripped.length < 0.5) return true;

  // A real sentence has words; a wall of single characters is misread pixels. CJK doesn't space its
  // words, so a whole line arrives as one "word" — counting letters inside it works for both.
  const words = text.trim().split(/\s+/);
  const realWords = words.filter(w => (w.match(/\p{L}/gu) || []).length >= 2);
  if (realWords.length === 0) return true;

  // A symbol wedged BETWEEN two letters is a misread glyph, not spelling — "PISCUI$E", "s@id". This
  // rule is why the example in the comment above needed writing down twice: the filter did not
  // actually catch its own "Th3 kn1ght s@id", because every one of those tokens is >50% letters and
  // holds two letters, which is all the tests above ever asked. jek hit the real version of it on
  // 2026-08-10 and got the transliterated Thai of a word that does not exist.
  //
  // The junk glyphs are NAMED, not inferred. This used to be written the other way round — "anything
  // that isn't a letter, a digit, an apostrophe, a hyphen or a dot" — which quietly declared the
  // punctuation of every writing system on earth to be a misread. Measured on 2026-08-12 (jek: "แล้ว
  // มันจะมีเคสแบบอื่นอีกไหม"), the old form rejected, among others:
  //
  //   私は、彼を見た。 · 他说，我不知道。 · ザ・ワールド   ← 、，・ mid-line: the app's core use case
  //   notification (status/error) · Save/Load · km/h      ← the slash, which is how this was found
  //   Ctrl+Alt · save_file · Half—Life · Wi‑Fi            ← + _ em-dash and the non-breaking hyphen
  //   สวัสดีครับ                                            ← every script that writes vowels as marks
  //
  // and each rejection cost more than it looked: the CC loop drops such a line SILENTLY (no rescue
  // path there), while a snip falls through to claudeReadImage — 2 units and a "Reading harder…"
  // pause for a read that was already correct, or a dead-end "Blurry" with no key.
  //
  // What the rule was ever meant to catch is a glyph OCR swaps FOR a letter: $↔S, @↔a, &↔G, |↔l.
  // Naming those is a short, checkable list; naming the survivors was not. & stays in despite AT&T
  // because PIS&UISE is a real measured misread from this app (see the OCR notes above).
  // Digits keep their own rule below, so "wor1d" is caught and the game title "L4D2" is not.
  const mangled = realWords.filter((w) => {
    if (/\p{L}[@$&#%*^~|\\"§©®¥£€]\p{L}/u.test(w)) return true;
    if (!/\p{L}\d\p{L}/u.test(w)) return false;
    return (w.match(/\p{L}/gu) || []).length / w.length >= 0.6;
  });
  // A share, not a single hit: one broken word inside a five-line read is a read worth translating
  // (and the dictionary second opinion in recognizeImage has already had its go at fixing it), while
  // one broken word out of one or two is the whole read.
  return mangled.length * 3 >= realWords.length;
}

// Human-readable names for the target codes, used for the Claude prompt.
const LANG_NAMES = {
  th: 'Thai', en: 'English', ja: 'Japanese', 'zh-CN': 'Chinese',
  ko: 'Korean', es: 'Spanish', fr: 'French', de: 'German', vi: 'Vietnamese',
};
function targetName() {
  return LANG_NAMES[settings.targetLang] || settings.targetLang;
}

// sl=auto lets Google detect the source, so this works for any OCR'd language.
// Google's part-of-speech labels → short tags shown after a single word ("n.", "adj.", …).
const POS_ABBR = {
  noun: 'n.', verb: 'v.', adjective: 'adj.', adverb: 'adv.', pronoun: 'pron.',
  preposition: 'prep.', conjunction: 'conj.', interjection: 'interj.', exclamation: 'interj.',
  abbreviation: 'abbr.', numeral: 'num.', particle: 'part.', article: 'art.', determiner: 'det.',
  prefix: 'pref.', suffix: 'suf.',
};
function posAbbr(p) { return p ? (POS_ABBR[String(p).toLowerCase()] || '') : ''; }

// SECOND OPINION on the part of speech, from the dictionary already shipped for point-at-a-word.
// Google's dt=bd block only answers for words it holds as HEADWORDS, so a vocab list ends up with
// gaps that look arbitrary: measured on a real list, `think` and `discerning` carried a tag while
// `sedating` (an -ing form of `sedate`) and `command...` (punctuation still attached) carried none
// (jek, 2026-08-09: "ทำไมบางอันไม่มีชนิดของคำ?"). Both of those the local index can answer — it
// deinflects, and it is asked with the word cleaned. Proper nouns like `Chox` still come back empty,
// which is correct: a game's character has no part of speech.
//
// Loaded on demand, never at boot. It is 12MB of JSON and parsing it blocks this process for ~300ms;
// paying that once, inside a lookup the user is already waiting on (the network round trip is
// longer), beats charging every launch for a table most sessions never touch.
const DICT_POS_ABBR = { noun: 'n.', verb: 'v.', adj: 'adj.', adv: 'adv.', pron: 'pron.', prep: 'prep.',
  conj: 'conj.', intj: 'interj.', num: 'num.', particle: 'part.', article: 'art.', det: 'det.',
  name: '', phrase: '' }; // name/phrase deliberately blank — neither is a part of speech
// The local dictionary's answer for ONE word, in the shape the free endpoint returns — { text, pos,
// senses: [{ pos, terms }] }. One converter, because the two shapes were never really different: the
// dt=bd block is one group per part of speech, and this dictionary is one ENTRY per part of speech.
// Anything that reads a word answer — the Type bar, tapping a word, the pointed-at bubble — now gets
// the same object no matter which of the two produced it, so "three senses in the bar but one when I
// point at it" stops being possible by construction (jek, 2026-08-15: "อยากให้มัน consistent").
//
// Same caps as translate(): 3 groups × 3 terms. A gloss can already carry several terms in one string
// ("ที่; ณ; ตรง"), which is exactly the `terms` array split by another name.
// Returns null when the dictionary has nothing, or nothing IN THE READER'S LANGUAGE — an English
// definition is not an answer for someone reading Thai (hoverNeedsTranslation is the same test the
// bubble uses).
function localWordAnswer(word) {
  const lang = settings.sourceLang;
  if (!HOVER_LANGS[lang]) return null;
  try {
    if (!hoverDict.isLoaded(lang) && !hoverDict.load(lang)) return null;
    const found = hoverDict.lookupAt(String(word || ''), 0, lang);
    if (!found || !Array.isArray(found.entries)) return null;
    // Judged on whether the entry has ANY sense in the reader's language, not on whether its FIRST
    // one is — `light` files its Thai under the third sense of the noun entry, and testing senses[0]
    // alone threw the whole entry away. (hoverNeedsTranslation asks the narrower question because the
    // bubble only ever paints sense zero.)
    // Cut to three AFTER dropping the entries that answer only in English, never before. `fast` files
    // its Thai under entries 0, 3 and 4 — a train, an interjection and an acronym sit in between — so
    // slicing first left one sense where the word has three (measured 2026-08-15).
    const senses = preferReaderEntry(found.entries)
      .map((e) => {
        const own = (e.senses || []).filter((s) => !String(s.pos || '').split(',').map((t) => t.trim()).includes('en'));
        const terms = own.flatMap((s) => String(s.gloss || '').split(';')).map((t) => t.trim()).filter(Boolean);
        return { pos: DICT_POS_ABBR[String((own[0] || {}).pos || '').split(',')[0].trim()] || '', terms: terms.slice(0, 3) };
      })
      .filter((s) => s.terms.length)
      .slice(0, 3);
    if (!senses.length) return null;
    return { text: senses[0].terms.join('; '), pos: senses[0].pos, senses, matched: found.matched };
  } catch { return null; }
}

// What a word answers with when the network is gone, in the order that gives the best line: the
// shared cache first (it holds the answer the bar itself gave for this word, whenever it was), then
// the on-disk dictionary. Both are already on this machine — "offline" only ever meant "cannot ask
// Google", never "cannot answer".
function offlineWordAnswer(word) {
  const hit = wordCacheGet(word);
  if (hit) return { text: hit.text, pos: hit.pos, senses: hit.senses, fromCache: true };
  return localWordAnswer(word);
}

// Everything the machine can say about a word WITHOUT a network call or a key — the study record a
// pointed word turns into. `senses` is the answer the two surfaces already agree on (shared cache
// first, dictionary second); `defs` is the part neither surface shows but a learner opening the word
// later actually wants: the dictionary's own English definitions, which enth.json carries under the
// `,en` senses and which nothing has ever read.
//
// ONE function, called by BOTH save paths (the point-mode key and the tapped word in the panel), so
// a word does not become a fuller record for having been collected one way rather than the other —
// which is the two-grade collection this was asked to stop (jek, 2026-08-15).
function wordStudyDetail(word) {
  const term = String(word || '').trim();
  if (!term) return {};
  const answer = offlineWordAnswer(term) || {};
  const out = {};
  if (Array.isArray(answer.senses) && answer.senses.length) out.senses = answer.senses;
  if (answer.pos) out.pos = answer.pos;
  const lang = settings.sourceLang;
  try {
    if (HOVER_LANGS[lang] && (hoverDict.isLoaded(lang) || hoverDict.load(lang))) {
      const found = hoverDict.lookupAt(term, 0, lang);
      const defs = [];
      for (const e of (found && found.entries) || []) {
        for (const sn of e.senses || []) {
          const parts = String(sn.pos || '').split(',').map((t) => t.trim());
          if (!parts.includes('en')) continue;             // the reader's own language is `meaning`
          const text = String(sn.gloss || '').trim();
          if (!text || defs.some((d) => d.text === text)) continue;
          defs.push({ pos: DICT_POS_ABBR[parts[0]] || '', text });
          if (defs.length >= 3) break;                     // three is a definition, ten is a page
        }
        if (defs.length >= 3) break;
      }
      if (defs.length) out.defs = defs;
    }
  } catch { /* the definitions are a bonus; never let them cost the save */ }
  return out;
}

function posFromLocalDict(word) {
  const local = localWordAnswer(word);
  return (local && local.pos) || '';
}

// Returns { text, pos }. pos is only present for single-word lookups (Google's dt=bd dictionary
// block) — phrases/sentences come back with pos:''.
// The free endpoint echoes ALL-CAPS words back untranslated — it reads them as proper nouns. Games
// shout their skill names and headers, so this hit constantly ("FESTERING" came back as "Festering",
// while "HAAI" on the next line translated fine). Measured against the live endpoint:
//   FESTERING → "Festering"   festering → "เปื่อยเน่า"
// So when a read comes back as its own input, retry it lowercased once. Only the echo case takes this
// path, and if the retry echoes too the original stands — no other read changes behaviour.
const echoesInput = (out, input) => out.trim().toLowerCase() === input.trim().toLowerCase();

// ---------- "there is no internet" is a different sentence from "something broke" ----------
// undici answers EVERY network failure with the same two words — `fetch failed` — and those two words
// were being forwarded to the pill verbatim, so a player on a dropped Wi-Fi read "Error: fetch failed".
// That names the HTTP library's problem, not theirs, and it is the one failure in this app they can
// actually fix in five seconds. Measured 2026-08-07 (Electron 32.3.3, node 20.18.1): DNS down gives
// message 'fetch failed' with `cause.code === 'ENOTFOUND'` in ~80ms, so the string alone is never
// enough to tell offline from a 500 — the cause code is where the truth is.
const OFFLINE_CODES = new Set([
  'ENOTFOUND', 'EAI_AGAIN', 'ENETUNREACH', 'ENETDOWN', 'EHOSTUNREACH',
  'ECONNREFUSED', 'ECONNRESET', 'EPIPE', 'ETIMEDOUT',
  'UND_ERR_CONNECT_TIMEOUT', 'UND_ERR_SOCKET', 'UND_ERR_HEADERS_TIMEOUT',
]);
function isOfflineError(err) {
  if (!err) return false;
  // Our own AbortController timeout. A stalled request looks identical whether the network is gone or
  // the endpoint is merely slow, so ask the OS rather than guess — this is the one case where
  // net.isOnline() decides, and it only ever downgrades a wrong "offline" into a plain error.
  if (err.name === 'AbortError') { try { return !net.isOnline(); } catch { return false; } }
  const code = err.code || (err.cause && err.cause.code) || '';
  if (OFFLINE_CODES.has(code)) return true;
  // The Anthropic SDK wraps its transport errors, so the code can be a level deeper than `cause`.
  const nested = err.cause && err.cause.cause && err.cause.cause.code;
  if (nested && OFFLINE_CODES.has(nested)) return true;
  return /getaddrinfo|ENOTFOUND|ECONNREFUSED|network error/i.test(String(err.message || ''));
}
// The pill's hint slot is 109px. Anything past ~18 characters overflows it and starts a marquee, which
// hides the text for a frame and slides it in from the right edge — the "warp then slide" that made
// the mic errors read as a stutter (see marqueeIfOverflow in the renderer). An error you cannot read
// at a glance mid-game is worse than a short one, so the offline case travels as a CODE and the
// renderer prints the two words that fit. Everything else keeps its own message.
function errorForPill(err) {
  if (isOfflineError(err)) return 'offline';
  const msg = String((err && err.message) || err);
  // The one failure a player actually hits, and the one the raw message explains worst: the free gtx
  // endpoint rate-limits per IP, so all three tries across both hosts come back 429 and the pill said
  // "Translate HTTP 429" — which reads as "the app is broken" (jek, 2026-08-30, on a snip of a word
  // that OCR had in fact read correctly). It is temporary and it fixes itself; say so, and say the
  // one thing worth doing about it.
  if (/\b429\b/.test(msg)) return 'Too many translations just now — wait a moment and snip again';
  return msg;
}
// What the Learn window's AI rows say went wrong. Three outcomes it can word differently: the
// reader's network is down, our AI service is down (see glossProxyClient), or something else broke.
// 'quota' comes through as its own code so the row can point at the way out instead of at a failure.
function aiErrorCode(err) {
  if (err && err.gtCode) return err.gtCode;          // 'aidown' | 'quota'
  return isOfflineError(err) ? 'offline' : 'failed';
}

// A misspelling Google FORGAVE costs nothing — "citaton" still came back การอ้างอิง. One it CHOKES on
// does: it hands the word straight back untranslated, inside the line, so the reader gets a hole where
// the word they didn't know should be ("recieve the swrod now" → "รับ swrod ตอนนี้", measured
// 2026-08-12). By then we already know the right spelling AND which word broke it, so the fix is to
// ask once more with that word corrected rather than print a translation with a gap in it.
//
// The retry is worth it precisely because it is rare: it fires only when a corrected word survived
// into the output, which is the case that is already wrong. The common one — a typo the endpoint
// handled — never spends a second request.
// The words to look for are the ones that were WRONG, which is the input side of the correction —
// spell.parts marks them on the CORRECTED line, so reading `fix` there hunts for "sword" while the
// hole in the output says "swrod" and nothing ever matches (measured: the retry never fired).
// Diffing the two token lists asks the question directly and needs no markup at all.
const words = (s) => String(s || '').toLowerCase().split(/[^\p{L}\p{N}']+/u).filter(Boolean);
function leaksTypo(out, src, fixedText) {
  const good = new Set(words(fixedText));
  // Two letters or fewer is noise ("teh" is worth catching, "th" would match half a Thai line by
  // accident) — and a short token is exactly the one a target language might legitimately contain.
  const bad = words(src).filter((w) => w.length > 2 && !good.has(w));
  if (!bad.length) return false;
  const low = String(out || '').toLowerCase();
  return bad.some((w) => low.includes(w));
}

async function translate(text, opts = {}) {
  // GT_FORCE_OFFLINE=1 — dev only. The offline paths (the local-dictionary answers below) are the
  // ones nobody exercises, because testing them for real means turning off the Wi-Fi on the machine
  // you are working on. This makes every lookup fail exactly the way a dropped connection does, so
  // "it falls back to the dictionary" can be MEASURED instead of reasoned about.
  if (process.env.GT_FORCE_OFFLINE) {
    const err = new Error('fetch failed');
    err.cause = { code: 'ENOTFOUND' };
    throw err;
  }
  const first = await translateCased(text, opts);
  // tries:1 is the type-ahead peek — it runs on every keystroke and must stay one request.
  if (opts.tries === 1 || !first.spell || !leaksTypo(first.text, text, first.spell.text)) return first;
  try {
    const fixed = await translateCased(first.spell.text, opts);
    // Keep the ORIGINAL correction block: the card still has to say what was actually on screen and
    // how it is really spelled. Only the translation comes from the corrected line.
    if (fixed.text && !leaksTypo(fixed.text, text, first.spell.text)) return { ...fixed, spell: first.spell };
  } catch { /* the first answer, hole and all, still beats an error */ }
  return first;
}

async function translateCased(text, opts = {}) {
  const first = await translateOnceRaw(text, opts);
  if (!first.text || !echoesInput(first.text, text) || text === text.toLowerCase()) return first;
  try {
    const retry = await translateOnceRaw(text.toLowerCase(), opts);
    if (retry.text && !echoesInput(retry.text, text)) return retry;
  } catch { /* keep the original read — a failed retry must not lose a translation we already have */ }
  return first;
}

// ---------- "…and this is how it's actually spelled" ----------
// OCR mangles game text and people mistype, and the translation still comes back RIGHT — Google
// forgives a typo silently. So the card was answering "what does this mean" while leaving the wrong
// spelling on screen as the thing you read, learn, and save into Vocab (jek, 2026-08-12).
//
// The correction is free: `dt=qc` is one more parameter on the request we already send, and Google
// answers with the same "Did you mean" block its own site prints. data[7] = [html, plain, [1]] and is
// ABSENT when nothing needed fixing, so its presence IS the signal — no threshold to tune.
// data[7][0] wraps each corrected word in <b><i>…</i></b>, which is how the card can mark the two
// wrong words in a sentence instead of reprinting the whole line. That HTML never leaves this
// function: it is turned into plain tokens here and rebuilt with textContent in the renderer.
const unent = (s) => String(s)
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
function spellFix(data, input) {
  const blk = Array.isArray(data) && Array.isArray(data[7]) ? data[7] : null;
  const plain = blk && typeof blk[1] === 'string' ? blk[1].trim() : '';
  const src = String(input || '').trim();
  // Case-insensitive: games SHOUT their labels and Google hands back "Festering" for "FESTERING".
  // That is not a spelling mistake, and printing it as one would fire on half the HUD in an RPG.
  if (!plain || plain.toLowerCase() === src.toLowerCase()) return null;
  const html = blk && typeof blk[0] === 'string' ? blk[0] : '';
  const parts = [];
  const re = /<b><i>([\s\S]*?)<\/i><\/b>/g;
  let at = 0, m;
  while ((m = re.exec(html))) {
    if (m.index > at) parts.push({ t: unent(html.slice(at, m.index)), fix: false });
    parts.push({ t: unent(m[1]), fix: true });
    at = re.lastIndex;
  }
  if (at < html.length) parts.push({ t: unent(html.slice(at)), fix: false });
  const kept = parts.filter((p) => p.t);
  // The tokens must rebuild the same line they came from. If Google ever changes that markup, the
  // renderer prints `text` plainly instead of a line that silently lost a word.
  const same = kept.map((p) => p.t).join('').trim() === plain;
  return { text: plain, parts: same ? kept : [] };
}

// Two hosts for the same undocumented endpoint, in the same response shape, so one parser reads
// both. This is REDUNDANCY, NOT INDEPENDENCE, and the difference matters: it survives one host being
// rate-limited, blocked on a network, or having a bad day. It does NOT survive Google retiring the
// API, because both are Google — and the free tier of this product stands entirely on an endpoint
// nobody promised us (see PRICING.md §4.5). A genuinely independent fallback costs money per call
// and would change the economics, which is a pricing decision and not a code one.
const FREE_TRANSLATE_HOSTS = [
  'https://translate.googleapis.com/translate_a/single',
  'https://translate.google.com/translate_a/single',
];
async function translateOnceRaw(text, { tries = 3, timeoutMs = 8000 } = {}) {
  if (!text.trim()) return { text: '', pos: '', senses: [] };
  const query = '?client=gtx&sl=auto&tl=' + encodeURIComponent(settings.targetLang) + '&dt=t&dt=bd&dt=qc&q=' + encodeURIComponent(text);
  // The free gtx endpoint intermittently rate-limits (429), stalls, or returns an empty body.
  // Retry a few times with a short backoff + a per-try timeout so a transient blip doesn't read as
  // "translation not working". The live preview passes {tries:1} so it never blocks the drag.
  //
  // The host ROTATES with the attempt rather than being fixed for the call: a retry against the host
  // that just rate-limited us is a retry we already know the answer to. tries:1 therefore still only
  // ever touches the first host, so the drag preview pays nothing for this.
  let lastErr;
  for (let attempt = 0; attempt < tries; attempt++) {
    const url = FREE_TRANSLATE_HOSTS[attempt % FREE_TRANSLATE_HOSTS.length] + query;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      // net.fetch, NOT the global fetch. Same signature, same options, completely different answer
      // from Google: the global one in the main process is Node's undici, and the free gtx endpoint
      // 429s it on sight — the User-Agent header above never mattered, because what gives an undici
      // request away is its TLS/HTTP fingerprint, which no header can dress up. net.fetch goes out
      // through Chromium's own network stack, i.e. the stack Google serves this endpoint to every
      // day, and it is also what Electron documents for requests made from the main process.
      //
      // Measured 2026-08-31 inside ONE Electron 32.3.3 process, same URL, same headers, back to back:
      //   globalThis.fetch  translate.googleapis.com  HTTP 429   (html error page)
      //   net.fetch         translate.googleapis.com  HTTP 200   "การประกัน"
      //   globalThis.fetch  translate.google.com      HTTP 429
      //   net.fetch         translate.google.com      HTTP 200   "การประกัน"
      // Both hosts, every time. This is why rotating hosts and backing off never helped: the request
      // was never going to be answered, so retrying it three times just cost three times as long.
      // A bare `node -e` fetch of the same URL returns 200, which is what made this look transient
      // for an hour — standalone Node ships a different undici than the one bundled in Electron 32.
      const res = await net.fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' }, signal: ctrl.signal });
      if (!res.ok) throw new Error('Translate HTTP ' + res.status);
      const data = await res.json();
      const segments = Array.isArray(data) && Array.isArray(data[0]) ? data[0] : [];
      const out = segments.map(s => (s && s[0]) ? s[0] : '').join('').trim();
      // data[1] = dictionary block (single words only): [ [posName, [terms…], …], … ]. It carries ONE
      // GROUP PER PART OF SPEECH, and only the first was ever read — so a word that is both a noun and
      // a verb lost the other sense entirely ("run" → verb วิ่ง kept, noun การวิ่ง dropped; jek asked
      // about exactly this, 2026-07-30). Keep up to 3 groups × 3 terms: enough for "v. วิ่ง · n. การวิ่ง"
      // without turning a vocab row into a dictionary page.
      const bd = (Array.isArray(data) && Array.isArray(data[1])) ? data[1] : [];
      const senses = bd.slice(0, 3).map((g) => ({
        pos: posAbbr(g && g[0]),
        terms: (Array.isArray(g && g[1]) ? g[1] : []).slice(0, 3).filter(Boolean),
      })).filter((x) => x.terms.length);
      const pos = senses.length ? senses[0].pos : '';
      if (out) return { text: out, pos, senses, spell: spellFix(data, text) };
      throw new Error('empty translation');
    } catch (err) {
      lastErr = err;
      // 429 is not the same failure as the others and must not be retried on the same clock. A
      // timeout, a dead socket or an empty body all mean "this host is having a bad moment", and the
      // very next line rotates to the other host, so a short pause is the whole fix. A 429 means "you
      // asked too fast" — rotating hosts does NOT help, because the throttle is on us, not on them,
      // and 400ms + 800ms is simply not long enough to be forgiven.
      //
      // Measured 2026-08-31 (jek: three snips inside ten seconds, each one translating twice — the
      // drag preview and then the release): all three attempts came back 429 and the pill went red,
      // while the identical request from a cold node process a minute later returned HTTP 200 and
      // "การประกัน" from BOTH hosts. Nothing was blocked; the retries were just too impatient.
      const throttled = /HTTP 429/.test(String(err && err.message));
      if (attempt < tries - 1) {
        // 1.2s then 2.4s — 3.6s of waiting in the worst case, and only for a snip that would
        // otherwise have shown an error. The drag preview passes tries:1 and never reaches here.
        await new Promise(r => setTimeout(r, (throttled ? 1200 : 400) * (attempt + 1)));
      }
    } finally {
      clearTimeout(timer);
    }
  }
  throw lastErr;
}

// ---------- rich card (Claude) ----------

// Swap to 'claude-haiku-4-5' for a cheaper, faster read; Opus is the better linguist.
const CARD_MODEL = 'claude-haiku-4-5-20251001';

const CARD_SCHEMA = {
  type: 'object',
  properties: {
    translation: { type: 'string', description: 'Natural translation of the whole text into the target language' },
    pronunciation: { type: 'string', description: 'How the source text reads, written in the target-language script. Empty string if not useful.' },
    // The AI card's half of the spelling answer (Google's `dt=qc` does the free path — see spellFix).
    // Claude is the better speller HERE because it reads the whole line: OCR damage like "PIS&UISE"
    // is a shape mistake, not a typo, and only context says it was "DISGUISE".
    source: { type: 'string', description: 'The source text with obvious misreadings or typos corrected — game text often arrives mangled by OCR (e.g. "PIS&UISE" for "DISGUISE"). Return the input EXACTLY as given when nothing is wrong. Never translate it, never rephrase it, never change its case or wording for any other reason.' },
    // Split into TWO constrained fields (was one overloaded free-text `type`): what the text IS, and —
    // only for a single word — its part of speech. The old field let the model free-associate a junk POS
    // on an ambiguous capture (e.g. "JP" → pos "JP."). Both are enum'd so nothing arbitrary reaches the UI.
    shape: { type: 'string', enum: ['WORD', 'PHRASE', 'SENTENCE', 'IDIOM'], description: 'The shape of the source text: WORD for one word, PHRASE for a short group, SENTENCE for a full clause, IDIOM for a set expression.' },
    pos: { type: 'string', enum: ['', 'noun', 'verb', 'adjective', 'adverb', 'pronoun', 'preposition', 'conjunction', 'interjection', 'determiner', 'particle', 'numeral', 'name'], description: 'Part of speech — ONLY when shape is WORD (use "name" for a proper noun/acronym). Empty string for PHRASE, SENTENCE, or IDIOM.' },
    meaning: { type: 'string', description: 'One-line explanation (in the target language) of what it means in context' },
    forms: { type: 'string', description: 'SINGLE WORDS ONLY — the other forms a learner has to memorise, separated by " · ", written in the SOURCE language. English verbs: base, past, past participle ("go · went · gone") — include them even when regular. English nouns: only an irregular plural ("child · children"). English adjectives: comparative and superlative ("big · bigger · biggest"). Other source languages: the equivalent core inflections (e.g. a Japanese verb\'s dictionary/te/past forms). Empty string for phrases, sentences, or a word with no forms worth listing.' },
    example: {
      type: 'object',
      properties: {
        en: { type: 'string', description: 'A short natural sentence in the SOURCE language using it' },
        th: { type: 'string', description: 'That sentence translated into the target language' },
      },
      required: ['en', 'th'],
      additionalProperties: false,
    },
  },
  required: ['translation', 'pronunciation', 'source', 'shape', 'pos', 'meaning', 'forms', 'example'],
  additionalProperties: false,
};

function apiKey() {
  return process.env.ANTHROPIC_API_KEY || settings.apiKey || '';
}

// Second pair of eyes for the reads tesseract can't do. It's a threshold-and-shapes engine trained on
// printed documents, so small light-on-dark UI text over busy artwork (a Windows taskbar label on a
// game cover, say) comes back mangled — "Overcooked! 2" as "OVErcooke: U" — or under the quality gate
// entirely. A vision model doesn't binarise anything, so it just reads it.
//
// ONLY runs when tesseract already failed AND a key is set: a call per snip would be slow and paid,
// where the local engine handles the common case (plain HUD text) fine and instantly.
async function claudeReadImage(png) {
  const client = anthropicClient();
  if (!client || !png) return '';
  try {
    const res = await client.messages.create({
      model: CARD_MODEL,
      max_tokens: 512,
      system: 'You read text out of screenshots. Reply with the text EXACTLY as it appears — same characters, same line breaks, nothing else. No quotes, no explanation, no translation. If there is no readable text, reply with nothing at all.',
      messages: [{
        role: 'user',
        content: [
          { type: 'image', source: { type: 'base64', media_type: 'image/png', data: Buffer.from(png).toString('base64') } },
        ],
      }],
    });
    if (res.stop_reason === 'refusal') return '';
    const raw = res.content.find(b => b.type === 'text');
    return raw && raw.text ? raw.text.trim() : '';
  } catch (err) {
    // A failed rescue must never replace the original "couldn't read that" with a network error.
    console.error('Claude image read failed:', err);
    return '';
  }
}

// ---- Word card (the lexicon entry behind Learn's Card mode) ---------------------------------
//
// Everything else the app knows about a word is a translation: what it means. This is the rest of
// what "knowing a word" is — who it keeps company with, how formal it sounds, the mistake a learner
// with THIS first language reliably makes with it, and one more sentence from a different world so
// the word is not welded to the single game line you met it in.
//
// ONE call per word, ever. The answer is stored on the vocab entry and reused for life, so a
// hundred words cost a hundred calls and then nothing — the cost does not grow with how much you
// study, which is the whole reason this shape was chosen over grading free-form answers.
const LEX_SCHEMA = `{"collocations":["…","…","…"],"family":["…","…"],"synonyms":["…","…"],"opposites":["…","…"],"register":"…","mistake":"…","example":"…","prompt":"…"}`;
ipcMain.handle('vocab:lexicon', async (_e, { word, src } = {}) => {
  const clean = String(word || '').trim();
  if (!clean) return { error: 'empty' };
  const client = anthropicClient();
  if (!client) return { error: 'nokey' }; // the UI says "add a key on Plan" rather than failing silently
  const target = targetName();
  try {
    const res = await client.messages.create({
      model: CARD_MODEL,
      max_tokens: 400,
      system:
        `You write dictionary-style usage notes for a learner whose first language is ${target}. ` +
        `Reply with ONLY this JSON, no prose, no code fence: ${LEX_SCHEMA}\n` +
        `collocations: 3 words this one genuinely appears with, most common first — bare words, no explanation.\n` +
        `family: the other forms of this same word, as bare words with their part of speech in brackets — ` +
        `e.g. for "specific": "specifically (adv)", "specificity (n)". 2-4 of them, or an empty array if ` +
        `the word has no common derivations.\n` +
        `synonyms: 2-3 words that come close, each followed by " — " and a SHORT note in ${target} saying ` +
        `how it differs. Near-synonyms that are not interchangeable are the trap this row exists to ` +
        `defuse, so the note matters more than the word.\n` +
        `opposites: 2-3 words that mean the reverse, bare words, no explanation. A word with no real ` +
        `opposite (a concrete noun, a proper noun) gets an empty array — do not stretch for one.\n` +
        `register: how formal it is and where it turns up, at most 8 words, written in ${target}.\n` +
        `mistake: the single error a ${target} speaker most reliably makes with this word — write it in ${target}, ` +
        `and quote the wrong form so they recognise it. If there is no common one, use an empty string.\n` +
        `example: one natural sentence in English using the word in a DIFFERENT setting from the one supplied, ` +
        `at most 12 words.\n` +
        `prompt: a concrete everyday SITUATION, written in ${target}, that would make someone reach for this ` +
        `word — at most 18 words, no example sentence, just the situation.`,
      messages: [{
        role: 'user',
        content: src
          ? `Word: ${clean}\nWhere they met it: ${String(src).slice(0, 300)}`
          : `Word: ${clean}`,
      }],
    });
    if (res.stop_reason === 'refusal') return { error: 'refused' };
    const raw = (res.content.find(b => b.type === 'text') || {}).text || '';
    // The model is asked for bare JSON, but a stray fence or a sentence in front of it must not cost
    // the user the call they already paid for.
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) return { error: 'parse' };
    const j = JSON.parse(m[0]);
    return {
      collocations: Array.isArray(j.collocations) ? j.collocations.slice(0, 3).map(String) : [],
      family: Array.isArray(j.family) ? j.family.slice(0, 4).map(String) : [],
      synonyms: Array.isArray(j.synonyms) ? j.synonyms.slice(0, 3).map(String) : [],
      // Bare words, unlike synonyms: the trap synonyms carry (near-misses that don't swap cleanly)
      // doesn't exist here, so a note per word would be padding.
      opposites: Array.isArray(j.opposites) ? j.opposites.slice(0, 3).map(String) : [],
      register: String(j.register || ''),
      mistake: String(j.mistake || ''),
      example: String(j.example || ''),
      prompt: String(j.prompt || ''),
    };
  } catch (err) {
    console.error('lexicon failed:', err && err.message);
    return { error: aiErrorCode(err) };
  }
});

// Fresh sentences for Recall, a WHOLE SITTING per call. Recall works without this — it falls back to
// the line the word was met in — but that line is one the learner has already read, so the answer can
// be remembered as a picture of the sentence instead of produced from the word. These are new
// settings, which is what makes the exercise a recall rather than a recognition.
//
// Batched on purpose. The lexicon above is one call per word because its answer is a page; this is
// one line per word, so ten of them fit in a single call — a sitting costs ONE request, and the
// result is cached on each entry (`rc`) so the same word never costs a second.
const RECALL_MAX = 12; // a sitting bigger than this is split by the caller; keeps the reply small enough to stay reliable
ipcMain.handle('vocab:recall-set', async (_e, { words } = {}) => {
  const list = (Array.isArray(words) ? words : [])
    .map((w) => ({ word: String((w && w.word) || '').trim(), src: String((w && w.src) || '').slice(0, 160) }))
    .filter((w) => w.word)
    .slice(0, RECALL_MAX);
  if (!list.length) return { error: 'empty' };
  const client = anthropicClient();
  if (!client) return { error: 'nokey' };
  try {
    const res = await client.messages.create({
      model: CARD_MODEL,
      max_tokens: 90 * list.length + 120,
      system:
        `You write gap-fill practice sentences for a language learner. Reply with ONLY a JSON object ` +
        `mapping each word EXACTLY as given to one sentence, no prose, no code fence: {"word":"sentence"}\n` +
        `Each sentence must CONTAIN the word exactly as spelled — do not inflect it, do not translate it, ` +
        `do not use a synonym. A sentence that does not contain the word is useless here.\n` +
        `Each sentence must be a DIFFERENT situation from the one the learner already met the word in, ` +
        `and must not reuse that sentence's distinctive nouns.\n` +
        `At most 14 words. Ordinary, concrete, and specific enough that only this word fits the gap — ` +
        `a sentence where three of the learner's other words would also work teaches nothing.\n` +
        `Use every word given, once each.`,
      messages: [{
        role: 'user',
        content: list.map((w) => (w.src ? `${w.word} — already seen in: ${w.src}` : w.word)).join('\n'),
      }],
    });
    if (res.stop_reason === 'refusal') return { error: 'refused' };
    const raw = (res.content.find(b => b.type === 'text') || {}).text || '';
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) return { error: 'parse' };
    const j = JSON.parse(m[0]);
    // Keep only what the renderer can actually cut a gap into. A sentence that lost the word is worse
    // than no sentence — Recall would fall back mid-list and the sitting would mix the two sources.
    const out = {};
    for (const { word } of list) {
      const s = typeof j[word] === 'string' ? j[word].trim() : '';
      if (s && s.toLowerCase().includes(word.toLowerCase()) && s.length > word.length + 4) out[word] = s;
    }
    return { sentences: out };
  } catch (err) {
    console.error('recall set failed:', err && err.message);
    return { error: aiErrorCode(err) };
  }
});

// Check a sentence the learner wrote using one of their own collected words. This is the rung above
// recognition: Study/Test/Usage all ask whether the word is in your head, and none of them can tell
// you whether you can PUT it somewhere new. Graded, not praised — an AI that says "great job" teaches
// nothing, which is the one thing ELSA gets right.
ipcMain.handle('vocab:check-sentence', async (_e, { word, sentence, situation } = {}) => {
  const w = String(word || '').trim(), sent = String(sentence || '').trim();
  if (!w || !sent) return { error: 'empty' };
  const client = anthropicClient();
  if (!client) return { error: 'nokey' };
  const target = targetName();
  try {
    const res = await client.messages.create({
      model: CARD_MODEL,
      max_tokens: 380,
      system:
        `You mark one English sentence written by a ${target}-speaking learner who was asked to use a ` +
        `given word. Reply with ONLY this JSON: {"verdict":"good|ok|wrong","notes":["…"],"better":"…"}\n` +
        `verdict: "good" = natural and the word is used correctly. "ok" = the word is right but the ` +
        `sentence is awkward or has a small error. "wrong" = the word is not used in a real sense of it.\n` +
        `notes: 1-3 SHORT points written in ${target}, each naming one concrete thing — a wrong tense, a ` +
        `collocation nobody says, the wrong sense of the word. Never praise without a reason. If it is ` +
        `genuinely good, say in one note what specifically works.\n` +
        `better: the same sentence as a native would write it, keeping the learner's meaning. If theirs ` +
        `is already natural, repeat it unchanged.`,
      messages: [{ role: 'user', content: `Word: ${w}\nSituation: ${String(situation || '').slice(0, 200)}\nTheir sentence: ${sent}` }],
    });
    if (res.stop_reason === 'refusal') return { error: 'refused' };
    const raw = (res.content.find(b => b.type === 'text') || {}).text || '';
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) return { error: 'parse' };
    const j = JSON.parse(m[0]);
    return {
      verdict: ['good', 'ok', 'wrong'].includes(j.verdict) ? j.verdict : 'ok',
      notes: Array.isArray(j.notes) ? j.notes.slice(0, 3).map(String) : [],
      better: String(j.better || ''),
    };
  } catch (err) {
    console.error('sentence check failed:', err && err.message);
    return { error: aiErrorCode(err) };
  }
});

let anthropic = null;
// ---------- how a Claude call gets paid for ----------
// Two routes, and the choice is the user's, not ours:
//
//   own key in Settings  ->  straight to Anthropic, unlimited, billed to them, we never see it
//   otherwise            ->  our Worker, on a licence's one-time bundle or the free trial
//
// The proxy exists because "buy the app, then go create an Anthropic account and top it up" loses
// most buyers between those two clauses (see worker/src/index.js). BYOK stays because it is the
// honest answer for anyone who does have a key and doesn't want a ceiling.
// The account's subdomain is part of a workers.dev hostname — `gloss-api.workers.dev` was never a
// name that could resolve, which is why every AI card in every build so far fell back to Google
// without saying so. Deployed 2026-09-04; `wrangler deploy` prints this, and /health answers 200.
const GLOSS_API = process.env.GLOSS_API || 'https://gloss-api.monmon7735.workers.dev';
// The site, not the worker. Bug reports go to the Pages Function next to the download page, which is
// already deployed — the AI worker above is not, and a feedback channel that only works once the
// paid path is live would have missed the whole reason it exists.
const GLOSS_SITE = process.env.GLOSS_SITE || 'https://gloss-6xm.pages.dev';
const GLOSS_TIMEOUT_MS = 15000;

// The free trial has to be counted somewhere, and an account for a 100-read trial is a bigger ask
// than the trial is worth. A random id in settings is enough: it is not an identity, it just stops
// one install from being a hundred.
// The machine's own identifier, hashed. Never sent raw: the id leaves this computer on every proxied
// call, and a hardware serial is the kind of thing that should not sit in someone else's logs.
//
// WHY NOT A RANDOM UUID (which is what this was). The free trial is 100 AI reads counted against
// this id, and a random uuid in settings.json resets by deleting one file — a single sentence on
// Reddit turns the trial into an unlimited one, on our Anthropic bill, and the day the app gets
// attention is exactly the day someone writes that sentence. Derived from the hardware, deleting
// settings.json changes nothing.
//
// This is a speed bump, not a lock — a determined user can still spoof the header entirely (there is
// no app-side fix for that; see underIpCaps in the worker, which is the real defence). It only has
// to be inconvenient enough that the trick isn't worth posting.
function machineFingerprint() {
  const { execFileSync } = require('child_process');
  try {
    if (process.platform === 'darwin') {
      const out = execFileSync('/usr/sbin/ioreg', ['-rd1', '-c', 'IOPlatformExpertDevice'],
        { encoding: 'utf8', timeout: 3000 });
      const m = out.match(/"IOPlatformUUID"\s*=\s*"([^"]+)"/);
      if (m) return m[1];
    } else if (IS_WIN) {
      const out = execFileSync('reg',
        ['query', 'HKLM\\SOFTWARE\\Microsoft\\Cryptography', '/v', 'MachineGuid'],
        { encoding: 'utf8', timeout: 3000, windowsHide: true });
      const m = out.match(/MachineGuid\s+REG_SZ\s+(\S+)/i);
      if (m) return m[1];
    }
  } catch { /* locked-down machine, or the tool isn't there — fall through */ }
  return null;
}

function deviceId() {
  if (!settings.deviceId) {
    const hw = machineFingerprint();
    // Salted so the stored value can't be matched back to a machine by anyone who learns the
    // hardware id from somewhere else; sliced because 32 hex chars is already far past collision.
    settings.deviceId = hw
      ? require('crypto').createHash('sha256').update(`gloss.device.v1:${hw}`).digest('hex').slice(0, 32)
      : require('crypto').randomUUID(); // no fingerprint available — a resettable trial beats no trial
    saveSettings();
  }
  return settings.deviceId;
}

// Live quota, refreshed from the response headers of every proxied call so the UI can show a real
// number without spending a unit to ask for one.
let quotaState = null; // { plan, used, limit }
function quotaSnapshot() { return quotaState; }

// "Is it worth starting a paid read at all?" — for the ONE caller that spends units on a snip which
// already produced usable text (the mixed-language rescue). Everything else in the app either has to
// call regardless (the user pressed ✦) or has nothing to fall back to, and handles the 402 when it
// comes. Own key = no allowance to run out. No quotaState yet = nothing has been spent this session,
// so let the first call be the one that finds out.
function aiAllowanceLeft() {
  if (apiKey()) return true;
  const q = quotaState;
  if (!q || !Number.isFinite(q.limit) || !Number.isFinite(q.used)) return true;
  return q.used < q.limit;
}

// An error the caller can distinguish from a network blip: the user is out of allowance and there
// is something they can actually do about it.
class QuotaError extends Error {
  constructor(info) {
    super('quota exhausted');
    this.gtCode = 'quota';
    this.info = info;
  }
}

// Shaped exactly like the Anthropic SDK client the five call sites already use — same
// `messages.create(body)` in, same parsed response out — so nothing downstream has to know which
// route paid for the answer.
function glossProxyClient() {
  return {
    _gtKey: null,
    messages: {
      create: async (body) => {
        const headers = {
          'content-type': 'application/json',
          'x-gloss-device': deviceId(),
        };
        if (settings.licenceKey) headers['x-gloss-licence'] = settings.licenceKey;

        // Bound the wait. Every caller has a fallback (Google for a translation, an error row in
        // Learn), and all of them are better than a card that never arrives because the proxy is
        // unreachable — which it always is on a build whose Worker isn't deployed yet.
        const abort = new AbortController();
        const timer = setTimeout(() => abort.abort(), GLOSS_TIMEOUT_MS);
        let res;
        try {
          res = await fetch(`${GLOSS_API}/v1/messages`, {
            method: 'POST',
            headers,
            body: JSON.stringify(body),
            signal: abort.signal,
          });
        } catch (err) {
          // A connection failure to OUR host while the machine is plainly online is our outage, not
          // the reader's network — and telling them "no internet" sends them to reboot a router that
          // was never the problem. Today it is every free user, every time: the Worker is not
          // deployed, so the hostname does not resolve at all.
          if (isOfflineError(err)) {
            let online = false;
            try { online = net.isOnline(); } catch { /* assume the error meant what it said */ }
            if (online) { const e = new Error('gloss AI unreachable'); e.gtCode = 'aidown'; throw e; }
          }
          throw err;
        } finally {
          clearTimeout(timer);
        }

        if (res.status === 402) {
          const info = await res.json().catch(() => ({}));
          // A ceiling on the whole service, not on this user. Their own allowance is untouched, so
          // leave quotaState alone — overwriting it with the empty body would show them a number
          // they have not actually spent.
          if (info.error === 'paused') {
            // 'paused' now covers two ceilings, and they do not end the same way: the daily one lifts
            // by itself at midnight, the total one only when its owner raises it. Saying "try again
            // tomorrow" for the second is a promise the service will not keep, so say the part that
            // is true of both — translation still works, and a key of your own has no ceiling at all.
            setHintState('AI reads are paused — translation keeps working. Add your own Claude key in Settings to carry on without a limit');
            throw new QuotaError(info);
          }
          quotaState = { plan: info.plan, used: info.used, limit: info.limit };
          // Every window that shows the count is looking at the settings snapshot, and nothing was
          // republishing it when the number moved — so Settings could sit on "998 left" for an hour
          // of reading. The counter is part of that snapshot; changing it is a settings change.
          sendAll('settings:changed', uiSettings());
          // Say it once here rather than at five call sites, each of which would word it differently.
          setHintState(info.plan === 'free'
            ? 'Free AI reads used up — unlock Gloss Pro, or add your own Claude key in Settings'
            : 'Your AI reads are used up — translation still works. Top up, or add your own Claude key for no limit');
          throw new QuotaError(info);
        }
        if (res.status === 401) {
          // Same rule as licence:verify — a 401 that says the Worker is missing its own secret is
          // our fault, not a bad key, and must not be reported as one to someone who paid.
          const why = await res.clone().json().then((d) => d && d.reason).catch(() => null);
          if (why === 'unconfigured') {
            setHintState('AI is not answering right now — translation keeps working');
            throw new Error('ai unconfigured');
          }
          setHintState('That Gloss licence key was not accepted — check it in Settings');
          throw new Error('licence rejected');
        }
        // The abuse caps answer 429. Almost everyone who sees this is a real person behind a shared
        // connection — an office, a dorm, a café — so it is worded as a wait, not an accusation, and
        // it names the way out that doesn't involve waiting at all.
        if (res.status === 429) {
          setHintState('Too many reads from this network right now — wait a minute, or add your own Claude key in Settings');
          throw new Error('rate limited');
        }
        if (!res.ok) throw new Error(`proxy ${res.status}`);

        const used = Number(res.headers.get('x-gloss-used'));
        const limit = Number(res.headers.get('x-gloss-limit'));
        if (Number.isFinite(used) && Number.isFinite(limit)) {
          quotaState = { plan: res.headers.get('x-gloss-plan') || 'free', used, limit };
          sendAll('settings:changed', uiSettings());   // same reason as the 402 branch above
        }
        return res.json();
      },
    },
  };
}

function anthropicClient() {
  const key = apiKey();
  if (key) {
    if (!anthropic || anthropic._gtKey !== key) {
      anthropic = new Anthropic({ apiKey: key });
      anthropic._gtKey = key;
    }
    return anthropic;
  }
  // No personal key. Everyone still gets AI — a licence buys a bundle of reads, and without one
  // the free trial covers the first reads so a buyer can find out whether it reads THEIR game
  // before being asked for anything.
  return glossProxyClient();
}

// With a key: one Claude call returns the whole card. Without: Google gives the
// translation and the rest of the card stays empty.
// `useAi` decides who does the work, and it is the difference between a card that costs nothing and
// one that costs money. Google returns a sentence; Claude returns the sentence PLUS pronunciation,
// word shape, part of speech and an example — the thing the app is actually sold on.
//
// It defaults to OFF, which reverses how this worked until 2026-08-06. Every snip used to go to
// Claude, so the app paid for a full learner's card even when the player only wanted to know what a
// line said and would never look at it again. Live captions already worked this way (see the note on
// liveTimer — "a Claude call per subtitle would be slow + paid"); this just applies the same
// reasoning to the thing people do most. The full card is now a button on the card itself, which has
// the side effect of making the paid feature VISIBLE rather than something that happens invisibly on
// every read.
// Same shape as spellFix's answer, from the model's `source` field. Fenced, because a schema field is
// an invitation to be helpful: only a same-language rewrite of a similar length counts as a SPELLING,
// and anything that came back as the translation itself is the model answering the wrong question.
function aiSpell(source, input) {
  const fixed = String(source || '').trim();
  const src = String(input || '').trim();
  if (!fixed || !src || fixed.toLowerCase() === src.toLowerCase()) return null;
  if (Math.abs(fixed.length - src.length) > Math.max(4, src.length * 0.35)) return null;
  return { text: fixed, parts: [] };
}

// Han, kana and hangul in an answer that was asked for in Thai. Deliberately not "does it contain
// Thai": a mostly-Thai line with two Chinese words in it passes that test, and that is exactly the
// shape this exists to catch. Only meaningful while the target is a script none of these belong to,
// so it says so rather than firing on a Japanese learner's perfectly good Japanese card. Borrows the
// CJK_RE the word-splitter already defines further down — same question, and two copies of a range
// like that drift.
// Its own range rather than CJK_RE further down: that one deliberately leaves Hangul OUT, because it
// answers a different question (is this one word, for a script that writes without spaces — and
// Korean does write spaces). Here Hangul belongs: a Thai card with a Korean word in it is exactly as
// wrong as one with a Chinese word in it, and the comment claimed to cover it while the shared range
// never did.
const OFF_SCRIPT_RE = /[ᄀ-ᇿ぀-ヿ㐀-鿿가-힯豈-﫿]/;
function wrongScript(value) {
  if (!value || typeof value !== 'string') return false;
  const target = (settings.targetLang || 'th');
  if (target === 'ja' || target === 'zh-CN' || target === 'ko') return false;
  return OFF_SCRIPT_RE.test(value);
}

// The most one card is allowed to cost, expressed as the only input we control. Measured 2026-09-08
// against the live worker: a 2,256-character snip cost THB 0.14 and worked; 5,000 characters failed
// on its own (the card is a JSON schema of fields, and a page of prose does not fit one) and 32,000
// never reached Claude at all. So the ceiling is not there to stop a bill that was climbing — the
// bill flattens, because max_tokens caps the answer at 1024 either way. It is there so the failure
// is a SENTENCE the user can act on instead of a card that silently came back truncated: refusing at
// 3,000 costs nothing and says why, while letting it through spends a read to produce a stub.
//
// With this, the worst a single card can cost is provable: 3,000 chars of user text (~850 tok) plus
// the fixed schema (~990 tok) plus a full 1024-token answer = THB 0.225. Every price rests on that
// number rather than on hoping nobody sweeps a whole screen.
const AI_CARD_MAX_CHARS = 3000;

async function buildCard(text, useAi = false) {
  // Checked before the client is built so the read is never spent — see AI_CARD_MAX_CHARS. The
  // Google path below has no such limit and still answers, so the user keeps a translation; only
  // the fuller card is refused, and card:ai turns this code into the line that explains it.
  if (useAi && String(text || '').length > AI_CARD_MAX_CHARS) {
    const g = await translate(text);
    return { th: g.text, pos: g.pos, senses: g.senses || [], spell: g.spell || null, aiError: 'toolong' };
  }
  const client = useAi ? anthropicClient() : null;
  if (!client) {
    try {
      const g = await translate(text);
      const senses = (g.senses && g.senses.length) ? g.senses : ((localWordAnswer(text) || {}).senses || []);
      const pos = g.pos || posFromLocalDict(text);
      wordCachePut(text, { text: g.text, pos, senses }); // single words only — wordCachePut decides
      return { th: g.text, pos, senses, spell: g.spell || null };
    } catch (err) {
      // The card without a key IS the free endpoint, so this is the last place a lookup can fail with
      // the answer already on disk. Single words only — the dictionary has no opinion on a sentence.
      const local = offlineWordAnswer(text);
      if (local) return { th: local.text, pos: local.pos, senses: local.senses, spell: null, offlineDict: true };
      throw err;
    }
  }

  // A bad key, a rate limit, no network, a refusal, or a malformed/parse-failed
  // response should never lose the translation — fall back to the free endpoint.
  try {
    const res = await client.messages.create({
      model: CARD_MODEL,
      max_tokens: 1024,
      // Naming the source beats asking for detection when the source cannot change: a locked build
      // knows it is English, and a model told so stops hedging between kanji readings and English
      // homographs on a short line.
      system: `You translate game text into ${targetName()} for a ${targetName()} learner. ${PAIR_LOCK
        ? 'The source is English.'
        : 'The source may be any language (English, Japanese, Chinese, Korean, …) — detect it.'} All card fields (translation, pronunciation, meaning, example.th) must be written in ${targetName()}. Be concise and natural — no preamble.`,
      output_config: { format: { type: 'json_schema', schema: CARD_SCHEMA } },
      messages: [{ role: 'user', content: text }],
    });

    if (res.stop_reason === 'refusal') throw new Error('Claude refused');
    const raw = res.content.find(b => b.type === 'text');
    if (!raw || !raw.text) throw new Error('Claude returned no text');
    const card = JSON.parse(raw.text);
    if (!card.translation) throw new Error('Claude returned no translation');

    // Measured 2026-09-07 on "the merchant refuses to sell the cursed blade": the model answered
    // "พ่อค้าปฏิเสธที่จะขาย劍ที่ถูก诅咒" — Thai with the two hard words left in Chinese. The system
    // prompt already asks for Thai and asking harder is not a fix, because the failure is silent and
    // lands in the headline: the one line a buyer reads. So the answer is checked rather than
    // trusted, and a field carrying the wrong script is dropped in favour of the free translation,
    // which was correct on the same line ("พ่อค้าไม่ยอมขายดาบที่ถูกสาป").
    if (wrongScript(card.translation)) {
      console.warn('Claude card: translation not in the target script, using the free one');
      const g = await translate(text).catch(() => null);
      if (!g || !g.text) throw new Error('Claude returned the wrong script');
      card.translation = g.text;
    }
    if (wrongScript(card.meaning)) card.meaning = '';
    if (card.example && wrongScript(card.example.th)) card.example = null;

    return {
      th: card.translation,
      spell: aiSpell(card.source, text),
      pronunciation: card.pronunciation || '',
      pos: card.pos || '',              // real POS now (enum'd); only set when shape=WORD
      meaning: card.meaning || '',
      forms: card.forms || '',
      example: card.example || null,
    };
  } catch (err) {
    // Fall back to the free endpoint silently — a Claude hiccup shouldn't flash an error when the
    // Google fallback is about to succeed. If the fallback ALSO throws, translateOnce/translateText's
    // own catch surfaces the real failure.
    console.error('Claude card failed, falling back to Google:', err);
    // …but keep WHY on the card. The fallback answer is correct for an ordinary translation and the
    // caller should not flinch — yet card:ai has to tell the user what happened, and the only thing
    // that knows is this catch. Without it the ✦ button reported "check your AI allowance" while the
    // truth was that our own proxy does not resolve: the app blaming the user for our outage. The
    // Learn window has said the honest sentence for weeks (learn/i18n.js net.aidown); this is the
    // same fact, and it must not have two answers. (review, 2026-08-15)
    const g = await translate(text);
    const out = { th: g.text, pos: g.pos, senses: g.senses || [], spell: g.spell || null };
    if (err && err.gtCode) out.aiError = err.gtCode;   // 'aidown' | 'quota'
    return out;
  }
}

// Pick 2-5 useful/difficult words out of a sentence for the vocab collection. Needs a Claude key —
// the free Google endpoint can't do word-level extraction, only whole-text translation.
// Split a line into EVERY word, in order — not "the useful ones". Japanese/Chinese/Thai don't put
// spaces between words, so the offline chip-splitter (whitespace) hands back one giant chip and
// tap-to-pick is useless there. This does the one job a model is genuinely better at than a regex;
// deciding which words are worth learning stays with the user, who is the only one who knows which
// ones they keep forgetting.
async function segmentWords(text) {
  const client = anthropicClient();
  if (!client) return { needKey: true };

  try {
    const schema = {
      type: 'object',
      properties: {
        words: {
          type: 'array',
          items: { type: 'string', description: 'One word, exactly as it appears in the source text, in order' },
        },
      },
      required: ['words'],
      additionalProperties: false,
    };
    const res = await client.messages.create({
      model: CARD_MODEL,
      max_tokens: 1024,
      system: 'Split the given text into its individual words, in the order they appear. Detect the language. Keep each word exactly as written in the source — do not translate, conjugate, or normalise. Drop pure punctuation. Be concise — no preamble.',
      output_config: { format: { type: 'json_schema', schema } },
      messages: [{ role: 'user', content: text }],
    });

    if (res.stop_reason === 'refusal') throw new Error('Claude refused');
    const raw = res.content.find(b => b.type === 'text');
    if (!raw || !raw.text) throw new Error('Claude returned no text');
    const data = JSON.parse(raw.text);
    const words = Array.isArray(data.words) ? data.words.filter(w => typeof w === 'string' && w.trim()) : [];
    if (!words.length) throw new Error('Claude returned no words');
    return { words };
  } catch (err) {
    console.error('Word split failed:', err);
    return { error: errorForPill(err) };
  }
}

// Each translate request (snip or typed) gets a generation number. A slower older request must
// never clobber the card/status of a newer one that already landed — stale results still go into
// history but are not shown (the renderer checks payload.gen), and stale errors are dropped here.
let transGen = 0;
let ocrBusy = false; // one capture+OCR at a time — a rapid re-trigger that arrives mid-OCR is dropped
                     // rather than piling onto the single (slow, on Windows) Tesseract worker.

// Drag once, translate once. Read what was under the box at the moment it was
// released, then show the result inside the pill (which expands, holds, and
// collapses back on its own).
async function translateOnce(bounds, cachedText, preCap) {
  if (!checkScreenPermission()) return;
  const gen = ++transGen;
  const stale = () => gen !== transGen; // a newer snip/typed request started after this one
  setHintState(cachedText ? 'Translating…' : 'Reading…');
  sendMain('result:loading', true); // spin the dot; the previous result stays until this lands

  try {
    // Reuse the reading the live preview already OCR'd (same box) — skips a full duplicate capture+
    // OCR pass on release, which was the main source of "slow" (it also queued behind the discarded
    // preview OCR in the single Tesseract worker). Only OCR here when there's nothing to reuse.
    let normalized = cachedText || '';
    // Set when Claude read the crop because the line turned out to hold more than one alphabet. It
    // decides the CARD too, further down: a mixed line read correctly and then translated by the free
    // endpoint is only half a feature (see the note there).
    let mixedRead = false;
    if (!normalized) {
      // Drop this read if a capture+OCR is already running — mashing the trigger would otherwise queue
      // slow tesseract passes and thrash the CPU (the "lag when translating very fast"). The dot is
      // already spinning from that in-flight read, so just bow out quietly.
      if (ocrBusy) { sendMain('result:loading', false); return; }
      ocrBusy = true;
      try {
        const cap = preCap || await captureRegion(padBounds(bounds));
        if (stale()) return; // a newer request owns the dot/card now — don't touch them
        if (!cap) { sendMain('result:loading', false); sendMain('translation:error', "Couldn't capture that area — try boxing away from the screen edge"); return; }
        const ocr = await recognizeImage(cap.image, true);
        normalized = normalizeLines(ocr.text);
        dumpOcrDebug(cap.image.toPNG(), ocr, { keptConfidence: ocr.confidence, garbage: looksLikeGarbage(normalized) });
        if (stale()) return;
        // A CONFIDENT but very short read ("ok", "hi", "no", "go") trips looksLikeGarbage's <3-char rule
        // yet is almost certainly a real word. When there's no Claude key the rescue below can only return
        // '' — a guaranteed dead-end "Blurry" — so trust the confident short read and translate it instead
        // of leaving free-tier users unable to translate any 2-letter word (jek 2026-07-26).
        const trustShortNoKey = !anthropicClient()
          && normalized.trim() && !lowConfidence(ocr)
          && normalized.replace(/\s+/g, '').length < 3;
        const failed = !trustShortNoKey
          && (!normalized.trim() || lowConfidence(ocr) || looksLikeGarbage(normalized));
        // The fourth reason to ask Claude, and the only one that fires on a read the gates above were
        // HAPPY with: the line is written in an alphabet the engine was not set up for (see looksMixed).
        // Every check above judges quality, and a mixed line has good quality — of the half the engine
        // could read. Gated on the setting and on there being allowance left, because unlike the other
        // three this one spends 2 units on a snip that already produced usable text.
        const mixed = !failed && settings.aiMixedRead && aiAllowanceLeft()
          && looksMixed(normalized, settings.sourceLang);
        // The fifth reason, and the only one that is about the MACHINE rather than this crop: there is
        // no native reader for this language here, so the text came from tesseract, which on CJK is
        // wrong often and confident about it. Waiting for a quality gate to catch that does not work —
        // the gates are what it slips past. See nativeOcrMissing.
        const noPack = !failed && !mixed && settings.aiMixedRead && aiAllowanceLeft()
          && nativeOcrMissing(settings.sourceLang);
        if (failed || mixed || noPack) {
          // Hand the SAME crop to Claude before giving up (no-op without a key). The read still goes
          // through normalizeLines so the rest of the pipeline is identical.
          setHintState(mixed ? 'More than one language — asking AI…' : noPack ? 'No local reader — asking AI…' : 'Reading harder…');
          const rescued = normalizeLines(await claudeReadImage(cap.image.toPNG()));
          if (stale()) return;
          if (!rescued.trim()) {
            // A rescue that comes back empty ends the road for a line nobody could read. For a MIXED
            // line it must not: the OCR text was good enough to pass every quality gate, so keep it and
            // translate that. Turning a usable read into "Blurry" because the paid path was offline or
            // out of allowance would make the feature strictly worse than not having it.
            // Same reasoning as `mixed` for noPack: the tesseract text passed the quality gates, so it
            // is the best answer available when the AI trip cannot be made. Better a shaky translation
            // than "Blurry" on a read that was never asked to be good.
            if (!mixed && !noPack) {
              sendMain('result:loading', false);
              sendMain('ocr:lowquality', { confidence: Math.round(ocr.confidence), text: normalized.slice(0, 60) });
              return;
            }
          } else {
            normalized = rescued;
            // Only when the read actually landed. A failed one means no key, no network, or no
            // allowance — all three would fail the card call too, so don't queue a doomed second trip.
            // Either reason means Claude produced this text, and the card call downstream keys off
            // that — not off which of the two asked for it.
            mixedRead = mixed || noPack;
          }
        }
      } finally {
        ocrBusy = false;
      }
    }

    // A mixed line goes to Claude for the CARD as well, whatever the AI-cards setting says. The free
    // endpoint is called with sl=auto, which detects ONE language per request — the minority language
    // in the line comes back untranslated, so a read that finally captured both halves would be handed
    // to a translator that can only answer for one of them. Claude is given the whole line at once and
    // its prompt already says the source may be any language. buildCard falls back to Google by itself
    // on any error, so this cannot dead-end (jek, 2026-08-13).
    const card = await buildCard(normalized, mixedRead || settings.aiCards);
    if (!card.th) { if (stale()) return; sendMain('result:loading', false); sendMain('translation:error', 'No translation came back — check your connection'); return; }

    const payload = { en: normalized, ts: Date.now(), ...card };
    // What a tap-right-after-the-drag would keep. Set here rather than read out of history so the
    // gesture cannot pick up a row that arrived from somewhere else (CC, a typed line) in between.
    lastSnipCard = { payload, at: Date.now() };
    keepArmedCard(payload); // a tap during the read already asked for this one
    rememberHistory(payload);
    saveHistory();
    bumpStats(payload); // Insights tally — survives history's 300-row cap
    sendAll('translation:new', { ...payload, gen }); // gen stays out of the saved history — broadcast to the pill AND the learn window's History tab
  } catch (err) {
    console.error('One-shot translate failed:', err);
    if (stale()) return;
    sendMain('result:loading', false);
    sendMain('translation:error', errorForPill(err));
  } finally {
    // The arm belongs to THIS snip. Every early return above — no permission, OCR busy, nothing read,
    // a newer snip already started, no translation — leaves without a card, and until now left the
    // arm standing for the full 15s: the NEXT snip, which nobody asked to keep, was silently
    // collected instead. mouseHookDown clears it too, but only in 'hold' style; 'drag' never goes
    // through that function, and 'drag' is the style this was reported from.
    keepArmedAt = 0;
    applyContentProtection(); // un-hide the pill from capture now the OCR frame is grabbed
  }
}

// Typed input skips OCR entirely — no capture, no misreads, no garbage tokens.
// Same translate → card → history → render path as a snip.
// `origin` — 'type' when the text was keyed in, 'speak' when the recogniser heard it. Both skip OCR
// and share this whole path, which is why a spoken line used to arrive in History indistinguishable
// from a typed one: it set `typed: true` and nothing else. It still sets `typed` (every consumer of
// that flag means "not a read", and that is still true), and ADDS `spoken` on top rather than
// replacing it — additive, so nothing that already tests `typed` changes behaviour.
async function translateText(text, origin = 'type') {
  const clean = (text || '').trim();
  if (!clean) return;
  const gen = ++transGen;
  const stale = () => gen !== transGen;
  setHintState('Translating…');
  sendMain('result:loading', true);
  try {
    const card = await buildCard(clean, settings.aiCards);
    if (!card.th) { if (stale()) return; sendMain('result:loading', false); sendMain('translation:error', 'No translation came back — check your connection'); return; }
    const payload = { en: clean, ts: Date.now(), typed: true, spoken: origin === 'speak' || undefined, ...card };
    rememberHistory(payload);
    saveHistory();
    bumpStats(payload); // Insights tally — survives history's 300-row cap
    sendAll('translation:new', { ...payload, gen }); // broadcast — the learn window's History tab listens too
  } catch (err) {
    console.error('Typed translate failed:', err);
    if (stale()) return;
    sendMain('result:loading', false);
    sendMain('translation:error', errorForPill(err));
  }
}

// Upgrade a card that Google already answered: same source text, run through Claude this time, and
// replace the row in history so the fuller version is what gets saved, reviewed and exported. The
// text is re-sent by the renderer rather than looked up by index because history can shift under a
// card that has been sitting open (a live caption, another snip) and upgrading the wrong row is
// worse than not upgrading at all.
ipcMain.handle('card:ai', async (_e, text) => {
  const clean = String(text || '').trim();
  if (!clean) return { ok: false };
  try {
    const card = await buildCard(clean, true);
    if (!card.th) return { ok: false };
    // buildCard falls back to Google when Claude is unreachable — right for an ordinary translation,
    // wrong here. The user pressed a button that says "full card"; handing back the same Google line
    // and reporting success is the silent no-op this app has been full of. If none of the AI fields
    // came through, the upgrade did not happen, and the caller must be told so it can say why.
    if (!(card.pronunciation || card.meaning || card.forms || card.example)) {
      // Name the cause when there is one. 'aidown' = our proxy could not be reached, which is not
      // something the user can check, fix, or be at fault for.
      return { ok: false, error: card.aiError || 'ai-unavailable' };
    }
    const payload = { en: clean, ts: Date.now(), ai: true, ...card };
    // Replace the most recent entry for this exact source rather than pushing a duplicate — the user
    // asked for a better answer to a question they already asked, not for a second question.
    const at = history.findIndex((h) => h && h.en === clean);
    if (at >= 0) history[at] = { ...history[at], ...card, ai: true };
    else history.unshift(payload);
    saveHistory();
    sendAll('translation:new', { ...payload, upgraded: true });
    return { ok: true };
  } catch (err) {
    console.error('card upgrade failed:', err && err.message);
    return { ok: false, error: errorForPill(err) };
  }
});

// The ✎ line is a BUTTON, not a footnote. "This is how it is really spelled" answers half the question
// while the translation above it is still the misread's: jek's card read "hostalgia" and said โฮสเทล,
// with ✎ nostalgia sitting under it and no way to say "then translate THAT" (2026-08-13). Tapping the
// line re-translates the corrected text; the card it builds carries `respelled` = the words that were
// actually read, so it can offer the way back. A correction the reader cannot undo is a guess made on
// their behalf — and OCR is not right often enough to earn that.
//
// ONE read, ONE history row: this REPLACES the row instead of filing the same moment twice, keeps its
// timestamp (that is when you read it) and its source flags (a snip stays a snip in the History
// filters), and keeps `respelled` on the stored row so reopening it from History months later still
// offers the way back.
//
// `use` is a card the renderer already holds — the version it just swapped away from. Going back and
// forth is then free: no network, and with AI cards on, no Claude call either.
ipcMain.handle('card:respell', async (_e, arg) => {
  const to = String((arg && arg.to) || '').trim();
  const from = String((arg && arg.from) || '').trim();
  if (!to || to === from) return { ok: false };
  try {
    const use = arg && arg.use;
    // Rebuilt field by field rather than spread: a payload from the renderer is not a card, and the
    // half of it that is bookkeeping (en, ts, live/typed flags) is decided HERE, from the row.
    const card = (use && use.th)
      ? { th: String(use.th), pos: use.pos || '', senses: use.senses || [], spell: use.spell || null,
          pronunciation: use.pronunciation || '', meaning: use.meaning || '', forms: use.forms || '',
          example: use.example || null }
      : await buildCard(to, settings.aiCards);
    if (!card.th) return { ok: false, error: 'no-translation' };
    const at = from ? history.findIndex((h) => h && h.en === from) : -1;
    const was = at >= 0 ? history[at] : null;
    const payload = {
      en: to,
      ts: was ? was.ts : Date.now(),
      // Which way the card was read is a fact about the READ, not about the spelling — carry it over
      // so srcOf() keeps answering the same thing after a swap.
      live: was ? was.live : undefined, typed: was ? was.typed : undefined, point: was ? was.point : undefined,
      spoken: was ? was.spoken : undefined,
      ai: was ? was.ai : undefined,
      respelled: from || null,
      ...card,
    };
    if (at >= 0) history[at] = payload; else history.unshift(payload);
    saveHistory();
    sendAll('translation:new', payload); // one render path — the card and the learn window both listen
    return { ok: true };
  } catch (err) {
    console.error('respell failed:', err && err.message);
    return { ok: false, error: errorForPill(err) };
  }
});

function setHintState(msg) {
  sendMain('hint', msg);
}

// ---------- Live subtitle mode ----------
// Draw the subtitle strip ONCE (usually the bottom of the screen), then the app re-reads that
// region every second and pushes a fresh translation whenever the text changes — no re-snipping
// per line. Uses the free Google endpoint only (a Claude call per subtitle would be slow + paid).
let liveTimer = null;     // pending setTimeout for the NEXT poll (null while a poll is in flight)
let liveOn = false;       // authoritative "CC mode running" flag — liveTimer alone goes null mid-poll
let livePicking = false;  // the next snip drag defines the live region instead of translating once
let liveRegion = null;    // absolute screen bounds of the subtitle strip (mirrors settings.ccRegion)
let liveLastText = '';    // last text we already translated
let livePendingText = null; // candidate awaiting a second identical read (mid-fade frames misread)
let liveBusy = false;
let liveOffline = false;  // the network dropped mid-session: say it ONCE, then keep quiet until it's back
const LIVE_POLL_MS = 1200; // default GAP between reads; overridable via settings.ccIntervalMs

function liveActive() { return liveOn; }

function livePace() {
  const v = Number(settings.ccIntervalMs);
  return Number.isFinite(v) && v >= 300 ? v : LIVE_POLL_MS;
}

// Self-paced loop: schedule the next poll only AFTER the current one fully settles, so a slow (Windows
// tesseract) read never overlaps the next tick or pegs the CPU — the gap is always livePace() of idle
// time BETWEEN reads. Replaces the old fixed setInterval, which could stack reads when OCR ran long.
function scheduleLivePoll() {
  if (!liveOn) return;
  liveTimer = setTimeout(async () => {
    liveTimer = null;
    await livePoll();
    scheduleLivePoll();
  }, livePace());
}

function startLive(bounds) {
  stopLive();
  liveRegion = bounds;
  // Written the moment it is picked, not on quit: a crash or a kill mid-session would otherwise cost
  // the answer, and this is the one thing in CC that takes a drag to replace.
  settings.ccRegion = { x: bounds.x, y: bounds.y, width: bounds.width, height: bounds.height };
  saveSettings();
  liveLastText = '';
  livePendingText = null;
  // Our own card can sit right on top of the subtitle strip — hide the overlay from capture while
  // live mode runs so we never OCR our own translation back. Restored by stopLive().
  setProtect(mainWindow, true);
  liveOn = true;
  scheduleLivePoll();
  sendMain('live:state', true);
  setHintState('Live · watching subtitles');
}

function stopLive() {
  if (!liveOn && !liveTimer) return;
  liveOn = false;
  if (liveTimer) { clearTimeout(liveTimer); liveTimer = null; }
  liveBusy = false;
  liveOffline = false;
  applyContentProtection(); // back to the user's hideFromCapture preference
  sendMain('live:state', false);
  setHintState('⌘⇧S');
}

async function livePoll() {
  if (liveBusy || snipping) return; // never overlap reads, never fight the snip overlay
  // Permission can be revoked mid-session — without this the loop failed silently every second
  // forever. checkScreenPermission also surfaces the permission:needed banner.
  if (!checkScreenPermission()) { stopLive(); return; }
  // No network = no translation, so the whole poll is wasted work: a full screen grab plus a tesseract
  // WASM read (the slow Windows path) every second, thrown away every second, while the pill kept
  // saying "Live · watching subtitles" and nothing ever appeared. Say why, spend nothing, and pick the
  // captions back up by itself the moment the connection returns — CC is a mode you leave running, so
  // ending it on a dropped Wi-Fi would be the wrong answer too.
  let online = true;
  try { online = net.isOnline(); } catch { /* older builds: assume online and fail the normal way */ }
  if (!online) {
    if (!liveOffline) { liveOffline = true; setHintState('No internet'); }
    return;
  }
  if (liveOffline) { liveOffline = false; setHintState('Live · watching subtitles'); }
  liveBusy = true;
  try {
    const cap = await captureRegion(padBounds(liveRegion));
    if (!cap) return;
    // Arbitrated here too, despite this being the timed path. The second read is only taken when the
    // dictionary sees a word it doesn't know, and a warm tesseract pass measured 69-126ms against a
    // poll gap of ccIntervalMs (1200ms default) — the same misread that ruins a snip ruins every
    // subtitle line that carries it, so paying a tenth of the gap for it is the right trade.
    const ocr = await recognizeImage(cap.image, true);
    const text = normalizeLines(ocr.text);
    if (!text.trim() || lowConfidence(ocr) || looksLikeGarbage(text)) { livePendingText = null; return; }
    if (text === liveLastText) { livePendingText = null; return; }
    // Require the same NEW text twice in a row — a subtitle mid-fade or mid-typewriter reads as a
    // partial line once, then stabilizes on the next poll.
    if (text !== livePendingText) { livePendingText = text; return; }
    livePendingText = null;
    liveLastText = text;
    // Take the gen number BEFORE the await, like translateOnce/translateText do — taking it at send
    // time let a SLOW live translate finish after a newer manual snip yet claim a higher gen and
    // steal the card back from the translation the user was reading.
    const gen = ++transGen;
    const g = await translate(text);
    if (!g.text) return;
    const payload = { en: text, th: g.text, pos: g.pos, spell: g.spell || null, ts: Date.now(), live: true };
    rememberHistory(payload);
    saveHistory();
    bumpStats(payload); // Insights tally — survives history's 300-row cap
    sendAll('translation:new', { ...payload, gen }); // broadcast — the learn window's History tab listens too
  } catch (err) {
    console.error('Live poll failed:', err); // keep polling — one bad frame must not kill the mode
  } finally {
    liveBusy = false;
  }
}

// Toggle from the pill's CC button. ON always starts with drawing the strip — the drag doubles as
// visual confirmation of exactly what will be watched.
// Open the strip picker. Always — this is the "where are the subtitles" question, and the answer can
// change (a different game, a different resolution, a cutscene that puts them somewhere else).
function doLivePick() {
  // A Windows snip armed and waiting for its drag owns the mouse hook (it swallows every click and wheel)
  // and the Esc key. CC picking opens its own overlay and would leave that hook armed with nothing
  // able to cancel it — the cursor would keep eating clicks system-wide. Stand it down first.
  if (winSnipArmed) cancelWinSnip();
  if (liveActive()) stopLive(); // re-picking mid-session: stop reading the old strip first
  if (livePicking) { closeSnipWindows(); return; } // pick again while picking = cancel
  if (!checkScreenPermission()) return;
  livePicking = true;
  sendMain('live:picking', true); // renderer steps the pill aside + knows CC-cancel is armed
  // Hide the pill from capture ALREADY during picking — the default strip overlaps the pill's home
  // dock, so without this the edit-box preview OCR'd the pill itself, got garbage, and showed
  // nothing ("instant translation doesn't work when adjusting the CC area").
  setProtect(mainWindow, true);
  doSnipStart();
}

// Is a remembered strip still somewhere we can read? A display can leave between sessions of CC
// (unplugged, resolution changed), and resuming onto coordinates that are no longer on any screen
// would start a watch loop that captures nothing and says nothing about why.
function liveRegionUsable() {
  // Restored lazily rather than at load: settings are read before any display information is
  // meaningful, and the check below is the only place that has to care whether it is still on screen.
  if (!liveRegion && settings.ccRegion && typeof settings.ccRegion.width === 'number') {
    liveRegion = { ...settings.ccRegion };
  }
  if (!liveRegion) return false;
  try {
    const d = screen.getDisplayMatching(liveRegion).bounds;
    return liveRegion.x + liveRegion.width > d.x && liveRegion.x < d.x + d.width
        && liveRegion.y + liveRegion.height > d.y && liveRegion.y < d.y + d.height;
  } catch { return false; }
}

// ON and OFF, and nothing else. It used to open the strip picker on every single start, so the key
// that is supposed to switch subtitles on answered with a drag-a-box overlay instead — "พอกด
// Alternate C แล้วมันกลายเป็น Edit ตัวขนาดของ subtitle" (jek, 2026-08-09). The strip was already
// remembered in liveRegion; nothing was asking for it. Picking is its own action now (doLivePick,
// the Choose area button), which is also the honest split: where the subtitles are is a question you
// answer once per game, and whether you want them is a question you answer mid-fight.
function doLiveToggle() {
  if (winSnipArmed) cancelWinSnip();
  if (liveActive()) { stopLive(); return; }
  if (livePicking) { closeSnipWindows(); return; } // CC again while adjusting the box = cancel
  if (liveRegionUsable()) {
    if (!checkScreenPermission()) return;
    startLive(liveRegion);
    return;
  }
  doLivePick(); // first time this session (or the old strip is off-screen) — ask where to look
}

// ---------- actions (shared by IPC and global shortcuts) ----------

// Windows: capture the screen FIRST (clean, before the overlay shows), then open the overlay showing
// that still image. Dragging happens over the frozen shot — macOS composites overlays over live video
// fine, so it keeps the direct live path (startFrozenSnip is win32-only, see doSnipStart).
async function startFrozenSnip() {
  if (snipStarting) return;
  snipStarting = true;
  try {
    const cursor = screen.getCursorScreenPoint();
    const display = screen.getDisplayNearestPoint(cursor);
    const full = await captureFullDisplay(display);
    snipFreeze = full ? { display, fullImg: full.fullImg } : null;
    showSnipWindows();
    if (full) {
      const idx = screen.getAllDisplays().findIndex((d) => d.id === display.id);
      const win = snipWindows[idx];
      if (win && !win.isDestroyed()) win.webContents.send('snip:freeze', full.fullImg.toDataURL());
    }
  } finally {
    snipStarting = false;
  }
}

// Windows live snip: keep the overlay click-through (video keeps playing) and let the snip-only mouse
// hook supply the left-button drag → the existing external-session engine (mouseHookDown/Move/Up) draws
// the box + translates, exactly like the macOS mousehook path. The hook runs only while armed.
// Show the click-through overlay(s) IMMEDIATELY on ⌘⇧S so there's instant feedback + the cursor cue,
// instead of the overlay only appearing once the drag's first event arrives (that felt delayed).
function preShowWinSnipOverlay() {
  ensureSnipWindows();
  const displays = screen.getAllDisplays();
  const cursor = screen.getCursorScreenPoint();
  console.log('snip arm: displays', displays.length, 'overlays', snipWindows.length);
  snipWindows.forEach((win, i) => {
    if (win.isDestroyed() || !displays[i]) return;
    const b = displays[i].bounds;
    win.setIgnoreMouseEvents(true, { forward: true }); // click-through — video keeps playing
    // Hide the overlay from screen capture (WDA_EXCLUDEFROMCAPTURE) — still visible to the user, but
    // invisible to BitBlt. Without this the transparent full-screen overlay lands in the mid-drag
    // preview capture as flat black, so every live read came back empty at confidence 0.
    setProtect(win, true);
    setFixedWindowBounds(win, { x: b.x, y: b.y, width: b.width, height: b.height });
    // Same first-frame truth as showSnipWindows: the armed ring belongs on the real cursor.
    win.webContents.send('snip:reset', { external: true, cursor: ringPoint(cursor) }); // armed state: crosshair cue + hint, no box yet
    clearTimeout(win._gtHideTimer); // a pending post-snip hide must not swallow this new session
    win.showInactive();
  });
  hidePillFromCapture();
}

// Windows only. The snip overlay here is click-through and never focused (showInactive), and the
// input hook is mouse-only — so the overlay CANNOT see keystrokes the way the focused macOS one can.
// ONE key is borrowed as the "forget the box, I'll type it" switch, and Space is the safe choice:
// borrowing a key means TAKING it from the game for the few seconds a snip is armed, so the movement
// and hotbar keys must stay untouched. It also seeds nothing — a real focused field is what makes
// Japanese/Chinese/Korean (IME) input possible at all, and an accelerator is a physical key, not a
// character, so seeding from one would type the wrong letter on any non-US layout.
function grabSnipTypeKey() {
  try { globalShortcut.register('Space', () => { cancelWinSnip(); doTypeFocus(''); }); } catch {}
}
function releaseSnipTypeKey() {
  try { globalShortcut.unregister('Space'); } catch {}
}

function disarmWinSnip() {
  releaseForegroundAfterSnip();
  winSnipArmed = false;
  stopSnipHook();
  syncEscape(); // and NOT a blind unregister — a snip overlay may still be open and need Esc
  releaseSnipTypeKey();
}
// Esc / re-press: abort with no capture. mouseHookUp already handles overlay+pill on a real release, so
// this is NOT called there (see startWinSnip's up handler) — only for cancellation.
function cancelWinSnip() {
  if (!winSnipArmed && !externSession) return;
  disarmWinSnip();
  abortExternSession(); // tears down a mid-drag session (closes overlay + restores capture)
  closeSnipWindows();   // hide the pre-shown overlays when no drag ever opened a session
  setHintState('⌘⇧S');
}
// Swallowing WM_LBUTTONDOWN stops a click reaching the window underneath — and that is ALL it stops.
// A Unity game (measured on Restory.exe, 2026-08-28) reads the mouse through Raw Input, which a
// low-level hook cannot filter, and GetAsyncKeyState still reports the button as physically held. So
// 'press the key, then press and hold to drag a box' kept firing/dragging INSIDE the game the whole
// time the box was being drawn, while the hook dutifully logged every event as swallowed.
//
// Raw Input goes to the FOREGROUND window (nothing here registers RIDEV_INPUTSINK), so the fix is to
// stop the game being it: activate the snip overlay for the duration of the arm. The overlay is built
// focusable:false (WS_EX_NOACTIVATE) precisely so a snip would never steal focus — that is lifted for
// the arm and put straight back. The game gets the foreground handed back on disarm, which Windows
// permits because we are the foreground process at that moment.
function takeForegroundForSnip() {
  if (process.platform !== 'win32') return;
  try {
    winSnipPrevFg = foregroundWindow ? foregroundWindow() : null;
    const near = screen.getDisplayNearestPoint(screen.getCursorScreenPoint());
    const i = screen.getAllDisplays().findIndex((d) => d.id === near.id);
    const win = snipWindows[i >= 0 ? i : 0];
    if (!win || win.isDestroyed()) return;
    win.setFocusable(true);
    // focus() is not enough on its own: Electron routes it to SetForegroundWindow, which Windows
    // refuses to a process that is not already the foreground one — silently, so this used to log
    // success while the game stayed foreground and kept reading the drag through Raw Input (measured
    // on Restory.exe, 2026-08-29). forceForeground does the AttachThreadInput dance that Windows
    // actually honours, and reports whether the overlay ended up foreground. focus() stays as the
    // fallback for when the native path is unavailable (no koffi) or refused.
    const got = forceForeground ? forceForeground(win.getNativeWindowHandle()) : false;
    if (!got) win.focus();
    console.log('[DBG] snip foreground: ' + (got ? 'TAKEN natively (the game stops seeing the mouse)' : 'focus() fallback — VERIFY the pid at drag-down'));
  } catch (err) {
    console.warn('winSnip: could not take the foreground:', err.message);
  }
}
function releaseForegroundAfterSnip() {
  if (process.platform !== 'win32') return;
  try {
    for (const w of snipWindows) if (!w.isDestroyed()) w.setFocusable(false);
    if (winSnipPrevFg) restoreForeground(winSnipPrevFg);
  } catch { /* non-fatal */ }
  winSnipPrevFg = null;
}

function startWinSnip() {
  if (winSnipArmed) {
    // Re-press cancels — but not in the first moment. Holding the shortcut makes Windows resend it,
    // and the first of those repeats arrives after the OS repeat delay (~500ms), late enough to look
    // like a deliberate second press; letting it cancel is what made the overlay flicker on and off.
    // This guard belongs HERE and not in doSnipStart: it must cover the arm/cancel toggle only, never
    // the point-style shutter, which is a real second press within the same second.
    if (Date.now() - snipOpenedAt < 900) return;
    cancelWinSnip();
    return;
  }
  lastPreviewOcr = null;
  lastPreviewTranslate = null;
  const ok = startSnipHook({
    down: mouseHookDown,
    move: mouseHookMove,
    // One drag per press: mouseHookUp already closes the overlay + hides the pill for the capture, so
    // only disarm the hook here — never re-close (that would un-hide the pill into the OCR frame).
    // Disarm FIRST: mouseHookUp kicks off the capture+OCR, and anything heavy running while the
    // input hook is still live shows up as system-wide mouse lag.
    // Only fall back to the idle hint when nothing is being read — otherwise translateOnce's
    // 'Reading…' lands in the same frame and the pill visibly stutters resizing twice.
    up: (x, y) => { disarmWinSnip(); if (!mouseHookUp(x, y)) setHintState('⌘⇧S'); },
  });
  if (!ok) {
    // The WH_MOUSE_LL drag hook couldn't install — koffi/uiohook missing, or (far more often) an
    // anti-cheat or an elevated/admin game blocking low-level hooks. Rather than kill the app's core
    // feature with an error, fall back to the hook-FREE point overlay: the same click-through
    // anchor→size→shutter flow the live-point path already uses (showSnipWindows' winPoint branch). It
    // needs no global mouse hook — the box is driven by forwarded mousemove, and the second ⌘⇧S press is
    // the shutter (see doSnipStart) — and it keeps the game video playing behind it. The only difference
    // the user feels is drag-a-box → press-to-anchor, move, press again. (jek, Win11 2026-07-31)
    console.warn('[DBG] winSnip: input hook UNAVAILABLE — fell back to the hook-free point overlay (clicks reach the game)');
    followCursorMonitor();
    showSnipWindows();
    grabSnipTypeKey(); // the point overlay is click-through too — Space is the only way to reach Type
    return;
  }
  console.log("[DBG] snip ARMED (hook installed)");
  winSnipArmed = true;
  syncEscape();
  grabSnipTypeKey();
  // No pill hint while armed: the overlay says it full-screen already, and a long line in the pill's
  // narrow slot marqueed, then got killed by the next status a moment later — that was the judder.
  preShowWinSnipOverlay();
  // ...and only when a MOUSE BUTTON is going to be pressed. Taking the foreground exists for one
  // reason — a foreground game reads that button through Raw Input, which no hook can filter, so the
  // press that draws the box also lands in the game (measured on Restory.exe, 2026-08-29). 'hold and
  // sweep' presses nothing: you hold the trigger, move, and let go, so there is no button for the
  // game to see and nothing to protect against. Grabbing the foreground for it bought nothing and
  // pushed the game to the background for the length of every snip — the most frequent thing anyone
  // does here (jek, 2026-08-30: "ความต่อเนื่องในการเล่นเกมสำคัญกว่า"). 'drag' is only ever reached as
  // the automatic fallback for a trigger that cannot be held, and it still needs this.
  if (effectiveSnipStyle() === 'drag') takeForegroundForSnip(); // AFTER the overlay exists and is shown — it is the window we hand the foreground to
}

// Hold ⌘⇧S down and Windows keeps sending WM_HOTKEY for as long as you hold it — one press, then a
// burst of ~30 a second once the OS repeat delay elapses. Every one of those arrived here looking
// like a deliberate fresh press, and since a re-press CANCELS an armed snip (startWinSnip) the
// overlay armed and cancelled over and over: the rapid flicker. (jek, Win11 2026-07-31)
let lastSnipKeyAt = 0;   // when this last ran, accepted or swallowed — a held key keeps pushing it
let snipOpenedAt = 0;    // when the session on screen right now was opened
// ---------- Point at a word ----------------------------------------------------------------------
// A different thing from snipping, on a key of its own, which is the whole point of it existing
// separately (jek, 2026-08-09: "มันควรจะแยกกันกับตัว snip เลยเป็นฟังก์ชันอื่นแยก ... มันทำงานคนละอย่างกับ snip เลย").
// Snipping asks "translate this passage"; this asks "what is THAT word" — you point, a bubble names
// it, you move on. No box, no card, no AI call, no network: the answer comes out of a local index.
//
// The trick that makes it feel instant is that NOTHING happens on mouse move except arithmetic.
// Turning the mode on captures a band of screen around the cursor and OCRs it ONCE, keeping the
// rectangle the engine reports for every individual character. After that a mouse move is: which
// rectangle contains this point → which character is that → look the word up (~0.1ms against the
// in-memory index). A fresh capture only happens when the cursor leaves the band it read, or when
// what's on screen has had time to change.
//
// Ported from the `hover` branch, which built it against macOS Vision, and first wired up on
// WINDOWS: native/winocr.ps1 answers {"boxes":true} with the same normalized geometry Vision gives,
// built from Windows.Media.Ocr's per-word rectangles. macOS caught up on 2026-08-15 — the branch's
// visionocr.swift replaced main's, which it was a strict superset of (the plain read is the same
// program, `recognize()` factored out and the response encoded with JSONSerialization instead of
// hand-rolled escaping). So both platforms now feed the ONE path below; nothing under this line
// knows which engine drew the rectangles.
const HOVER_POLL_MS = 40;        // cursor sampling — 25/s is under the eye's threshold for "follows me"
const HOVER_CAP_W = 1100;        // band read around the cursor: wide enough for a full subtitle line…
const HOVER_CAP_H = 320;         // …and tall enough for the two or three lines around it
const HOVER_STALE_MS = 1500;     // a game repaints; a reading older than this can't be trusted
const HOVER_EDGE = 48;           // re-read before the cursor actually reaches the edge of the band
const HOVER_LANGS = { jpn: 1, eng: 1 }; // source languages a dictionary exists for

let hoverWindow = null;
let hoverActive = false;
let hoverTimer = null;
let hoverBusy = false;           // a capture+OCR is in flight — don't stack them
let hoverCache = null;           // { bounds, lines: [{ text, chars: [{x,y,w,h}|null] }], at }
let hoverShownKey = null;        // what the bubble is currently showing, so we don't resend it 25×/s
// The same word, as CONTENT — { matched, entry, line }. hoverShownKey is only an identity ("is this
// still the same word"), and the save key needs the word itself. Kept here rather than re-running the
// hit-test when the key is pressed: that would answer for wherever the cursor drifted to in the
// meantime, and pressing a key nudges the mouse.
let hoverShownWord = null;
// Dwell-to-keep state. Keyed on the WORD, never on hoverShownKey — that key carries the whole OCR
// line, so a health bar ticking at the far end of it would restart the clock while the cursor has
// not moved off the word at all (the same trap the translation cache's comment describes).
let hoverDwellWord = null;   // the word the clock is running for
let hoverDwellSince = 0;
let hoverDwellDone = false;  // this stay has already been collected — do not fire again until it moves
let hoverLastPt = { x: -1, y: -1 };

function sendHover(channel, payload) {
  if (hoverWindow && !hoverWindow.isDestroyed()) hoverWindow.webContents.send(channel, payload);
}

function ensureHoverWindow() {
  if (hoverWindow && !hoverWindow.isDestroyed()) return hoverWindow;
  const display = screen.getDisplayNearestPoint(screen.getCursorScreenPoint());
  const { x, y, width, height } = display.bounds;
  hoverWindow = new BrowserWindow({
    x, y, width, height,
    show: false,
    frame: false,
    transparent: true,
    alwaysOnTop: true,
    hasShadow: false,
    resizable: false,
    movable: false,
    skipTaskbar: true,
    fullscreenable: false,
    focusable: false,        // never activate — the game keeps focus and keeps rendering
    acceptFirstMouse: true,
    backgroundColor: '#00000000',
    webPreferences: {
      preload: path.join(__dirname, 'preload-hover.js'),
      contextIsolation: true,
      nodeIntegration: false,
      backgroundThrottling: false, // an occluded overlay must still repaint the bubble
    },
  });
  hoverWindow.setAlwaysOnTop(true, 'screen-saver');
  hoverWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  // The bubble sits INSIDE the band this mode keeps re-reading, so without this the app spends its
  // time reading its own popup back and defining the words in its own definitions.
  // GT_SHOW_BUBBLE=1 turns the protection off so a screenshot can show the bubble — development only.
  setProtect(hoverWindow, !process.env.GT_SHOW_BUBBLE);
  hoverWindow.setIgnoreMouseEvents(true, { forward: true }); // click-through for the whole session
  hoverWindow.loadFile(path.join(__dirname, 'renderer', 'hover', 'hover.html'));
  hoverWindow.on('closed', () => { hoverWindow = null; });
  return hoverWindow;
}

function toggleHoverMode() {
  if (hoverActive) stopHoverMode();
  else startHoverMode();
}

function startHoverMode() {
  if (hoverActive) return;
  // Unreachable from the UI (the chip and the shortcut are both filtered by HOVER_CAPABLE) — kept
  // as the guard for every way in that is not the UI: the hover:toggle IPC, a hand-edited
  // settings.json, anything a later caller adds without re-checking the capability.
  if (!HOVER_CAPABLE) { setHintState('Point-at-a-word needs Windows or macOS'); return; }
  // One dictionary per source language, and only the two that have one. Chinese and Korean OCR fine
  // — what they don't have is a word index to look the result up in, and this mode without one is
  // just a highlight rectangle.
  const lang = settings.sourceLang;
  if (!HOVER_LANGS[lang]) {
    // Unreachable in the English→Thai edition (PAIR_LOCK pins the source to eng, which HAS a
    // dictionary) — but the sentence must not name a language the user cannot select, so it only
    // offers the switch when there is a picker to switch with.
    setHintState(PAIR_LOCK
      ? 'Point-at-a-word needs a dictionary for this language'
      : 'Point-at-a-word reads Japanese or English — switch source to 日本語 / English');
    return;
  }
  // Loading up to 28MB of dictionary blocks this process for ~300ms. Paint the hint FIRST so the
  // freeze reads as "loading" rather than as the shortcut having done nothing.
  if (!hoverDict.isLoaded(lang)) setHintState('Loading dictionary…');
  setTimeout(() => {
    if (hoverActive) return;
    if (!hoverDict.load(lang)) { setHintState('Dictionary missing from this build'); return; }
    hoverActive = true;
    hoverCache = null;
    hoverShownKey = null;
    hoverShownWord = null;
    hoverLastPt = { x: -1, y: -1 };
    registerShortcuts(); // binds the mode-only keys (hoverSave) — see the `when` gate in there
    const win = ensureHoverWindow();
    positionHoverWindow(screen.getCursorScreenPoint());
    win.showInactive();
    hidePillFromCapture(); // our own pill must not end up in the band we're reading
    clearInterval(hoverTimer);
    hoverTimer = setInterval(pollHover, HOVER_POLL_MS);
    sendMain('hover:state', true); // the Shortcuts row draws this as a switch — see shortcutList().mode
    syncEscape();
    // The save key is named HERE and nowhere else on screen: the bubble is a glance and may not carry
    // a hint line, and a key nobody is told about is a key nobody presses. Live accel, never the
    // literal — every shortcut in this app is rebindable.
    const keep = SHORTCUT_ACTIONS.find((a) => a.id === 'hoverSave');
    // With dwell on, the hold IS the gesture and naming the key first would describe the slower way
    // of doing the same thing. The key still works and still gets named — second.
    setHintState(settings.hoverDwellSave
      ? `Point at a word — hold on it to keep it${keep ? ` (or ${accelFor(keep)})` : ''}, Esc stops`
      : (keep ? `Point at a word — ${accelFor(keep)} keeps it, Esc stops`
              : 'Point at a word — Esc to stop'));
  }, hoverDict.isLoaded(lang) ? 0 : 30);
}

function stopHoverMode() {
  if (!hoverActive) return;
  hoverActive = false;
  clearInterval(hoverTimer);
  hoverTimer = null;
  hoverCache = null;
  hoverShownKey = null;
  hoverShownWord = null;
  clearTimeout(hoverTrTimer);
  hoverTrTimer = null;
  registerShortcuts(); // …and gives the mode-only keys back to the game
  if (hoverWindow && !hoverWindow.isDestroyed()) hoverWindow.hide();
  sendMain('hover:state', false);
  applyContentProtection(); // give the pill its normal capture behaviour back
  syncEscape();
  setHintState('');
}

// Keep the overlay on whichever display the cursor is on — a bubble can't span two screens.
function positionHoverWindow(pt) {
  if (!hoverWindow || hoverWindow.isDestroyed()) return null;
  const b = screen.getDisplayNearestPoint(pt).bounds;
  const cur = hoverWindow.getBounds();
  if (cur.x !== b.x || cur.y !== b.y || cur.width !== b.width || cur.height !== b.height) {
    hoverWindow.setBounds({ x: b.x, y: b.y, width: b.width, height: b.height });
  }
  return hoverWindow.getBounds();
}

function hoverCacheCovers(pt) {
  const c = hoverCache;
  if (!c) return false;
  if (Date.now() - c.at > HOVER_STALE_MS) return false;
  const b = c.bounds;
  return pt.x >= b.x + HOVER_EDGE && pt.x <= b.x + b.width - HOVER_EDGE
      && pt.y >= b.y + HOVER_EDGE && pt.y <= b.y + b.height - HOVER_EDGE;
}

// The one place that knows which engine answers with geometry. Returns the engine's own shape —
// {lines:[{t,c:[[x,y,w,h]|null]}]} in IMAGE FRACTIONS — or null.
//
// Two attempts, the second only when the first came back thin. Measured 2026-08-09 across eight
// rendered conditions: clean text at 11-28px, light-on-dark, dark-on-light and serif all read
// perfectly, and every failure was text over a busy background (1 of 8 words) or low contrast (7 of
// 8). The snip path has had the answer to exactly that since July — read again through
// binarizeBright, which finds text as a bright minority in a scene where Otsu can't — and this path
// was the one place still taking a single look.
//
// Gated on a weak first result, not run always: this fires on a cursor that has moved out of its
// band, up to 25 times a second in the worst case, and doubling every read to rescue the reads that
// don't need it would spend the latency budget the whole design is built to protect.
// How much of a read is real WORDS, judged by the one authority this feature already carries: the
// dictionary it is about to look the answer up in. Returns { known, total }.
//
// Length is not the test, and measuring proved it: over a moderately busy background the engine
// returned "8re- Selbthe dåmaged sword bef uest begin" — forty characters of mostly nothing. A
// length gate accepts that and never tries again, which is the case that needed trying again most.
// A dictionary gate sees three real words out of seven and knows better.
function hoverScore(res, lang) {
  const out = { known: 0, total: 0 };
  if (!res || !Array.isArray(res.lines)) return out;
  for (const l of res.lines) {
    // Same token rule as the snip path's second opinion — one scorer, so the two paths can't drift.
    const s = dictScore(String(l && l.t || ''), lang);
    out.known += s.known;
    out.total += s.total;
  }
  return out;
}

async function recognizeBoxes(image) {
  if (!HOVER_CAPABLE) return null;
  const lang = settings.sourceLang;
  // Only the READER differs by platform — the two-pass rescue below, its scoring gate and the
  // {text, lines:[{t,c}]} shape it returns are one implementation for both. A second copy of the
  // rescue logic per engine is how the two platforms start disagreeing about when a read is good
  // enough. Vision is asked for geometry with the ";boxes" suffix on the language line
  // (native/visionocr.swift); Windows.Media.Ocr with the boxes flag on the request object.
  const read = IS_WIN
    ? (img) => winOcrServerRecognize(img.toPNG(), WINOCR_LANG_MAP[lang] || 'en-US', true).catch(() => null)
    : (img) => visionServerRecognize(img.toPNG(), `${VISION_LANG_MAP[lang] || 'en-US'};boxes`).catch(() => null);

  const plain = await read(image);
  const a = hoverScore(plain, lang);
  // Good enough = at least three words and most of them real. Below that the read is fragments, and
  // fragments are what the second attempt exists for.
  if (a.total >= 3 && a.known >= a.total * 0.6) return plain;

  // Same rescue the snip path has had since July (see recognizeImage): binarizeBright finds text as a
  // bright minority in a scene, where the engine's own thresholding gives up. Measured on the same
  // eight images: text over a busy background went 1/8 words → 8/8 and 1/8 → 7/8 through this pass.
  //
  // Not run unconditionally, for two reasons and both measured. It costs a whole second read on a
  // path that can fire whenever the cursor leaves its band. And it is not strictly better: on
  // low-contrast grey-on-grey the cutoff floor erases the text outright (7/8 → 0/8), which is exactly
  // the case the gate above accepts on the first read and never sends here.
  let hard = null;
  try { hard = await read(binarizeBright(image)); } catch { hard = null; }
  const b = hoverScore(hard, lang);
  return b.known > a.known ? hard : plain;
}

// Neither engine really answers per CHARACTER for a spaced script: ask Vision for the box of one
// character and it returns the box of the whole space-delimited RUN that character sits in, and
// Windows.Media.Ocr is built out of per-word rectangles to begin with. So a run of N characters
// arrives as N copies of one rectangle. Measured on jek's terminal, 2026-08-15: every character of
// `$SP=/private/tmp/claude-501/-Users-jek/9b50bb44-...` carried the same 521px-wide box, so pointing
// anywhere along 320px of it hit character 0 every time — one word for the whole path, and a
// highlight that swallowed it whole.
//
// Cut each shared rectangle into N equal cells, one per character. Exact in a terminal (monospace is
// what this mode is most often pointed at) and an approximation in a proportional font, but an
// approximation that puts the cursor in the right WORD, which one 521px cell can never do. Japanese
// is untouched: its runs are one character long already, so every group here has size 1.
function sliceSharedBoxes(chars) {
  const same = (a, b) => a && b && a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h;
  const out = chars.slice();
  for (let i = 0; i < out.length;) {
    let j = i + 1;
    while (j < out.length && same(chars[i], chars[j])) j++;
    const n = j - i;
    if (n > 1) {
      const b = chars[i];
      const cell = b.w / n;
      for (let k = 0; k < n; k++) out[i + k] = { x: b.x + cell * k, y: b.y, w: cell, h: b.h };
    }
    i = j;
  }
  return out;
}

// Capture the band around the cursor and turn the engine's normalized per-character boxes into
// screen points, which is the only coordinate system the rest of this path speaks.
async function refreshHoverCache(pt) {
  if (hoverBusy || !hoverActive) return;
  hoverBusy = true;
  try {
    const db = screen.getDisplayNearestPoint(pt).bounds;
    const width = Math.min(HOVER_CAP_W, db.width);
    const height = Math.min(HOVER_CAP_H, db.height);
    const bounds = {
      x: Math.max(db.x, Math.min(Math.round(pt.x - width / 2), db.x + db.width - width)),
      y: Math.max(db.y, Math.min(Math.round(pt.y - height / 2), db.y + db.height - height)),
      width, height,
    };
    const cap = await captureRegion(bounds);
    if (!cap || !hoverActive) return;
    const size = cap.image.getSize();
    if (!size.width || !size.height) return;
    const res = await recognizeBoxes(cap.image);
    if (!res || !hoverActive) return;

    // The boxes are fractions of the captured IMAGE; the image is `bounds` at the display's backing
    // scale, so dividing the pixel size back down by the capture ratio returns points.
    const wPts = size.width / (cap.ratioX || 1);
    const hPts = size.height / (cap.ratioY || 1);
    const lines = (res.lines || []).map((l) => ({
      text: l.t || '',
      // `b[2] > 0` and not just `length === 4`: a space comes back as [0,0,0,0], which passed the
      // old test and became a real zero-size rectangle pinned to the band's top-left corner — an
      // invisible hit target in the wrong place, and a corner the highlight's union could be dragged
      // back to. It is nothing; say so.
      chars: sliceSharedBoxes((l.c || []).map((b) => (b && b.length === 4 && b[2] > 0 ? {
        x: bounds.x + b[0] * wPts,
        y: bounds.y + b[1] * hPts,
        w: b[2] * wPts,
        h: b[3] * hPts,
      } : null))),
    }));
    hoverCache = { bounds, lines, at: Date.now() };
    // The one thing you cannot see from outside when this mode picks the wrong word: WHAT it read.
    // Every "it highlighted the whole phrase" / "that word gives nothing" report is really a question
    // about this line, and guessing at it from the bubble alone costs more than printing it.
    if (DEBUG) console.error('hover: read', JSON.stringify({ bounds, size, ratio: [cap.ratioX, cap.ratioY],
      lines: lines.map((l) => ({ t: l.text, first: l.chars[0], last: l.chars[l.chars.length - 1] })) }));
  } catch (err) {
    if (DEBUG) console.error('hover: capture failed', err);
  } finally {
    hoverBusy = false;
  }
}

// Which character is under the point. The boxes hug the glyph, so they're padded a little — without
// it the gaps between characters read as "nothing here" and the bubble flickers off.
function hoverHitTest(pt) {
  if (!hoverCache) return null;
  for (const line of hoverCache.lines) {
    for (let i = 0; i < line.chars.length; i++) {
      const b = line.chars[i];
      if (!b) continue;
      const padX = b.w * 0.1;
      const padY = b.h * 0.25;
      if (pt.x >= b.x - padX && pt.x <= b.x + b.w + padX
          && pt.y >= b.y - padY && pt.y <= b.y + b.h + padY) return { line, index: i };
    }
  }
  return null;
}

// Which scripts write their words with spaces between them. Everything below that talks about "the
// run the cursor is in" means a space-delimited one, which only exists here — a Japanese line is one
// unbroken run by nature, and treating it as such is what the dictionary's own longest-match walk
// already assumes.
const HOVER_SPACED = { eng: 1 };
// Characters that never appear INSIDE a word, only in paths, URLs, code and identifiers. A digit
// counts: no English word carries one, and `claude-501` / `9b50bb44` are exactly what this is for.
// `-` is deliberately absent — `check-invariants` is one token on purpose (see hoverBareToken).
const HOVER_NOT_WORD = /[/\\=:;$@#%&*+<>|~^_(){}[\]0-9]/;
// The run of non-space characters the cursor is in, trimmed of the punctuation that legitimately
// bookends a word ('point', "word", end.) — so quoting a word does not disqualify it. Returns null
// when what is left is not language at all: pointing anywhere in
// `$SP=/private/tmp/claude-501/-Users-jek/9b50bb44-...` used to answer "SP" (jek, 2026-08-15),
// because the lookup below walked the RAW line and happily dug an English word out of the middle of
// a path. hoverBareToken has refused that shape since July — this is the same rule, applied once,
// where both lookups can read it instead of only one of them.
function hoverWordRun(line, index) {
  const text = line.text || '';
  if (!HOVER_SPACED[settings.sourceLang]) return { s: 0, e: text.length };
  let s = index, e = index;
  while (s > 0 && !/\s/.test(text[s - 1])) s--;
  while (e < text.length && !/\s/.test(text[e])) e++;
  while (s < e && !HOVER_BARE_LETTER.test(text[s])) s++;        // leading ( " ' $ …
  while (e > s && !HOVER_BARE_LETTER.test(text[e - 1])) e--;    // trailing ) " ' . , ; …
  if (e <= s) return null;
  if (index < s || index >= e) return null;   // the cursor sat on the punctuation, not the word
  if (HOVER_NOT_WORD.test(text.slice(s, e))) return null;
  return { s, e };
}

// The word the cursor is IN, not the word that starts at the cursor. Hovering 生 in 女子生徒 should
// give 女子生徒 — so try starting a few characters back and keep the longest match that still covers
// the character being pointed at. `run` bounds the search: without it the walk reaches across a
// space and reads two words as one.
function hoverResolveWord(line, index, run) {
  let best = null;
  const lang = settings.sourceLang;
  const from = Math.max(run.s, index - hoverDict.lookback(lang));
  for (let start = from; start <= index; start++) {
    const found = hoverDict.lookupAt(line.text, start, lang);
    if (!found) continue;
    if (start + found.length <= index) continue; // match ends before the cursor — not this word
    if (start + found.length > run.e) continue;  // …and one that runs past the word is not this one
    if (!best || found.length > best.found.length) best = { start, found };
  }
  return best;
}

function pollHover() {
  if (!hoverActive) return;
  const pt = screen.getCursorScreenPoint();
  if (!hoverCacheCovers(pt)) {
    refreshHoverCache(pt); // async; this tick still hit-tests whatever we have
  }
  // A cursor that has not moved is the cheapest tick there is — and it is also EXACTLY what dwelling
  // looks like, so the clock has to be read before this returns. Without this line the hold never
  // fired at all: holding still meant every poll left here, one line above the tick (measured
  // 2026-08-15, "harbour" resolved and was never collected).
  if (Math.abs(pt.x - hoverLastPt.x) < 2 && Math.abs(pt.y - hoverLastPt.y) < 2) { hoverDwellTick(); return; }
  hoverLastPt = pt;

  const wb = positionHoverWindow(pt);
  if (!wb) return;

  const hit = hoverHitTest(pt);
  // Three answers, in falling order of how much we know about the word. A dictionary match on the
  // line is the best; failing that, the plain token under the cursor is looked up on its OWN, which
  // rescues everything joined by a hyphen (`-` counts as a word character, so `check-invariants` is
  // one token to lookupEn and no dictionary holds it); failing that too, the token still exists and
  // the translator can answer for it even though the dictionary cannot. (jek, 2026-08-12, pointing at
  // `-invariants` and getting nothing at all.)
  // ONE gate in front of both lookups: if the run under the cursor is not language, neither of them
  // gets to answer for it. Putting the test inside hoverResolveWord alone would leave the bare-token
  // path to pull "Users" out of /Users/jek — the same wrong answer through the other door.
  const run = hit ? hoverWordRun(hit.line, hit.index) : null;
  const bare = run ? hoverBareToken(hit.line, hit.index, run) : null;
  const resolved = (run && hoverResolveWord(hit.line, hit.index, run)) || hoverResolveBare(bare);
  if (DEBUG) console.error('hover: hit', JSON.stringify({ pt, hit: hit && { i: hit.index, ch: hit.line.text[hit.index], t: hit.line.text.slice(0, 60) },
    run: run && hit.line.text.slice(run.s, run.e), bare: bare && bare.text, resolved: resolved && resolved.found.matched }));
  if (!resolved && !bare) {
    if (hoverShownKey !== null) {
      hoverShownKey = null;
      hoverShownWord = null; // nothing under the cursor → nothing for the save key to act on
      hoverDwellWord = null; // …and nothing for the clock to be counting towards
      clearTimeout(hoverTrTimer); // …and nothing worth a network call either
      hoverWindow.webContents.send('hover:hide');
    }
    return;
  }

  const start = resolved ? resolved.start : bare.start;
  const span = resolved ? resolved.found.length : bare.length;
  const key = `${hit.line.text}|${start}|${span}${resolved ? '' : '|bare'}`;
  if (key === hoverShownKey) { hoverDwellTick(); return; } // same word — the bubble stays, the clock runs
  hoverShownKey = key;

  // The highlight is the union of the boxes of the characters the match actually spans.
  let left = Infinity, top = Infinity, right = -Infinity, bottom = -Infinity;
  for (let i = start; i < start + span; i++) {
    const b = hit.line.chars[i];
    if (!b) continue;
    left = Math.min(left, b.x); top = Math.min(top, b.y);
    right = Math.max(right, b.x + b.w); bottom = Math.max(bottom, b.y + b.h);
  }
  if (!isFinite(left)) return;

  const found = resolved && resolved.found;
  // enth.json files a word once per word class, in the dictionary's order, not the reader's: `language`
  // happens to carry its Thai gloss on the first entry, while `more` lists an English-definition entry
  // (det) first and keeps the Thai one (adv, "อีก") second. Everything below reads entry ZERO and
  // nothing else, so the same act — pointing at a word — answered one of them with a single Thai word
  // and the other with a three-line English definition and an EN warning chip (jek, 2026-08-13). Sort
  // the answer the reader asked for to the front; when no entry has one, the dictionary's own order
  // stands (jmdict is English throughout, which is every Japanese word).
  const entries = found ? preferReaderEntry(found.entries) : [];
  hoverShownWord = {
    matched: found ? found.matched : bare.text,
    entry: entries[0] || null,
    line: hit.line.text,
  };

  // The dictionary's answer may not be in the language the reader came here for — see the block at
  // hoverNeedsTranslation. A cached answer rides along with the word itself; a missing one is fetched
  // only if the cursor is still here in HOVER_TR_DWELL_MS.
  const trTerm = hoverTrTerm(hoverShownWord);
  // The shared cache is consulted for EVERY word now, not only for the ones the dictionary answers in
  // the wrong language. That is the whole point of sharing it: a word the Type bar already answered
  // must read the same when you point at it, and the bar's answer is the better of the two (Google
  // orders its senses by how often people actually use them; the dictionary is Wiktionary's order,
  // which is why pointing at `point` said พินทุ while the bar said จุด). The dictionary remains the
  // instant first answer for everything the bar has never been asked.
  const cached = wordCacheGet(trTerm);
  const needsTr = !found || hoverNeedsTranslation(entries[0]);
  const cachedTr = (cached && cached.text) || '';
  hoverShownWord.tr = needsTr || cached ? cachedTr : '';
  clearTimeout(hoverTrTimer);

  const payload = {
    // Window-relative: the renderer positions in CSS pixels inside its own overlay.
    rect: { x: left - wb.x, y: top - wb.y, width: right - left, height: bottom - top },
    matched: hoverShownWord.matched,
    // ONE line and its chip, decided here rather than in the overlay: the renderer is output-only and
    // has never seen a language, a setting or a dictionary — see the note above hoverShortGloss.
    // The cache wins when it has this word: it is the bar's own answer, and "the two surfaces say the
    // same thing" is worth more than the dictionary being 0ms faster on a word already in memory.
    gloss: cachedTr || hoverShortGloss(entries[0], ''),
    pos: (cached && cached.pos) || hoverShortPos(entries[0]),
    // The other parts of speech, in the SAME shape and under the SAME setting as the card's row and
    // the Type bar's — one word must not be a three-sense word in one place and a one-sense word in
    // another (jek, 2026-08-15). The overlay reads no settings of its own, so the gate is here: with
    // "Other meanings" off, or a word with only one sense, nothing is sent and the bubble is the one
    // line it has always been. `senses[0]` is dropped by the renderer (skipFirst) because the gloss
    // line above already carries the primary chip — exactly what the card does.
    senses: settings.showSenses
      ? ((cached && cached.senses && cached.senses.length ? cached.senses : (localWordAnswer(hoverShownWord.matched) || {}).senses) || [])
      : [],
    // "I have this word, I just don't have your language for it yet." The bubble opens on the word
    // and a quiet mark where the meaning goes, and the meaning drops in when it lands — one shape,
    // one language, the way the snip bar's "Reading…" works. False for a word we can already answer.
    pending: needsTr && !cachedTr && !!found,
    // Already yours? The star is the whole answer — pressing the key on a word you collected last
    // week should not look identical to collecting it, or the collection is a thing you can only
    // check by leaving the game.
    saved: vocabHas(hoverVocabEntry(hoverShownWord).word),
  };

  // Keyed on the WORD, not on `key`. `key` carries the whole OCR line, so a health bar ticking or one
  // letter re-read differently at the far end of that line makes it a "different word" — while the
  // cursor never left the word it is pointing at. The translation would then land under a key nobody
  // was waiting for and never be painted, and the bubble sat on the English placeholder until you
  // looked away and back (jek, 2026-08-14: "มันไม่โชว์แบบใหม่ ... เหมือนโชว์ข้อมูลเก่า"). The word is the
  // thing the answer is FOR, so the word is what decides whether the answer is still wanted.
  if (needsTr && !cachedTr) scheduleHoverTranslate(trTerm, found ? null : payload);
  // A word with no dictionary entry and no translation yet has NOTHING to say. Show nothing rather
  // than a bubble holding one word and an empty space — the answer arrives through the same payload
  // a moment later, or never, and never is a perfectly good outcome for a fragment of OCR noise.
  if (!found && !cachedTr) {
    hoverWindow.webContents.send('hover:hide');
    return;
  }
  hoverWindow.webContents.send('hover:show', payload);
  hoverDwellTick(); // a NEW word: this starts its clock (and never fires on the same tick)
}

// The plain run of letters under the cursor, ignoring every rule the dictionary path lives by. A
// hyphen ENDS a token here, which is the whole point: it is what separates `invariants` from
// `check-invariants`. Letters only — a number or a symbol in the middle means OCR noise or a file
// name, not a word worth spending a network call on.
const HOVER_BARE_MIN = 3; // "of", "at", "a1" — below this a token is as likely to be noise as a word
const HOVER_BARE_LETTER = /[A-Za-zÀ-ɏ]/;

function hoverBareToken(line, index, run) {
  const chars = Array.from(line.text || '');
  if (!HOVER_BARE_LETTER.test(chars[index] || '')) return null;
  // Never walk out of the run hoverWordRun approved. Letters alone would happily cross the `/` in
  // /Users/jek and hand back `Users` — a real word, from a thing that is not language.
  const lo = run ? run.s : 0, hi = run ? run.e : chars.length;
  let s = index;
  while (s > lo && HOVER_BARE_LETTER.test(chars[s - 1])) s--;
  let e = index;
  while (e < hi && HOVER_BARE_LETTER.test(chars[e])) e++;
  const text = chars.slice(s, e).join('');
  if (text.length < HOVER_BARE_MIN) return null;
  return { start: s, length: e - s, text };
}

// The dictionary, asked about the bare token on its own — the hyphen rescue. Shaped like
// hoverResolveWord's answer so the caller cannot tell which of the two found the word.
function hoverResolveBare(bare) {
  if (!bare) return null;
  const found = hoverDict.lookupAt(bare.text, 0, settings.sourceLang);
  return found ? { start: bare.start, found } : null;
}

// ---------- The word in the reader's own language, when the dictionary hasn't got it -------------
// Measured 2026-08-12 on dict/enth.json: of 77,199 entries, 66,292 (85.9%) carry only an English
// definition from Wiktionary and no Thai at all — and dict/jmdict.json is JMdict-**eng** end to end,
// so Japanese answers in English every single time. Pointing at `quest` returned "A journey or effort
// in pursuit of a goal", while typing the same word into the app returned ภารกิจ, because the type
// and snip paths have always had a real translator behind them (translate(), Google). Same word, two
// engines, and only one of them spoke the user's language (jek, 2026-08-12).
//
// What the mode is not allowed to lose is the reason it exists: a bubble that keeps up with the
// cursor. So this NEVER fires on a sweep — only on a word the cursor STAYED on, once per word, and
// the answer is written to disk, so the second time you meet it there is no network at all.
// Long enough that reading a line never trips it (a glance is 200-300ms per word) and short enough
// that deciding "yes, this one" does not become a wait. Tuned as ONE number rather than a slider:
// the switch is the decision, and a second control asking "how long is a hold" is a question nobody
// can answer without trying it.
const HOVER_DWELL_SAVE_MS = 1000;
const HOVER_TR_DWELL_MS = 400; // long enough that reading a line costs nothing; short enough to feel
const HOVER_TR_MAX = 4000;     // cached words kept on disk — oldest out first (Map insertion order)
const HOVER_TR_SAVE_MS = 2000;

let hoverTr = null;            // key -> translated text, lazily read off disk
let hoverTrTimer = null;       // the dwell timer for the word currently under the cursor
let hoverTrInFlight = null;    // key being fetched, so a re-hover can't stack a second call
let hoverTrSaveTimer = null;

function hoverTrFile() {
  return path.join(app.getPath('userData'), 'hover-tr.json');
}

// One key per (source, target, word): re-key the languages and the old answers stay valid for when
// they are switched back, instead of the cache handing Thai to someone now reading in English.
function hoverTrKey(word) {
  return `${settings.sourceLang}>${settings.targetLang}:${String(word || '').toLowerCase()}`;
}

// This started as "translations the bubble has already paid for" and is now the ONE place any
// surface's word answer is kept — the Type bar and a tapped word write here too (wordCachePut). That
// is what makes the two consistent: point at a word you looked up in the bar an hour ago and you get
// the string the bar gave you, not a second opinion from the dictionary (jek, 2026-08-15, choosing
// this over making the bar read the dictionary first — which would have cost `จุด` and left `พินทุ`).
// It also means the bar answers offline for every word you have ever looked up, not only the ones
// the local dictionary happens to carry.
//
// Values were plain strings and are now { text, pos, senses }. A string on disk is read as
// { text } — an old cache stays valid rather than being thrown away on upgrade.
function cacheValue(v) {
  if (typeof v === 'string') return v ? { text: v, pos: '', senses: [] } : null;
  if (v && typeof v === 'object' && typeof v.text === 'string' && v.text) {
    return { text: v.text, pos: v.pos || '', senses: Array.isArray(v.senses) ? v.senses : [] };
  }
  return null;
}

function loadHoverTr() {
  if (hoverTr) return hoverTr;
  hoverTr = new Map();
  try {
    const raw = JSON.parse(fs.readFileSync(hoverTrFile(), 'utf8'));
    if (raw && typeof raw === 'object') {
      for (const [k, v] of Object.entries(raw)) { const val = cacheValue(v); if (val) hoverTr.set(k, val); }
    }
  } catch { /* first run, or a file we can't read — an empty cache is the right answer either way */ }
  return hoverTr;
}

// The whole answer for a word, or null. Callers that only want the line use hoverTrLookup.
function wordCacheGet(word) {
  return (word && loadHoverTr().get(hoverTrKey(word))) || null;
}

// Only single words go in. A sentence would be a cache entry nobody can ever hit again (the same
// sentence twice is not a thing that happens) and would push 4000 real words out to make room.
// Google echoing its input back is not an answer either — caching `quest → quest` makes that
// permanent, which is the one failure this cache could make worse instead of better.
// "One word", asked HERE rather than borrowed: the renderer has its own isSingleWord (index.js) and
// this process cannot see it. Same rule — no whitespace, and a script without spaces is capped by
// length so a whole Japanese line is not filed as one word. Written out instead of imported because
// there is no module both a sandboxed renderer and the main process can read; if that changes, this
// and its twin should become one.
// Hangul is NOT here, and that is deliberate — the renderer's twin (isSingleWord in
// renderer/main/index.js) says so with its reason: Korean writes spaces between words, so the
// whitespace test already answers for it, and the ≤4-character rule would wrongly call a long
// misread "not a word". Including it here made the two disagree about the same string: main refused
// to keep or cache it while the card offered the ★ for it (found in review, 2026-08-15).
const CJK_RE = /[\u3040-\u30ff\u3400-\u9fff]/;
function isOneWord(s) {
  const t = String(s || '').trim();
  if (!t || /\s/.test(t)) return false;
  return CJK_RE.test(t) ? [...t].length <= 4 : true;
}

function wordCachePut(word, answer) {
  // Nothing in here may throw out of this function. It is called INSIDE the try that produces the
  // answer, so a failure here would be caught as "the lookup failed" and quietly demote a live
  // result to the offline one — which is exactly what happened the first time this shipped: it
  // called the renderer's isSingleWord, which does not exist in this process, and every online
  // lookup in the app started answering from the local dictionary. A cache is a side effect; a side
  // effect that can change the answer is not a cache.
  try {
    const term = String(word || '').trim();
    const text = String((answer && answer.text) || '').trim();
    if (!term || !text || !isOneWord(term) || echoesInput(text, term)) return;
    const cache = loadHoverTr();
    cache.set(hoverTrKey(term), { text, pos: answer.pos || '', senses: Array.isArray(answer.senses) ? answer.senses.slice(0, 3) : [] });
    while (cache.size > HOVER_TR_MAX) cache.delete(cache.keys().next().value);
    saveHoverTrSoon();
  } catch (err) {
    if (DEBUG) console.error('word cache: could not store', err);
  }
}

// Debounced: pointing at a paragraph can fill this a dozen times in a minute, and each write is the
// whole file. Nothing is lost if the app dies before it lands — the words are re-fetchable.
function saveHoverTrSoon() {
  clearTimeout(hoverTrSaveTimer);
  hoverTrSaveTimer = setTimeout(() => {
    try {
      fs.writeFileSync(hoverTrFile(), JSON.stringify(Object.fromEntries(hoverTr || [])));
    } catch (err) {
      if (DEBUG) console.error('hover: could not save translation cache', err);
    }
  }, HOVER_TR_SAVE_MS);
}

// Which language did the dictionary just answer in? Two dictionaries, two different ways of saying
// it: enth.json tags an English-definition sense `en` (that is what the EN chip on the bubble is
// reading), and jmdict has no tag because every gloss in it is English.
function hoverNeedsTranslation(entry) {
  const sense = entry && Array.isArray(entry.senses) ? entry.senses[0] : null;
  if (!sense) return false;
  const glossLang = settings.sourceLang === 'jpn' ? 'en'
    : (String(sense.pos || '').split(',').map((t) => t.trim()).includes('en') ? 'en' : 'th');
  return glossLang !== settings.targetLang;
}

// Which of a word's entries to lead with. Sorts the first entry that answers in the reader's own
// language to the front and leaves the rest in the dictionary's order; returns the list untouched
// when there is one entry, or when none of them answer in that language. See the call site for the
// `more` vs `language` case that made this necessary.
function preferReaderEntry(entries) {
  if (!Array.isArray(entries) || entries.length < 2) return entries || [];
  const i = entries.findIndex((e) => !hoverNeedsTranslation(e));
  if (i <= 0) return entries;
  return [entries[i], ...entries.slice(0, i), ...entries.slice(i + 1)];
}

// ---------- The ONE line the bubble says ---------------------------------------------------------
// The overlay is output-only (preload-hover.js): it has never seen a setting, a language or a
// dictionary entry, so the choice of what a glance is worth is made here and it paints what arrives.
//
// Best answer available RIGHT NOW, and nothing else. The dictionary's own gloss when it already
// speaks the reader's language — instant, no network, and for most words the end of it. Otherwise
// whatever the translator has already cached for this word, and failing that the dictionary's English
// definition as a placeholder: it is replaced by hover:extra a moment later (scheduleHoverTranslate),
// and a bubble that says nothing while it waits is worse than one that says something in the wrong
// language for 600ms. What it is NEVER allowed to do is say both at once, or say three of them.
function hoverShortGloss(entry, tr) {
  const sense = entry && Array.isArray(entry.senses) ? entry.senses[0] : null;
  if (sense && !hoverNeedsTranslation(entry)) return String(sense.gloss || '').trim();
  // NOT the dictionary's English definition, not even shortened, not even for the 600ms before the
  // translator answers. `Resume` has no Thai in enth.json at all, so the bubble opened on "To take
  // back possession of (something)" with a V. and an EN chip and only then became the one Thai word
  // — the English half of the flicker being the whole thing this window was rebuilt to stop showing
  // (jek, 2026-08-14: "มันยังโชว์แปลภาษาอังกฤษ ... มันไม่ได้โชว์แบบ Translation Bar"). The snip bar has
  // never done this: while it is working it says so (showPreviewStatus in renderer/snip/snip.js) and
  // the reader's language is the only language that ever reaches the card. Same rule here — the
  // bubble waits with a `pending` mark instead, see the payload.
  return String(tr || '').trim();
}

// The chip beside it. The `en` marker is stripped everywhere now: it warned that the line beside it
// was an English definition standing in for a translation, and no such line is ever shown here any
// more, so the chip would be a warning about nothing.
function hoverShortPos(entry) {
  if (!settings.showPos) return '';
  const sense = entry && Array.isArray(entry.senses) ? entry.senses[0] : null;
  return String((sense && sense.pos) || '').split(',').map((t) => t.trim())
    .filter((t) => t && t.toLowerCase() !== 'en').join(',');
}

// The headword, not the surface on screen: `swords` and `食べられた` translate worse than the form the
// dictionary already resolved them to, and it keeps one cache entry per word instead of one per
// inflection.
function hoverTrTerm(shown) {
  return (shown && shown.entry && shown.entry.term) || (shown && shown.matched) || '';
}

function hoverTrLookup(word) {
  return (wordCacheGet(word) || {}).text || '';
}

// `showPayload` is how a word the DICTIONARY doesn't have reaches the screen at all: there is no
// bubble up for it, so the translation has to arrive as the whole word rather than as a line added
// to one. Null for a word that already has a bubble.
function scheduleHoverTranslate(word, showPayload) {
  if (!word) return;
  // Is the bubble still showing the word this answer is for? Not "is it showing the same OCR line" —
  // see the call site. Read at both ends of the network call, because that is where the cursor moves.
  const stillWanted = () => hoverActive && hoverTrTerm(hoverShownWord) === word;
  hoverTrTimer = setTimeout(async () => {
    if (!stillWanted()) return; // the cursor moved on — no call at all
    const ck = hoverTrKey(word);
    // It landed while we were waiting out the dwell — the previous hover of this same word paid for
    // it, or a re-render restarted the timer on top of a call that was already finishing. Paint it;
    // asking Google for an answer we are holding is a network call spent on nothing.
    const have = hoverTrLookup(word);
    if (have) { paintHoverTr(have, showPayload); return; }
    // Already being fetched: the call in flight will paint it, because it tests the same word this
    // one would have. Returning here used to mean the bubble never got the answer at all — a word
    // re-entered while its own request was open was stuck on English until you left and came back.
    if (hoverTrInFlight === ck) return;
    hoverTrInFlight = ck;
    try {
      // tries:1 — this is a nicety running behind a bubble that already says something. Three
      // attempts with backoff would still be waiting long after the user has read the line and moved
      // on, and would spend the free endpoint's patience on a word nobody is looking at any more.
      const res = await translate(word, { tries: 1, timeoutMs: 4000 });
      const text = String((res && res.text) || '').trim();
      // Google echoes the input back for a word it can't place. Answering `quest` with "quest" is
      // worse than answering nothing, and caching it would make that permanent. (wordCachePut tests
      // this too — kept here because the paint below must not happen either.)
      if (!text || echoesInput(text, word)) return;
      // The senses ride along, so a word first met by POINTING carries the same three-sense row into
      // the bar as one first met in the bar carries into the bubble. Same cache, same shape, one way in.
      wordCachePut(word, { text, pos: res.pos || '', senses: (res.senses && res.senses.length) ? res.senses : ((localWordAnswer(word) || {}).senses || []) });
      if (!stillWanted()) return; // read it, moved on — nothing to paint
      paintHoverTr(text, showPayload);
    } catch (err) {
      // Offline, rate-limited, or simply slow: the dictionary's answer is already on screen, so the
      // correct failure here is silence.
      if (DEBUG) console.error('hover: word translate failed', err);
    } finally {
      hoverTrInFlight = null;
    }
  }, HOVER_TR_DWELL_MS);
}

// The reader's own language, arriving after the dictionary's answer is already on screen. It REPLACES
// the line the bubble is holding rather than adding a second one — see showExtra in
// renderer/hover/hover.js — and the EN warning goes with it, because the line it was warning about is
// gone. `showPayload` is a word the DICTIONARY never had: there is no bubble up for it, so the answer
// has to arrive as the whole word rather than as a line added to one.
function paintHoverTr(text, showPayload) {
  // The save key reads this: a word whose only meaning IS this translation must not go into the
  // collection with an empty meaning because the key was pressed a second after the line landed.
  if (hoverShownWord) hoverShownWord.tr = text;
  if (showPayload) sendHover('hover:show', { ...showPayload, gloss: text });
  else sendHover('hover:extra', { text, pos: hoverShortPos(hoverShownWord && hoverShownWord.entry) });
}

// The vocab entry a pointed-at word turns into. Kept apart from saveHoverWord so the poll can ask the
// same question ("is this word already mine") of the same answer the key would save.
function hoverVocabEntry(shown) {
  const e = (shown && shown.entry) || {};
  const senses = Array.isArray(e.senses) ? e.senses.slice(0, 3) : [];
  const entry = {
    // The dictionary form, not the surface on screen: 食べられた and 食べる are ONE word to study and
    // one row in the collection, and the meaning below belongs to the headword. The form you actually
    // saw is not lost — it is in `src`, the line it came from.
    word: e.term || (shown && shown.matched) || '',
    // The translated line first when there is one. It is the line the reader understood, and for a
    // word the dictionary never had it is the ONLY meaning there is — saving the English definition
    // over it would put a row in the collection in the language they are trying to get out of.
    meaning: (shown && shown.tr) || (senses[0] ? senses[0].gloss : ''),
    reading: e.reading || '',
    ts: Date.now(),
    src: (shown && shown.line) || '',
    // How it reached you, kept beside WHERE it sat. This is the one save path with no translation
    // behind it, and until it said so a pointed word was indistinguishable in the collection from one
    // starred off a snip — which is exactly the word jek could not place (2026-08-12).
    from: 'point',
    seen: 1, // you just met it — same as the pill's ★ does
  };
  // NOT senses[0].pos — that is the dictionary's raw tag ("noun"), and the panel's word tap stores
  // the short mark ("n.") that every chip in the app is drawn from. Storing both spellings for one
  // word class is how the same word ends up looking like two records depending on how it was kept
  // (measured 2026-08-15: a dwell-saved word came in as `noun` while a tapped one came in as `n.`).
  // wordStudyDetail speaks the short one; the raw tag is only the fallback for a word it cannot answer.
  // Everything else a word is worth keeping comes from the one place that knows it — the same
  // function the panel's word tap goes through, so a word collected by pointing is the same record
  // as the same word collected by tapping. It also converts the dictionary's one-gloss-string-per-
  // sense into the { pos, terms } the Learn flashcard prints, which this used to do by hand.
  const detail = wordStudyDetail(entry.word);
  entry.pos = detail.pos || (senses[0] && senses[0].pos) || '';
  if (!entry.pos) delete entry.pos;
  // One sense adds nothing over pos + meaning — the same rule addVocabWord applies in the renderer.
  if (Array.isArray(detail.senses) && detail.senses.length > 1) entry.senses = detail.senses;
  if (detail.defs) entry.defs = detail.defs;
  return entry;
}

// Runs every poll (25/s) while the mode is on, so what it does 25 times a second matters. The word's
// IDENTITY is a property read (hoverTrTerm). It used to build the whole vocab entry here, which runs
// a dictionary lookup and walks its senses — 25 times a second, on the main process, while a game is
// running, for a value only needed when the clock actually elapses. Everything expensive happens once
// now, at the moment it fires. (Found in review, 2026-08-15: the comment on this function claimed it
// was three comparisons and a clock read; it was not.)
function hoverDwellTick() {
  if (!settings.hoverDwellSave || !hoverShownWord) { hoverDwellWord = null; return; }
  const word = hoverTrTerm(hoverShownWord);   // entry.term || matched — no lookup
  if (!word) { hoverDwellWord = null; return; }
  if (word !== hoverDwellWord) { hoverDwellWord = word; hoverDwellSince = Date.now(); hoverDwellDone = false; return; }
  if (hoverDwellDone) return;
  if (Date.now() - hoverDwellSince < HOVER_DWELL_SAVE_MS) return;
  hoverDwellDone = true;                               // one shot per stay, whatever happens next
  // A word you already keep is left alone. Dwelling is a thing you do by ACCIDENT — pausing to read
  // — and the key's second press removes a word. Auto-removing on a pause would delete a collection
  // one glance at a time, so REMOVE stays a deliberate key press and this only ever adds.
  // Asked HERE, on the word saveHoverWord would actually store, and only once per stay.
  if (vocabHas(hoverVocabEntry(hoverShownWord).word)) return;
  saveHoverWord();
}

function saveHoverWord() {
  if (!hoverActive) return; // the key is only bound inside the mode — this is the belt to that brace
  if (!hoverShownWord) { setHintState('Point at a word first'); return; }
  const entry = hoverVocabEntry(hoverShownWord);
  if (!entry.word) return;
  const res = addVocabEntry(entry);
  // Only a REFUSAL is worth words. 'dup' lights the same star as 'added' because the question the key
  // asks is "is this word mine", and the answer is yes either way — telling someone off for keeping a
  // word twice is noise in the middle of a fight.
  if (res === 'full') { setHintState(`Collection is full (${MAX_VOCAB})`); return; }
  // …and a row in History. This key was the ONE way into the collection that wrote nothing there, so
  // a word kept this way could not be found afterwards by the only means anyone looks: scrolling back
  // through what they read. jek hit it exactly — a word in the collection ("passes") with no history
  // row anywhere, measured 2026-08-12: 268 rows back to 19 July, zero matches. The ★ strip in the
  // panel is already described as "a lens over the same reading", so a word that never joins the
  // reading is invisible to its own filter.
  //
  // Only on 'added': re-pointing at a word you already keep must not stack duplicate rows.
  if (res === 'added') {
    // `point` is the fourth source kind, beside live/typed (see srcOf in the renderers). Marking it is
    // the whole reason this row is safe to add — it can be told apart from something you translated.
    const row = { en: entry.word, ts: entry.ts, th: entry.meaning, point: true };
    if (entry.reading) row.reading = entry.reading;
    if (entry.pos) row.pos = entry.pos;
    if (entry.senses) row.senses = entry.senses;
    rememberHistory(row);
    saveHistory();
    // NOT bumpStats: Insights counts words the OCR READ, and pointing at one word is not a read. An
    // entry here would inflate the same tally the Learn window reports as reading volume.
    sendAll('translation:new', row); // no `gen` — the renderers file it and never raise a card (see `point`)
  }
  sendHover('hover:saved', { state: res });
}

function doSnipStart() {
  keepArmedAt = 0; // a fresh snip is a fresh question — see the finally in translateOnce
  // Windows' one chance to learn which app is in front — see captureFrontAppWin. Throttled inside,
  // so the key-repeat burst that reaches this function costs one lookup, not thirty.
  if (process.platform === 'win32') captureFrontApp();
  const now = Date.now();
  const sinceKey = now - lastSnipKeyAt;
  lastSnipKeyAt = now; // bump on EVERY call: while the key is held the gap never reopens
  if (sinceKey < 250) return; // the repeat burst itself
  // NOTHING ELSE IS SWALLOWED HERE. A longer guard used to sit on this line to stop the FIRST repeat
  // (which lands one OS repeat-delay after the press, so it clears the test above) from cancelling a
  // just-armed snip — but it sat in front of every path, including the point-style SHUTTER below,
  // where the second press is how you take the shot. Pressing twice inside a second is exactly what
  // a quick point-snip looks like, so that guard silently ate real captures. It now lives in
  // startWinSnip, on the arm/cancel toggle that actually needed it. (jek, 2026-07-31)
  if (!(winSnipArmed || snipping)) snipOpenedAt = now;
  // Windows normal snip → the click-through hook drag (CC strip-picking still uses the editable overlay).
  if (process.platform === 'win32' && !livePicking && !WIN_CAPTURING_SNIP) {
    // A point session is already live (the user's 'point' style, or a hook-drag that fell back because
    // startWinSnip couldn't get the mouse hook) → this second press is the shutter, like macOS point style.
    if (snipping && snipPointActive) { for (const w of snipWindows) if (!w.isDestroyed()) w.webContents.send('snip:finish'); return; }
    // Honor the Snip-style setting on Windows too (it used to always force the hook drag): 'point' takes
    // the hook-FREE anchor→size→shutter overlay — no global mouse hook, so it also works when anti-cheat
    // blocks hooks. 'drag' keeps the low-level drag hook (which itself falls back to point if it can't
    // install). (jek, Win11 2026-07-31)
    // Space is borrowed for "forget the box, I'll type it" here as well. It used to be grabbed only on
    // the drag-hook path, so choosing the point style — the very style you pick when a game blocks
    // hooks — quietly cost you that escape hatch, with nothing saying so.
    // 'hold' never reaches here from the trigger (the hook handles it end to end) but it does from the
    // pill's ⧉ button, which has no key to hold — a button press gets the drag, the closest thing to it.
    if (effectiveSnipStyle() === 'point') { followCursorMonitor(); showSnipWindows(); grabSnipTypeKey(); return; }
    // Recording mode: drag over a frozen shot instead of over live pixels, so the box is visible to a
    // screen recorder. Everything downstream is unchanged — snip:complete already crops from
    // snipFreeze when it is there.
    if (settings.recordableSnip) { startFrozenSnip(); return; }
    startWinSnip();
    return;
  }
  if (snipping) {
    // macOS point style: a second shortcut press is the shutter that captures the box.
    if (snipPointActive) {
      for (const w of snipWindows) if (!w.isDestroyed()) w.webContents.send('snip:finish');
    }
    return;
  }
  lastPreviewOcr = null; // fresh session — don't reuse a previous box's reading
  lastPreviewTranslate = null;
  followCursorMonitor(); // the game is where you're pointing; bring the pill to that screen
  showSnipWindows();
}

function doClear() {
  history = [];
  saveHistory();
  sendMain('result:hide');
  sendAll('history:clear'); // broadcast — the learn window's History tab clears too
  setHintState('⌘⇧S');
}


// ---------- IPC ----------

// Pill style 'behind' asks the overlay to stop being the top window so anything can cover it — the
// one thing every other style takes for granted. Raised again the moment there is something to see
// (see tuck()/untuck() in the renderer, which own when).
//
// The level is restored to 'screen-saver' rather than plain true: that is what the window was created
// with, and a fullscreen game sits above the ordinary always-on-top level, so coming back as merely
// "on top" would come back underneath the thing the overlay exists to sit over.
//
// NOT YET VERIFIED AGAINST A FULLSCREEN GAME. On macOS a game with its own Space is a stack this
// cannot join by asking politely, so this style is expected to suit windowed and borderless play and
// may simply never reappear over true fullscreen. Whoever tests that first should write the answer
// here rather than re-deriving it.
ipcMain.on('ui:sink', (_e, on) => {
  if (!mainWindow || mainWindow.isDestroyed()) return;
  pillSunk = !!on;
  if (on) mainWindow.setAlwaysOnTop(false);
  else mainWindow.setAlwaysOnTop(true, 'screen-saver');
  // Sinking removes the window's own mouse events; the feed is what stands in for them. Raising puts
  // them back, and needsCursorFeed() will stop it on its next tick.
  updateCursorFeed();
});
// The app's only outbound channel. Two entry points (the card's ⚑ and Settings › Report a problem)
// deliberately land on ONE handler and one endpoint: the difference between "this line read wrong"
// and "the shortcut does nothing" is a field, not a second system to keep working.
//
// Everything the sender would have to remember is attached here rather than asked for: version, OS,
// language pair, and prevFrontApp — the last app that was in front, which during a snip is the game.
// That is the single field this launch needs most ("which game, did it read it") and the one a
// person typing a report at 2am is least likely to include.
ipcMain.handle('report:send', async (_e, arg) => {
  const payload = {
    kind: arg && arg.kind === 'ocr' ? 'ocr' : 'general',
    note: String((arg && arg.note) || '').slice(0, 2000),
    text: String((arg && arg.text) || '').slice(0, 300),
    app: String(prevFrontApp || ''),
    version: app.getVersion(),
    os: `${process.platform} ${process.getSystemVersion()}`,
    langs: `${settings.sourceLang || '?'}>${settings.targetLang || '?'}`,
    engine: String((arg && arg.engine) || ''),
  };
  try {
    const abort = new AbortController();
    const timer = setTimeout(() => abort.abort(), 10000);
    try {
      const res = await fetch(`${GLOSS_SITE}/report`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
        signal: abort.signal,
      });
      return { ok: res.ok };
    } finally { clearTimeout(timer); }
  } catch {
    // No retry queue. A report that fails is a report the person can send again from a screen that
    // is still open — a queue here would be more moving parts than the thing it protects.
    return { ok: false };
  }
});

ipcMain.handle('snip:start', () => doSnipStart());

ipcMain.handle('live:toggle', () => doLiveToggle());
ipcMain.handle('live:pick', () => doLivePick());
ipcMain.handle('hover:toggle', () => toggleHoverMode()); // the row's switch — same toggle as the key // "Choose area" — the where question, kept off the toggle

// The CC edit overlay flips itself click-through (forward) except over the box/buttons, so the
// GAME stays playable while the strip is being adjusted. Per snip window, driven by its renderer.
ipcMain.on('snip:interactive', (e, on) => {
  const win = BrowserWindow.fromWebContents(e.sender);
  if (!win || win.isDestroyed()) return;
  if (on) win.setIgnoreMouseEvents(false);
  else win.setIgnoreMouseEvents(true, { forward: true });
});

ipcMain.handle('snip:cancel', () => closeSnipWindows());

// Typed a letter instead of dragging a box: drop the overlay and hand the character to the Type page,
// so ONE trigger (⌘⇧S or the ⧉ button) covers both "read that text" and "type it".
ipcMain.handle('snip:type', (_e, ch) => {
  closeSnipWindows();
  doTypeFocus(String(ch || '').slice(0, 1));
});

// A rect in the snip overlay's own coordinates -> absolute screen bounds.
function rectToBounds(e, rect) {
  const sender = BrowserWindow.fromWebContents(e.sender);
  const offset = sender && !sender.isDestroyed()
    ? sender.getContentBounds()
    : screen.getPrimaryDisplay().bounds;
  return {
    x: Math.round(rect.x + offset.x),
    y: Math.round(rect.y + offset.y),
    width: Math.round(rect.width),
    height: Math.round(rect.height),
  };
}

// The released box matches the last previewed box (within a few px)? Then the live preview already
// OCR'd this exact region — reuse that text instead of a full duplicate capture+OCR on release.
function matchesPreview(rect) {
  const p = lastPreviewOcr && lastPreviewOcr.rect;
  if (!p) return null;
  const near = (a, b) => Math.abs(a - b) <= 4;
  return (near(p.x, rect.x) && near(p.y, rect.y) && near(p.width, rect.width) && near(p.height, rect.height))
    ? lastPreviewOcr.en : null;
}

ipcMain.handle('snip:complete', (e, rect) => {
  const bounds = rectToBounds(e, rect);
  const cachedText = matchesPreview(rect);
  const forLive = livePicking;
  const frozen = snipFreeze; // grab BEFORE closeSnipWindows nulls it — this is the release crop source
  closeSnipWindows(forLive); // resets livePicking — read it first; keepAside for the ✓ path
  if (!rect || rect.width < 10 || rect.height < 10) return; // too small = a stray click — stay silent (jek 2026-07-26)
  lastSnipFiredAt = Date.now(); // the box was taken - a trigger press right after this means "keep it"
  if (forLive) { startLive(bounds); return; } // this drag DEFINED the live strip — don't translate once
  // If we can reuse the preview's reading, translate immediately — no capture needed at all.
  if (cachedText) { translateOnce(bounds, cachedText); return; } // preview OCR was already capture-hidden — clean
  // Windows freeze-frame: crop the still shot the user actually boxed — no re-capture (which would grab
  // a now-advanced video frame, reading text the user never saw), and no overlay-removal wait needed.
  if (frozen) {
    const preCap = cropRegion(frozen.fullImg, frozen.display, padBounds(bounds));
    if (preCap) { translateOnce(bounds, null, preCap); return; }
  }
  // macOS / fallback: a live capture needs a couple of frames for the compositor to actually remove
  // the overlay first, or its (now shareable) tint/selection bleeds into the OCR'd frame.
  hidePillFromCapture();
  setTimeout(() => translateOnce(bounds), 80);
});

// Live preview while the box is still being dragged. Deliberately cheap: the
// free endpoint, never Claude — a Claude call per drag tick would be slow and
// would cost money for a reading the user is about to change anyway. One at a
// time; a request that arrives while OCR is busy is dropped, not queued.
let previewBusy = false;
// The last box the live preview successfully OCR'd, so release can reuse it (same box) instead of
// running a full duplicate capture+OCR pass. Cleared when a new snip starts so a stale reading from
// a previous session is never reused.
let lastPreviewOcr = null;
// The last OCR'd text + its translation, so a preview tick whose box moved but whose text read the
// same (nudging the box a few px mid-word) reuses the translation instead of firing another Google
// network call. Cleared alongside lastPreviewOcr so a new snip session never reuses a stale pair.
let lastPreviewTranslate = null;

// Shared preview core — OCR + quick Google translate of a screen region. `keyRect` (window-local,
// optional) is remembered so a ⌘⇧S release over the SAME box can reuse this reading. Returns
// { en, th, pos } | null | { busy:true }. Driven by the renderer (snip:preview) AND by the ⌃⌥
// external hook (runExternPreview) so both paths get the same instant preview.
async function computePreview(bounds, keyRect) {
  // Busy is not "nothing found" — tell the caller to keep the current preview
  // rather than hiding a still-valid one while a prior read is in flight.
  if (previewBusy) return { busy: true };
  if (!bounds || bounds.width < 20 || bounds.height < 12) return null;
  if (!checkScreenPermission()) return null;
  previewBusy = true;
  try {
    const cap = await captureRegion(padBounds(bounds));
    if (!cap) return null;

    // Arbitrated like the snip path. This is the card the ⌃⌥ point gesture shows, so it is the read
    // the user sees FIRST — and `lastPreviewOcr` below hands it straight to release, so a misread
    // here is not just a bad preview, it is the translation. jek pointed at hand-lettered "DISGUISE"
    // on 2026-08-10 and got "P15&Ut'E" from this call while the snip path was already fixed.
    const ocr = await recognizeImage(cap.image, true);
    const normalized = normalizeLines(ocr.text);

    if (!normalized.trim() || lowConfidence(ocr) || looksLikeGarbage(normalized)) {
      return null;
    }

    // Remember this reading so release can reuse it (same box) instead of OCR-ing again.
    lastPreviewOcr = { rect: keyRect ? { x: keyRect.x, y: keyRect.y, width: keyRect.width, height: keyRect.height } : null, en: normalized };

    // Live translate the preview with the FREE Google endpoint — ONE quick try (short timeout) so a
    // slow/blocked call never stalls the preview (which would make it "sometimes not appear"). The
    // rich card (Claude, if a key is set) still happens once on release.
    // Skip the network call entirely when this tick's OCR read the same text as last tick (the box
    // moved a few px but is still framing the same word/line) — reuse the cached translation.
    let th, pos;
    if (lastPreviewTranslate && lastPreviewTranslate.en === normalized) {
      th = lastPreviewTranslate.th; pos = lastPreviewTranslate.pos;
    } else {
      const g = await translate(normalized, { tries: 1, timeoutMs: 1500 }).catch(() => ({ text: '', pos: '' }));
      th = g.text; pos = g.pos;
      lastPreviewTranslate = { en: normalized, th, pos };
    }
    return { en: normalized, th, pos };
  } catch (err) {
    console.error('Preview failed:', err);
    return null;
  } finally {
    previewBusy = false;
  }
}

ipcMain.handle('snip:preview', (e, rect) => {
  // Windows: no live preview while dragging. Preview runs tesseract (WASM, slow) on every settle and
  // stuttered the drag — box the region, then OCR once on release (snip:complete). Mac uses fast Vision.
  if (process.platform !== 'darwin') return null;
  if (!rect || rect.width < 20 || rect.height < 12) return null;
  return computePreview(rectToBounds(e, rect), rect);
});

ipcMain.handle('translate:text', (_e, text) => translateText(text));
// Live dictionary peek for the type box: the FREE Google endpoint only (never Claude — this fires
// while you type, so it must cost nothing and land fast). It is a read-only side channel: no history
// row, no card, no status hint, no generation bump — so a peek can never disturb a real translation.
ipcMain.handle('translate:peek', async (_e, text) => {
  const clean = String(text || '').trim();
  if (!clean) return { text: '', pos: '' };
  try {
    const g = await translate(clean, { tries: 1, timeoutMs: 4000 });
    wordCachePut(clean, { text: g.text, pos: g.pos, senses: g.senses });
    return g;
  }
  catch {
    // Same rule as the word tap below: offline, a single word still has an answer on disk.
    const local = offlineWordAnswer(clean);
    return local ? { ...local, offlineDict: true } : { text: '', pos: '', error: true }; // a typing-speed blip stays silent
  }
});

ipcMain.handle('vocab:segment', (_e, text) => segmentWords(String(text || '').trim()));

ipcMain.handle('vocab:translate-word', async (_e, word) => {
  // Trailing punctuation is why `command...` had no part of speech: every dictionary holds `command`
  // and none holds `command...`. Stripped for the LOOKUP only — what gets saved is still the word the
  // caller sent, so the row keeps reading the way the line did.
  // \p{M} belongs in the keep set or the strip eats a Thai word's own vowel: สวัสดี → สวัสด, because
  // the trailing ี is a combining mark, neither a letter nor a number.
  const clean = String(word || '').trim();
  const term = clean.replace(/^[^\p{L}\p{N}\p{M}]+|[^\p{L}\p{N}\p{M}]+$/gu, '') || clean;
  if (!clean) return { error: 'empty' };
  try {
    {
      const g = await translate(term);
      // Google answers for headwords only; the local index deinflects and covers the rest.
      const pos = g.pos || posFromLocalDict(term);
      // …and the senses, for the same reason. A word the dt=bd block has no group for kept its
      // translation and lost every other part of speech, which is the row the bubble and the card
      // both draw from.
      const senses = (g.senses && g.senses.length) ? g.senses : ((localWordAnswer(term) || {}).senses || []);
      // Into the shared cache, so pointing at this same word later answers with THIS line.
      wordCachePut(term, { text: g.text, pos, senses });
      // …and the dictionary's own definitions ride back with it, so the row the renderer saves is
      // the same record hoverVocabEntry builds. Neither surface decides what a word is worth.
      return { th: g.text, pos, senses, defs: wordStudyDetail(term).defs };
    }
  } catch (err) {
    // No network is not "no answer": the dictionary that point-at-a-word reads is on disk, and for a
    // single word it is the same answer this endpoint would have given. Only after IT comes up empty
    // is this a failure worth showing (jek, 2026-08-15 — the bar should not need the internet).
    const local = offlineWordAnswer(term);
    if (local) return { th: local.text, pos: local.pos, senses: local.senses, defs: wordStudyDetail(term).defs, offlineDict: true };
    console.error('Vocab word translate failed:', err);
    return { error: errorForPill(err) };
  }
});

// CHECK a licence key before telling anyone it worked. Saving one used to be blind — the field
// accepted whatever was typed and said "Licence saved", so a typo and a real key were the same
// event, and the difference only surfaced later as an AI call that failed for no stated reason.
// /v1/quota is the cheap question: it answers with the plan the key buys and spends nothing.
//
// Three outcomes, and they must stay three. `ok` — the server knows this key. `invalid` — it does
// not, and that is worth saying now. `unreachable` — we do not know, which is NOT the same as
// invalid and must never be shown as it: the Worker is not deployed yet, so today this is the
// common answer, and a build that called that "wrong key" would accuse every honest buyer.
ipcMain.handle('licence:verify', async (_e, key) => {
  const licence = String(key || '').trim();
  const headers = { 'x-gloss-device': deviceId() };
  if (licence) headers['x-gloss-licence'] = licence;
  const abort = new AbortController();
  const timer = setTimeout(() => abort.abort(), 8000);
  try {
    const res = await fetch(`${GLOSS_API}/v1/quota`, { headers, signal: abort.signal });
    const data = await res.json().catch(() => ({}));
    if (res.ok) {
      // The third place that learns the real count, and until 2026-09-08 the only one that threw it
      // away — the two AI-call sites publish it (see the 402 branch and the header branch above).
      // It is the worst one to miss: this runs the moment someone pastes the key they just paid for,
      // so Settings answered "6 of 10 AI reads left" — the FREE numbers — directly under a licence
      // that had verified fine. A buyer reads that as the key not working, on the one screen where
      // they are checking whether it did. Publish it the same way the other two do.
      if (Number.isFinite(Number(data.used)) && Number.isFinite(Number(data.limit))) {
        quotaState = { plan: data.plan || 'free', used: Number(data.used), limit: Number(data.limit) };
        sendAll('settings:changed', uiSettings());
      }
      return { state: 'ok', plan: data.plan || 'free', used: data.used, limit: data.limit };
    }
    // 401 is the server saying "not this key" — the body marker is the precise form (errStatus in
    // worker/src/index.js maps 'licence' → 401), the status alone is the fallback for any gateway
    // that answers before the Worker does. Everything else is "we do not know", which is saved and
    // said as such: never accuse a buyer because a proxy hiccuped.
    // 'unconfigured' is the one 401 that is not about the key: the Worker is missing the secret it
    // verifies our own keys with. Saying 'invalid' there would accuse a buyer for our own mistake,
    // which is the exact failure the three states above exist to prevent.
    if (data && data.error === 'licence' && data.reason === 'unconfigured') return { state: 'unreachable', http: 401 };
    if ((data && data.error === 'licence') || res.status === 401) return { state: 'invalid', reason: (data && data.reason) || '' };
    return { state: 'unreachable', http: res.status };
  } catch {
    return { state: 'unreachable' };
  } finally {
    clearTimeout(timer);
  }
});

ipcMain.handle('speak:toggle', () => toggleSpeak());
ipcMain.handle('app:clear', () => doClear());

// "Open Settings" for whichever permission is in the way. This was darwin-only and silently did
// NOTHING everywhere else — which is why a Windows user got told to go to Privacy › Speech in words
// while a mac user got a button that took them there. Windows has had deep links the whole time
// (ms-settings:), so there was never a reason for the gap beyond nobody filling it in. (jek, 2026-08-07)
const SETTINGS_PANE = {
  darwin: {
    screen: 'x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture',
    // Added when the banner started speaking for Accessibility too. Without a pane here its button
    // would have been present and dead — the one failure mode this whole banner exists to prevent.
    // No win32 twin on purpose: the hold trigger there is a keyboard hook, which asks for nothing.
    accessibility: 'x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility',
    speech: 'x-apple.systempreferences:com.apple.preference.security?Privacy_SpeechRecognition',
    mic: 'x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone',
  },
  win32: {
    speech: 'ms-settings:privacy-speech',
    mic: 'ms-settings:privacy-microphone',
    // Time & language › Language & region — where the OCR pack is added, per language, under Optional
    // features. Launched and confirmed to open Settings before being added here, as the note below asks.
    ocr: 'ms-settings:regionlanguage',
    // No 'screen' entry, and NOT because Windows has no such permission — it does: the consent store
    // carries graphicsCaptureProgrammatic and graphicsCaptureWithoutBorder (measured on Win11,
    // 2026-08-07, both Allow). They gate Windows.Graphics.Capture. This app does not use it: the
    // Windows path is GDI BitBlt (wincapture.js) with Electron's desktopCapturer behind it, so
    // permission:needed never fires here and there is nothing to open. If a capture path that DOES go
    // through WGC ever lands, this is the line that needs a pane — verify the ms-settings URI by
    // launching it before adding one, rather than guessing the slug.
  },
};
ipcMain.handle('permission:open-settings', (_e, pane) => {
  const url = (SETTINGS_PANE[process.platform] || {})[pane || 'screen'];
  if (url) shell.openExternal(url);
  // The path goes on the clipboard on the way out, because the hard part of that pane is not finding
  // it — it is the + button's file picker. Every copy of this app on the disk is called "Gloss" (the
  // name comes from Info.plist, not the folder), so the picker shows a row of identical icons and no
  // way to tell the running one from a backup or a stale build — jek, 2026-09-01, staring at three:
  // "dont know what to choose". With this, ⌘⇧G then ⌘V in that picker lands on the exact bundle that
  // asked for the permission, and there is nothing left to choose.
  try { clipboard.writeText(appBundlePath()); } catch { /* clipboard is a convenience, never a step */ }
  return appBundlePath();
});

// macOS does not hand a running app a screen-recording grant it did not have at launch — its own
// dialog says "Quit & Reopen" for exactly this reason. Nothing in the app said so, so the honest
// outcome of following every instruction correctly was still a red dot, and no way to tell a
// permission that had not been granted from one that had not been picked up yet.
ipcMain.handle('app:relaunch', () => {
  app.relaunch();
  app.isQuitting = true; // let the learn window's close handler actually close (see createLearnWindow)
  app.quit();
});

// What the permission lists accept is the BUNDLE — Gloss.app — and app.getPath('exe') is the binary
// buried three levels inside it (Gloss.app/Contents/MacOS/Gloss). Revealing that showed a file with a
// generic "exec" icon that cannot be dragged into the list at all: the button meant to end the "which
// file?" confusion was handing over a file that is never the answer. Found by looking at what the
// button actually opened, not at what it was supposed to open (jek, 2026-08-08).
function appBundlePath() {
  const exe = app.getPath('exe');
  if (process.platform === 'darwin') {
    const m = exe.match(/^(.*\.app)\/Contents\/MacOS\/[^/]+$/);
    if (m) return m[1];   // packaged: hand back the .app
  }
  return exe;             // dev run (bare Electron) and Windows: the executable IS the thing
}

// Point at the running app in the file manager, so re-adding it to a permission list is a drag and
// not a search. This exists because of a REAL dead end, not a hypothetical one: the OS lists a
// permission by app NAME, so a stale entry reads as "Gloss ✓ on" while denying us; the fix is to
// remove that entry and add the app again — and at THAT moment the picker asks for a file, with no
// clue which one. There can easily be two: a copy in /Applications and another in ~/Applications,
// identically named and identically iconned. Picking the wrong one grants a green toggle that
// changes nothing, which lands the user right back where they started, more confused than before.
// appBundlePath() is derived from the binary that is running now, so this cannot point at the wrong copy.
// Returns the path it revealed so a test can assert WHICH file the button opens — the bug this
// replaced was invisible to any check that only asked whether the button did something.
ipcMain.handle('app:reveal', () => { const p = appBundlePath(); shell.showItemInFolder(p); return p; });

// ---- Glass backdrop ------------------------------------------------------------------------
//
// The pill has always CALLED itself glass ("macOS-glass look" on .pill) while being a flat opaque
// slab, because on a transparent always-on-top overlay backdrop-filter has nothing to work with:
// there is no page behind us to blur, only the desktop, and the compositor won't reach through the
// window to it (see the --bg comment in styles.css — that is why --bg had to go FULLY opaque).
//
// So we hand the renderer the pixels ourselves. We already own a screen-capture path for OCR and a
// way to make our own window invisible to it (setContentProtection), which is exactly the pair a
// real glass effect needs: grab what is behind the stack, WITHOUT the stack in the frame.
//
// The image comes back absurdly small — GLASS_W px wide — and that is the blur. Stretching a 24px
// bitmap across a 336px pill means one source pixel per 14 screen pixels, and the bilinear upscale
// between them IS a gaussian. So the renderer needs no filter: no GPU blur pass on a window that
// sits over live gameplay, no filter-region square-corner artifact (the exact bug that made
// backdrop-filter unusable here — see the --bg note in styles.css), a ~1KB dataURL per sample, and
// it survives being painted as a plain background on a surface that scrolls internally.
const GLASS_W = 24;
let glassBusy = false;      // one capture in flight at a time; every trigger can fire freely
let glassLastAt = 0;        // ...and they coalesce onto this floor instead of stacking captures
const GLASS_MIN_GAP_MS = 900;  // one capture costs ~285ms of session setup; never chain them

// Average colour + brightness of the sampled patch. Both drive the look: the tint warms the rim and
// the sheen so the pill belongs to the scene it is sitting on, and the brightness decides how hard
// the scrim has to work — glass over a white webpage needs a much heavier dim than glass over a
// night-time game, or the label stops being readable.
function glassStats(img) {
  const { width, height } = img.getSize();
  const buf = img.getBitmap(); // BGRA, 4 bytes/px
  let r = 0, g = 0, b = 0, n = 0;
  for (let i = 0; i < buf.length; i += 4) { b += buf[i]; g += buf[i + 1]; r += buf[i + 2]; n++; }
  if (!n) return null;
  r = Math.round(r / n); g = Math.round(g / n); b = Math.round(b / n);
  void width; void height;
  return {
    tint: [r, g, b],
    // Rec. 709 luma, 0..1 — what the eye actually reads as "bright", not the raw mean.
    luma: (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255,
  };
}

ipcMain.handle('glass:sample', async (_e, rect) => {
  if (!mainWindow || mainWindow.isDestroyed() || !rect) return null;
  // A snip is its own capture with its own protection juggling — two of them interleaved would
  // leave the pill hidden from the screenshot the user actually asked for. Glass can wait.
  if (snipping || glassBusy) return null;
  if (Date.now() - glassLastAt < GLASS_MIN_GAP_MS) return null;
  if (process.platform === 'darwin' &&
      systemPreferences.getMediaAccessStatus('screen') !== 'granted') return null; // stay silent: the pill already shows the permission banner

  glassBusy = true;
  const wasProtected = mainWindow._gtProtected;
  try {
    const win = mainWindow.getBounds();
    // PAD: the blur samples past the element's own edge, so a crop that stops at the edge bleeds
    // transparent black in and rims the pill with a dark halo. Give the blur real pixels to reach into.
    const PAD = 28;
    const want = {
      x: Math.round(win.x + rect.x - PAD),
      y: Math.round(win.y + rect.y - PAD),
      width: Math.round(rect.width + PAD * 2),
      height: Math.round(rect.height + PAD * 2),
    };
    const db = screen.getDisplayMatching(want).bounds;
    const x = Math.max(db.x, want.x);
    const y = Math.max(db.y, want.y);
    const bounds = {
      x, y,
      width: Math.min(db.x + db.width, want.x + want.width) - x,
      height: Math.min(db.y + db.height, want.y + want.height) - y,
    };
    if (bounds.width < 8 || bounds.height < 8) return null;

    hidePillFromCapture(); // or we photograph ourselves and the pill mirrors into itself, frame after frame
    // macOS: sharingType is a compositor-side change, and a capture issued in the same tick can still
    // catch the last composited frame — with us in it. One frame of slack is enough and invisible.
    if (!IS_WIN) await new Promise(r => setTimeout(r, 24));

    const shot = await captureRegion(bounds);
    if (!shot) return null;
    const small = shot.image.resize({ width: GLASS_W, quality: 'good' });
    const stats = glassStats(small);
    return {
      url: small.toDataURL(),
      tint: stats ? stats.tint : null,
      luma: stats ? stats.luma : 0.5,
      // The renderer aligns each surface against this rect, so the pill and the panel show ONE
      // continuous backdrop instead of two independently-cropped ones.
      pad: { x: (win.x + rect.x) - bounds.x, y: (win.y + rect.y) - bounds.y, w: bounds.width, h: bounds.height },
    };
  } catch (err) {
    console.warn('glass: sample failed', err && err.message);
    return null;
  } finally {
    // Put protection back exactly as it was — applyContentProtection() would otherwise clear a hide
    // that a snip/live session had set for its own reasons.
    //
    // `snipping` is re-read HERE, not captured at the top: a snip can start during the ~285ms this
    // capture takes, and it hides the pill for its own reasons. Restoring over it would un-hide the
    // pill mid-snip, which puts our own "EN → TH" into the image the user is trying to read — the
    // exact bug hidePillFromCapture exists to prevent. Leave it hidden; the snip's own teardown
    // restores it. (2026-08-02)
    if (!wasProtected && !snipping) applyContentProtection();
    glassLastAt = Date.now();
    glassBusy = false;
  }
});

// The renderer toggles this as the cursor moves on/off the pill and panels, so
// transparent regions stay click-through to the game underneath.
let interactiveState = false;
// Pill style 'Window' is on and the overlay is currently sunk. Lives beside interactiveState because
// the two answer one question between them: whether this window is in a position to be clicked.
let pillSunk = false;
ipcMain.on('ui:dragging', (_e, on) => { pillDragging = !!on; });
ipcMain.on('ui:interactive', (_e, on) => {
  if (!mainWindow || mainWindow.isDestroyed() || on === interactiveState) return;
  // While a snip overlay is up, the pill window must NEVER go interactive: both windows are
  // full-screen, and an interactive pill window sitting under the cursor EATS the clicks meant
  // for the overlay — this is why grabbing the CC box only worked outside the pill's footprint.
  // EXCEPT while picking the live strip: the pill has stepped aside (no overlap) and its CC
  // button doubles as Cancel, so it must stay clickable.
  if (on && snipping && !livePicking) return;
  console.log('[DBG] ui:interactive ' + on);
  interactiveState = on;
  if (on) mainWindow.setIgnoreMouseEvents(false);
  else mainWindow.setIgnoreMouseEvents(true, { forward: true });
  setClickShield(on);
  // NO holdForeground('pill') here any more, and the click leaking into the game is the PRICE, paid
  // deliberately (jek, 2026-08-30). Taking the foreground is the only thing that stops a click
  // reaching a foreground game (see holdForeground), and it cost the game itself: every time a hand
  // rested on the pill the game was pushed to the background — muted, paused, or flipped out of
  // fullscreen — for a visit lasting a couple of seconds. "ความต่อเนื่องในการเล่นเกมสำคัญกว่า": an
  // unbroken game is worth more than a click that cannot leak, so the overlay now never takes the
  // foreground for a hover, and a stray click landing in the game is accepted.
  //
  // setClickShield above is still armed and still worth arming: it swallows the message at the
  // low-level hook, which stops every game that reads the mouse through WINDOW MESSAGES. Only games
  // reading Raw Input see the click now — that is a smaller set than "all of them", and it costs
  // nothing to keep.
  //
  // The way to use History / Type / Settings without a stray click is to PAUSE the game first, which
  // is what someone opening a panel is doing anyway. Typing still takes the foreground, through the
  // 'field' holder only, for exactly as long as a real text field has focus.
  updateCursorFeed();
});

// WINDOWS. Capturing the mouse is only half of not-clicking-the-game. The overlay is non-activating
// (focusable:false), so the GAME stays foreground, and a foreground game reads the mouse through Raw
// Input — which is delivered per-device, not per-window, and does not care that the cursor is over
// our pill. So a click on a pill button also fired in the game (jek 2026-08-29, right after the
// no-activate fix landed). The only place that reaches is the low-level hook: swallow the button
// there so nothing downstream ever sees it, then re-inject it into the overlay ourselves.
//
// Armed on exactly the same signal that makes the window capture the mouse, so the shield can never
// be eating clicks at a moment the pill wouldn't have taken them anyway.
function setClickShield(on) {
  if (!IS_WIN || !startShield) return;
  if (!on) { stopShield(); return; }
  startShield((kind, x, y, button, clickCount, delta) => {
    if (!mainWindow || mainWindow.isDestroyed()) return;
    const b = mainWindow.getBounds();
    // sendInputEvent wants window-relative DIP; globalX/Y carry the screen point so the page still
    // reads a correct e.screenX — which is what armDrag measures its drag from.
    const base = { x: Math.round(x - b.x), y: Math.round(y - b.y), globalX: Math.round(x), globalY: Math.round(y) };
    try {
      if (kind === 'wheel') {
        // WHEEL_DELTA units, already normalised to notches. Chromium's own wheel step is ~100px, and
        // the sign matches: a wheel AWAY from you is positive in Win32 and scrolls content UP.
        mainWindow.webContents.sendInputEvent({
          type: 'mouseWheel', ...base,
          deltaX: button === 'h' ? delta * 100 : 0,
          deltaY: button === 'h' ? 0 : delta * 100,
          canScroll: true,
        });
        return;
      }
      mainWindow.webContents.sendInputEvent({
        type: kind === 'down' ? 'mouseDown' : 'mouseUp', ...base,
        button, clickCount: clickCount || 1,
      });
    } catch { /* window went away mid-click */ }
  });
}

// The renderer decides interactive/hover purely from mousemove — and there is one state where those
// STOP ARRIVING: window capturing the mouse (ignoreMouseEvents false) while our app is NOT the active
// one. macOS only delivers mouseMoved to the active app, and Electron's forwarding is disabled unless
// ignore is true, so the renderer goes blind exactly when the overlay is holding the mouse. It then
// stays interactive forever: hover frozen, clicks that should reach the game eaten, and the pill
// unresponsive until a drag happened to reset it (the post-Enter bug). Feed it the cursor ourselves
// for as long as that state lasts — it ends the moment the cursor leaves the pill, which is the point.
let cursorFeedTimer = null;
function stopCursorFeed() { clearInterval(cursorFeedTimer); cursorFeedTimer = null; }
// When the renderer cannot see the cursor for itself. Three cases, and the third is the whole reason
// hover ever worked on macOS and never on Windows:
//   (a) a SNIP session — the overlay is click-through and the snip window eats every move;
//   (b) window interactive but our app inactive (a text field is open) — macOS only delivers
//       mouseMoved to the active app;
//   (c) WINDOWS, click-through and unfocused — i.e. the pill's ordinary resting state.
//
// (c) was measured, not assumed (Win11, Electron 32.3.3, 2026-07-31): sweeping the cursor 60 times
// across the pill produced 0 document mousemove, 0 ui:cursor and 0 updateHover calls in the renderer.
// setIgnoreMouseEvents(true, {forward: true}) is passed correctly at all 13 call sites; Windows simply
// does not deliver it to an unfocused click-through overlay. updateHover() is the ONLY thing that sets
// hover and interactive, so on Windows the expand-on-hover pill and the panel auto-hide countdown were
// both dead code paths — and they could not recover, because the old condition (b) required
// interactiveState, which only updateHover can ever set. A closed circuit.
function needsCursorFeed() {
  if (!mainWindow || mainWindow.isDestroyed()) return false;
  if (snipping) return true;                                    // (a)
  if (interactiveState && !mainWindow.isFocused()) return true; // (b)
  if (IS_WIN && !interactiveState) return true;                 // (c) — Windows only; macOS is unchanged
  // (d) Pill style 'Window'. A sunk overlay is in exactly the position (c) exists for: it is no
  // longer the window the pointer lands on, so no DOM mousemove ever reaches the page, so the
  // renderer never learns the cursor is over the pill, so setInteractive(true) is never called —
  // and the pill cannot be hovered or clicked at all, for the rest of the session. The feed is what
  // replaces the events the window stopped receiving, and it has to run on macOS too, which (c)
  // deliberately does not. Costs a getCursorScreenPoint per tick and nothing else; it stops the
  // moment the pill is raised, because from then on the window is back on top and gets its own
  // events. (Found by using it: jek, 2026-08-15, "why cannot I click or hover the pill".)
  if (pillSunk && !interactiveState) return true;               // (d)
  return false;
}
let lastFedX = null, lastFedY = null;
// 60ms is right for the pill: it answers "is the pointer over me", which does not need a frame rate.
// It is wrong for the snip ring, which is DRAWN from this feed and therefore inherits its cadence —
// at 60ms a moving cursor leaves the ring visibly behind and it catches up in 60ms hops. Measured
// with the cursor sweeping while the trigger was pressed (2026-08-15): 490 → 580 → 700 → 820 → 850,
// four jumps to arrive, which is the "อยู่ไม่ถูกที่แล้ววาร์ปมาถูกที่" jek reported. A snip lasts a couple of
// seconds; paying a screen.getCursorScreenPoint per frame for it is nothing.
const CURSOR_FEED_MS = 60;
const CURSOR_FEED_SNIP_MS = 16;
let cursorFeedRate = CURSOR_FEED_MS;
function updateCursorFeed() {
  if (!needsCursorFeed()) { stopCursorFeed(); return; }
  // The rate depends on WHO is being fed, and snipping can start while the feed is already running
  // for the pill — so a running timer at the wrong rate is restarted rather than left alone.
  const want = snipping ? CURSOR_FEED_SNIP_MS : CURSOR_FEED_MS;
  if (cursorFeedTimer && cursorFeedRate !== want) stopCursorFeed();
  if (cursorFeedTimer) return;
  cursorFeedRate = want;
  cursorFeedTimer = setInterval(() => {
    if (!needsCursorFeed()) { stopCursorFeed(); return; }
    const isSnip = !!snipping;
    const p = screen.getCursorScreenPoint();
    const b = mainWindow.getBounds(); // full-screen canvas: window-relative points == the page's client coords
    const x = p.x - b.x, y = p.y - b.y;
    // A still cursor is the common case now that this runs all the time on Windows — skip the IPC and
    // the elementFromPoint it triggers rather than repeat the same answer 16 times a second. Snip
    // payloads are left alone; that path is timing-sensitive and was not the thing being fixed.
    if (!isSnip && x === lastFedX && y === lastFedY) return;
    lastFedX = x; lastFedY = y;
    // Multi-monitor: the cursor may be on a display the overlay is not on, which puts this point
    // outside the page. That is deliberately still sent — elementFromPoint returns null for it and the
    // renderer collapses the pill, which is exactly right for "the cursor is somewhere else".
    const payload = { x, y };
    if (isSnip) payload.snip = true;
    sendMain('ui:cursor', payload);
    if (isSnip) feedSnipCursor(p);
  }, cursorFeedRate);
}

// The overlay's ring must track the REAL cursor, not only its own mousemove. The snip windows are
// REUSED (shown/hidden, re-bounded), and Chromium replays a stale mousemove — the previous session's
// last point — when a window is shown again, which parked the ring far from the cursor until the mouse
// moved and it visibly warped over. snip:reset now seeds the true point for frame 1, and this poll —
// the same OS-cursor authority the pill already runs on while snipping — keeps it honest afterwards.
function feedSnipCursor(p) {
  for (const win of snipWindows) {
    if (win.isDestroyed() || !win.isVisible()) continue;
    win.webContents.send('snip:cursor', ringPoint(p));
  }
}
// SCREEN coordinates, deliberately: each overlay converts with its own live origin at paint time. Main
// converting here would bake in the bounds as they were when the message was sent, and macOS moves the
// overlay AFTER it is shown (0,0 → 0,30, measured) — which is exactly how the ring ended up painted in
// the wrong place for the first frames of a snip. The page also clips it, so a cursor on another
// display simply lands outside every overlay's viewport.
function ringPoint(p) {
  return { sx: p.x, sy: p.y };
}

// WINDOWS. Taking the foreground off the game, and handing it straight back.
//
// ONE holder is left. The set stays, because two of them have already existed and a third will: the
// bug it prevents is two callers each keeping their own boolean and one of them releasing while the
// other still wants to be held.
//   'field' — a real text field is focused, and WS_EX_NOACTIVATE means the keystrokes go elsewhere.
//             Typing is the one thing that CANNOT be done from the background, so this is not a
//             trade-off, it is the only way in. It lasts as long as the field has focus, no longer.
// It cannot arm itself — a click can only focus a field once the window is already foreground — so
// the renderer asks through ui:focus-field on the mousedown that is about to focus one, and that is
// the ONLY thing in the app that takes the foreground now.
//
// 'pill' USED TO BE THE SECOND ONE and was removed on 2026-08-30. It held the foreground for as long
// as the cursor rested on our UI, so that a click could not reach the game: a foreground game reads
// the mouse through Raw Input, which is delivered per-device, cannot be filtered by any hook, and
// only reaches the FOREGROUND window — so not being it was the whole fix (jek 2026-08-29). It worked,
// and it cost more than it bought. Every visit to the pill pushed the game to the background for a
// couple of seconds, and a game that pauses or mutes itself when inactive did exactly that, over and
// over, for a single button press. jek, 2026-08-30: "ความต่อเนื่องในการเล่นเกมสำคัญกว่า" — an unbroken
// game is worth more than a click that cannot leak.
//
// So a click on the pill can now also land in the game, on purpose. What still catches most of them
// is setClickShield, which swallows the message at the low-level hook: only Raw Input readers get
// through. The escape hatch for the rest is to PAUSE the game before opening History/Type/Settings,
// which is what a player doing those things is doing anyway.
//
// A dwell-press gesture (rest on a button, no click at all) was built and removed the same day — it
// made the pill hard to press and did not touch the panels, which are where the interruption is felt.
// Do not reach for it again.
// macOS keeps the old no-op: focusable:false there HID the window and didn't stop the focus-steal
// anyway, which is the revert this comment used to record.
let mainWinPrevFg = null;
const fgHolders = new Set();
function holdForeground(who, on) {
  if (!IS_WIN || !mainWindow || mainWindow.isDestroyed()) return;
  const had = fgHolders.size > 0;
  if (on) fgHolders.add(who); else fgHolders.delete(who);
  const want = fgHolders.size > 0;
  console.log('[DBG] hold ' + who + '=' + on + ' set={' + [...fgHolders].join(',') + '} focused=' + mainWindow.isFocused() + ' interactiveState=' + interactiveState);
  if (want === had) return; // the other holder is still keeping us here
  if (want) {
    // Remember who was foreground BEFORE we take it — that is the game, and the only way back.
    try { mainWinPrevFg = foregroundWindow ? foregroundWindow() : null; } catch { mainWinPrevFg = null; }
    mainWindow.setFocusable(true);
    // focus() alone is not enough: Electron routes it to SetForegroundWindow, which Windows refuses
    // to a process that is not already foreground — silently. Same dance startWinSnip needs.
    let got = false;
    try { got = forceForeground ? forceForeground(mainWindow.getNativeWindowHandle()) : false; } catch {}
    if (!got) mainWindow.focus();
    console.log('[DBG] fg TAKEN native=' + got);
  } else {
    console.log('[DBG] fg RELEASED');
    mainWindow.setFocusable(false);
    // Hand it back the same tick the last holder lets go, so the game is out for the length of the
    // visit and no longer.
    try { if (mainWinPrevFg) restoreForeground(mainWinPrevFg); } catch {}
    mainWinPrevFg = null;
  }
}
// Drop every hold at once. Used where the foreground is being handed back wholesale rather than by
// one holder letting go — see returnFocusFromType. Iterating the set is the point: a caller that
// names its holders is a caller that silently stops working when a holder is renamed or removed.
function releaseAllForeground() {
  for (const who of [...fgHolders]) holdForeground(who, false);
  // The renderer keeps its own edge-guarded mirrors of these two (focusableNow / panelHoverNow) and
  // would otherwise never send `true` again — it thinks it already did. Tell it to forget.
  sendMain('ui:foreground-reset');
}

ipcMain.on('ui:focusable', (_e, on) => holdForeground('field', !!on));
// The deadlock this breaks: a text field can only take DOM focus if the window is already foreground,
// and the 'field' hold only arms once a field HAS focus. Clicking the Type bar therefore did nothing
// at all — no caret, ever (jek, 2026-08-30). So the renderer asks for the foreground on the mousedown
// that is about to focus a field, and waits for the answer before calling .focus().
//
// A 'panel' holder was tried first and is gone: it took the foreground the moment the CURSOR entered
// an open panel, which meant the game stopped or kept playing depending on where the hand happened to
// be resting — two different triggers for one action ("ทำไมบางทีเกมมันหยุด บางทีเกมมันเล่นต่อ", jek).
// One trigger now, and the narrowest one there is: nothing but a click into a text box takes the
// foreground. Hovering the panel, scrolling History, tapping ☆ — none of them touch the game.
ipcMain.handle('ui:focus-field', () => {
  holdForeground('field', true);
  return true;
});

ipcMain.handle('app:quit', () => {
  app.quit();
});

ipcMain.handle('learn:open', () => openLearnWindow());

// (app:minimize used to live here; the pill has no minimize affordance.)

ipcMain.handle('settings:get', () => uiSettings());

// Clamp what comes in. The renderers clamp too, but a store that trusts its callers has no floor —
// a hand-edited settings.json or a future non-UI writer would otherwise set gradSeen to 0 (every word
// instantly "known") or maxHistory to 5,000,000 (history.json eats the disk). Kept next to the values
// it guards, in DEFAULT_SETTINGS order.
const NUM_LIMITS = {
  cardSize: [10, 28], slideSpeed: [10, 200], holdSec: [0, 120],
  ccIntervalMs: [300, 10000],
  gradSeen: [2, 50], reviewCap: [0, 200], maxHistory: [20, 2000],
};
function clampSettings(patch) {
  const out = { ...patch };
  for (const [k, [lo, hi]] of Object.entries(NUM_LIMITS)) {
    if (!(k in out)) continue;
    const n = Number(out[k]);
    if (!Number.isFinite(n)) { delete out[k]; continue; } // garbage in → keep what we had
    out[k] = Math.min(hi, Math.max(lo, Math.round(n)));
  }
  // The pair is not settable in the locked edition — not by a hand-edited settings.json, not by an
  // older renderer, not by anything. The pickers are gone from the UI; this is the floor under them.
  if (PAIR_LOCK) { delete out.sourceLang; delete out.targetLang; }
  if ('vocabSortDefault' in out && !['new', 'seen', 'due'].includes(out.vocabSortDefault)) delete out.vocabSortDefault;
  // An unknown pillStyle would leave the pill in a state no CSS describes — drop it and keep what we had.
  if ('pillStyle' in out && !['visible', 'dim', 'ghost', 'ghostdim', 'behind'].includes(out.pillStyle)) delete out.pillStyle;
  for (const k of ['showEnglish', 'showPos', 'showEnMeaning', 'showReading', 'showSenses',
    'hideFromCapture', 'autoHidePanel', 'pillKeyword', 'followMonitor',
    'openAtLogin', 'aiCards', 'aiMixedRead', 'hoverDwellSave', 'reverseDefault', 'testDefault', 'speakOnFlip',
    'recordableSnip']) {
    if (k in out) out[k] = !!out[k];
  }
  return out;
}

ipcMain.handle('settings:set', (_e, patch) => {
  settings = { ...settings, ...clampSettings(patch) };
  saveSettings();
  if ('hideFromCapture' in patch) applyContentProtection();
  if ('openAtLogin' in patch) applyLoginItem();
  sendAll('settings:changed', uiSettings()); // every window: the Plan tab saves the key, the pill draws the PRO tag
  return uiSettings();
});

// Reset every setting back to defaults, but KEEP the saved Claude key — a "reset" shouldn't silently
// wipe a credential the user pasted (re-entering an sk-ant-… key is a real hassle).
// Open a link in the real browser. Allow-listed rather than "open whatever the renderer says" —
// the renderer has no business being able to launch arbitrary URLs.
// Where "Get Gloss Pro" goes. One constant, sent to both windows in the settings snapshot, so the
// day a real checkout exists exactly one line changes and neither renderer has to be touched. Until
// then it lands on the site's pricing section, which is an honest destination rather than a button
// that does nothing — never a dead end.
const BUY_URL = process.env.GLOSS_BUY_URL || 'https://gloss-6xm.pages.dev/#pricing';
const OPENABLE = new Set(['https://console.anthropic.com/settings/keys', BUY_URL]);
ipcMain.handle('open:url', (e, url) => {
  if (!OPENABLE.has(url)) return false;
  shell.openExternal(url);
  return true;
});

ipcMain.handle('settings:reset', () => {
  settings = { ...DEFAULT_SETTINGS, apiKey: settings.apiKey };
  saveSettings();
  applyContentProtection();
  applyLoginItem(); // reset means "stop starting itself" too — the login item lives outside settings.json
  registerShortcuts(); // custom keys were wiped — rebind the defaults so old combos don't linger
  applySnipHold();     // ...and the hold gesture goes back to its default arming set with them
  sendAll('settings:changed', uiSettings()); // every window: the Plan tab saves the key, the pill draws the PRO tag
  return uiSettings();
});

// ---------- rebindable shortcuts ----------
ipcMain.handle('shortcuts:get', () => shortcutList());
// Same list, synchronously, for the ONE caller that cannot await: the pill's resting hint. It is
// painted during the renderer's first pass, so an async getShortcuts() lands a frame or two later —
// long enough to see the placeholder swap (Windows flashed "Ctrl+Shift+S" before settling on the real
// "Alt+S"). Safe because loadSettings() runs before createMainWindow(), so the list is already final
// by the time any preload evaluates. Everything else keeps using the async channel.
ipcMain.on('shortcuts:get-sync', (e) => { e.returnValue = shortcutList(); });

// { id, accel } — accel '' resets that row to its default. Rejects a combo already bound to another
// action (conflict) or one Electron/the OS won't register (invalid), reverting so we never end up in a
// half-registered state. Returns { ok, error?, conflict?, list }.
ipcMain.handle('shortcuts:set', (_e, { id, accel } = {}) => {
  const action = SHORTCUT_ACTIONS.find((a) => a.id === id);
  if (!action) return { ok: false, error: 'unknown', list: shortcutList() };
  const next = String(accel || '').trim();
  const map = { ...(settings.shortcuts || {}) };
  if (!next) {
    delete map[id]; // reset this one to default
  } else {
    for (const a of SHORTCUT_ACTIONS) { // conflict vs every OTHER action's effective accel
      if (a.id === id) continue;
      if (((map[a.id] && map[a.id].trim()) || a.def) === next) {
        return { ok: false, error: 'conflict', conflict: a.label, list: shortcutList() };
      }
    }
    map[id] = next;
  }
  const prev = settings.shortcuts;
  settings.shortcuts = map;
  if (registerShortcuts().some((f) => f.id === id)) {
    settings.shortcuts = prev; // invalid / OS-taken → roll back and re-bind the good set
    registerShortcuts();
    return { ok: false, error: 'invalid', list: shortcutList() };
  }
  applySnipHold(); // the snip row may have just become (or stopped being) a hold gesture
  saveSettings();
  return { ok: true, list: shortcutList() };
});

ipcMain.handle('shortcuts:reset', () => {
  settings.shortcuts = {};
  registerShortcuts();
  applySnipHold();
  saveSettings();
  return { ok: true, list: shortcutList() };
});

// Called by the Settings page around a capture so the live combos don't fire while re-keying.
ipcMain.handle('shortcuts:suspend', () => { suspendShortcuts(); });
ipcMain.handle('shortcuts:resume', () => { resumeShortcuts(); });

// ---------- vocab store (shared between the pill and any future main window) ----------

// Insights tab reads the day tally straight out of memory — it's already tiny (one row per day).
ipcMain.handle('stats:get', () => stats);

ipcMain.handle('vocab:get', () => vocab);

// Bulk replace — used for the one-time localStorage→main migration and for the pill's batched
// "seen count" updates. Overwrites the whole list, so callers must pass the full current array.
ipcMain.handle('vocab:set', (_e, list) => {
  // Credit whatever this bulk write ADDS, by key diff. The legacy localStorage→main migration comes
  // through here, not vocab:add, and it can carry years of words that backfillMonths already ran too
  // early to see; a plain length check would miss it, since the same call is also used for same-size
  // rewrites (batched seen counts) that must credit nothing.
  const had = new Set(vocab.map((v) => vocabKey(vocabEntryWord(v))).filter(Boolean));
  vocab = Array.isArray(list) ? list.slice(0, MAX_VOCAB) : [];
  vocab.forEach((v) => {
    const key = vocabKey(vocabEntryWord(v));
    if (key && !had.has(key)) {
      const m = monthKey(Number(v && v.ts) || Date.now());
      stats.months[m] = (stats.months[m] || 0) + 1;
    }
  });
  saveStats();
  saveVocab();
  sendAll('vocab:changed', vocab);
  return vocab;
});

// Dedup, the ceiling rule and the month credit all live in addVocabEntry now — the point-at-a-word
// key collects without an IPC hop and must not get its own copy of any of that.
ipcMain.handle('vocab:add', (_e, entry) => {
  addVocabEntry(entry);
  return vocab;
});

ipcMain.handle('vocab:remove', (_e, word) => {
  const key = vocabKey(word);
  vocab = vocab.filter((v) => vocabKey(vocabEntryWord(v)) !== key);
  saveVocab();
  sendAll('vocab:changed', vocab);
  return vocab;
});

// Partial update for one entry (SRS scheduling, seen-count bumps) — merges patch into the matching
// entry by word key instead of replacing the whole list.
ipcMain.handle('vocab:update', (_e, { word, patch } = {}) => {
  const key = vocabKey(word);
  const idx = vocab.findIndex((v) => vocabKey(vocabEntryWord(v)) === key);
  if (idx !== -1) {
    vocab[idx] = { ...vocab[idx], ...(patch || {}) };
    saveVocab();
    sendAll('vocab:changed', vocab);
  }
  return vocab;
});

// Delete ONE history row (the − button on a History entry). Keyed by ts, the only per-entry id a
// payload carries; the renderer drops its own copy optimistically, so this just makes it stick and
// keeps the Learn window's History tab in sync.
ipcMain.handle('history:delete', (_e, ts) => {
  const before = history.length;
  history = history.filter(h => h.ts !== ts);
  if (history.length === before) return { ok: false };
  saveHistory();
  // Only the Learn window gets the re-push. The pill already removed the row from its own DOM, and a
  // history:load there triggers renderHistory(), which scrolls the log to the bottom — deleting a row
  // mid-list would yank the view away from what you were reading.
  if (learnWindow && !learnWindow.isDestroyed()) learnWindow.webContents.send('history:load', history);
  return { ok: true };
});

// Export the collected words as an Anki deck file. NOT a login.
//
// The risk jek named is real — the vocab lives in one vocab.json and has no way out of it, so a
// wiped machine takes months of collecting with it, and it is the only thing in this app that
// cannot be regenerated. But an account is the most expensive possible answer to it: a backend,
// auth, a database, sync conflicts, a privacy policy, uptime, and a per-user cost that never ends —
// on a product both advisors said should be sold ONCE, precisely because it has no per-user cost.
// Adding sync would make every sale a permanent liability.
//
// Anki is the cheap answer and the better one for this audience specifically. These are
// sentence-miners: they already run Anki, which already has accounts, free sync across devices,
// backups and a phone app. Exporting there gives them everything a login would have, for none of
// the cost, and makes Gloss a citizen of the ecosystem they live in rather than a walled copy of it.
//
// Tab-separated because that is what Anki's importer defaults to. Tabs and newlines are stripped
// from the fields rather than quoted: Anki treats a quote as literal text, so a quoted CSV would
// import with the quotes visible in every card.
ipcMain.handle('vocab:export-anki', async () => {
  if (!vocab.length) return { ok: false, reason: 'empty' };
  const { canceled, filePath } = await dialog.showSaveDialog({
    title: 'Export collected words',
    defaultPath: path.join(app.getPath('desktop'), `gloss-vocab-${new Date().toISOString().slice(0, 10)}.txt`),
    filters: [{ name: 'Anki import (tab-separated)', extensions: ['txt'] }],
  });
  if (canceled || !filePath) return { ok: false, reason: 'canceled' };

  const flat = (v) => String(v == null ? '' : v).replace(/[\t\r\n]+/g, ' ').trim();
  const rows = vocab.map((v) => [
    flat(vocabEntryWord(v)),
    flat(v.m || v.meaning),
    flat(v.src),                                   // the sentence it was met in — the reason to keep it
  ].join('\t'));
  // Anki reads these two lines as import settings, so the file carries its own field mapping and
  // nobody has to remember that column three is the sentence.
  const head = ['#separator:tab', '#columns:Word\tMeaning\tSentence'];

  try {
    fs.writeFileSync(filePath, head.concat(rows).join('\n') + '\n', 'utf8');
  } catch (err) {
    console.error('vocab export failed:', err);
    return { ok: false, reason: 'write' };
  }
  return { ok: true, count: rows.length, filePath };
});

ipcMain.handle('history:export', async () => {
  if (history.length === 0) return { ok: false, reason: 'empty' };
  const { canceled, filePath } = await dialog.showSaveDialog({
    title: 'Export translations',
    defaultPath: path.join(app.getPath('desktop'), `gloss-${Date.now()}.csv`),
    filters: [{ name: 'CSV', extensions: ['csv'] }],
  });
  if (canceled || !filePath) return { ok: false, reason: 'canceled' };

  const esc = (v) => `"${String(v).replace(/"/g, '""')}"`;
  const rows = [
    'time,english,thai',
    ...history
      .slice()
      .reverse()
      .map((h) => [new Date(h.ts).toISOString(), h.en.replace(/\n/g, ' '), h.th].map(esc).join(',')),
  ].join('\n');

  try {
    fs.writeFileSync(filePath, '﻿' + rows, 'utf8'); // BOM so Excel reads Thai
  } catch (err) {
    // No permission / disk full / network drive gone — tell the pill instead of failing silently.
    console.error('CSV export failed:', err);
    return { ok: false, reason: 'write' };
  }
  return { ok: true, filePath };
});


// ---------- lifecycle ----------

protocol.registerSchemesAsPrivileged([{
  scheme: 'gt',
  privileges: { standard: true, secure: true, supportFetchAPI: true, corsEnabled: true },
}]);

// One copy only. A second launch (desktop icon + start menu shortcut both exist) would come up with
// every global shortcut dead — the first copy already owns them — and, worse, both copies write
// history.json / vocab.json / settings.json with whole-file writeFileSync, so whichever quits last
// silently wipes the other's saved vocabulary.
const gotInstanceLock = app.requestSingleInstanceLock();
if (!gotInstanceLock) {
  app.quit();
} else {
  app.on('second-instance', () => {
    // Someone tried to launch it again — surface the copy that's already running instead.
    if (mainWindow && !mainWindow.isDestroyed()) {
      if (mainWindow.isMinimized()) mainWindow.restore();
      mainWindow.show();
    }
  });
}

// ---------- Tray: the way back when the overlay cannot answer ------------------------------------
// This app is one small always-on-top capsule and nothing else — no window in the taskbar, no menu
// bar item. Every way out of a stuck state was therefore a keyboard shortcut you had to already
// know, and the states are reachable by accident: lock makes the pill click-through, and Tucked
// slides it off the edge. (That pair is fixed in the renderer — a locked pill no longer tucks — but
// "the fix works" and "there is a way back if it doesn't" are two different promises, and only the
// second one survives the next bug.) The tray is the second one.
//
// Deliberately three items. A tray menu that mirrors the whole app is another surface to keep in
// step; this one exists to answer "I cannot get to it" and then get out of the way.
let tray = null;
let trayLocked = false; // renderer-owned state, mirrored here only so the menu can show a tick

function trayMenu() {
  return Menu.buildFromTemplate([
    // Un-hides, un-tucks and unlocks in one — whatever the pill is doing, this ends it. The renderer
    // owns all three, so it is one message rather than three round trips.
    { label: 'Show Gloss', click: () => { showMain(); sendMain('ui:reveal'); } },
    { label: 'Lock overlay', type: 'checkbox', checked: trayLocked, click: () => sendMain('lock:toggle') },
    { type: 'separator' },
    { label: 'Quit Gloss', click: () => app.quit() },
  ]);
}

function refreshTray() {
  if (tray && !tray.isDestroyed()) tray.setContextMenu(trayMenu());
}

// ---------- macOS application menu ---------------------------------------------------------------
// Until now this app never called setApplicationMenu, which does not mean "no menu" on macOS — it
// means ELECTRON'S menu. Its Help item is "Learn More" pointing at electronjs.org, its About box
// names Electron, and it has no ⌘, at all. That is the first thing a Mac user sees in the menu bar
// of an app they just downloaded, and it says the app was built for somewhere else.
//
// The Edit roles are not decoration either: on macOS, ⌘C/⌘V/⌘A inside a text field are delivered BY
// the menu. Ship a menu without them (or setApplicationMenu(null), the tempting "we have no menu"
// answer) and the Type bar silently stops taking paste — the one field the whole app is typed into.
// Windows gets null instead, and correctly: Chromium handles Ctrl+C/V there without a menu, and the
// only framed window we have would otherwise wear a menu bar this app has no use for.
function buildAppMenu() {
  if (process.platform !== 'darwin') { Menu.setApplicationMenu(null); return; }
  app.setAboutPanelOptions({
    applicationName: 'Gloss',
    applicationVersion: app.getVersion(),
    copyright: 'Reads any game and translates it in real time.',
  });
  const openSettings = () => { showMain(); sendMain('ui:reveal'); sendMain('ui:settings'); };
  Menu.setApplicationMenu(Menu.buildFromTemplate([
    {
      label: 'Gloss',
      submenu: [
        { role: 'about', label: 'About Gloss' },
        { type: 'separator' },
        // ⌘, is where every Mac user looks for settings before they look anywhere else. The overlay
        // has had a Settings panel the whole time and no key that opens it from outside the pill.
        { label: 'Settings…', accelerator: 'Command+,', click: openSettings },
        { label: 'Show Gloss', click: () => { showMain(); sendMain('ui:reveal'); } },
        { type: 'separator' },
        { role: 'services' },
        { type: 'separator' },
        { role: 'hide', label: 'Hide Gloss' },
        { role: 'hideOthers' },
        { role: 'unhide' },
        { type: 'separator' },
        { role: 'quit', label: 'Quit Gloss' },
      ],
    },
    { label: 'Edit', submenu: [
      { role: 'undo' }, { role: 'redo' }, { type: 'separator' },
      { role: 'cut' }, { role: 'copy' }, { role: 'paste' },
      { role: 'pasteAndMatchStyle' }, { role: 'selectAll' },
    ] },
    { label: 'Window', submenu: [
      { role: 'minimize' }, { role: 'zoom' }, { type: 'separator' }, { role: 'front' },
    ] },
    { role: 'help', submenu: [
      // GLOSS_SITE, not a second copy of the address — the /report form and the buy link already
      // read it, and a Help item that outlives a domain move is worth the one variable.
      { label: 'Gloss Help', click: () => shell.openExternal(GLOSS_SITE) },
    ] },
  ]));
}

function createTray() {
  if (tray) return;
  try {
    // build/tray.png is GENERATED — scripts/make-tray-icon.js writes it and its @2x next to it.
    // It did not exist until 2026-09-01, so every build so far handed Tray an empty image and the
    // menu bar item drew nothing: the one guaranteed way back from a locked or tucked pill was an
    // invisible slot. Never let that fail silently again — see the throw below.
    //
    // No resize on macOS. createFromPath picks up tray@2x.png on its own, and resize() collapses
    // that pair into one 16px bitmap, which is exactly how a menu bar icon ends up soft on a Retina
    // display. Windows has no @2x convention and DOES crop an oversized source rather than scale it,
    // so the resize stays there — same asset, the sizing each platform actually wants.
    const img = nativeImage.createFromPath(TRAY_ICON);
    if (img.isEmpty()) throw new Error(`tray icon missing or unreadable: ${TRAY_ICON} (run: node scripts/make-tray-icon.js)`);
    // macOS draws a template image itself: it inverts the shape for a dark menu bar, dims it while
    // the app is hidden and highlights it on click. A coloured bitmap gets none of that and is the
    // single clearest tell that a menu bar item was not written for this platform.
    if (process.platform === 'darwin') img.setTemplateImage(true);
    tray = new Tray(process.platform === 'darwin' ? img : img.resize({ width: 16, height: 16 }));
    tray.setToolTip('Gloss');
    tray.setContextMenu(trayMenu());
    // Windows convention: a left click on the tray icon is "bring it back", which is the whole reason
    // someone is looking at this icon in the first place. NOT on macOS — there a click on a menu bar
    // item opens its menu, which setContextMenu already does; registering this as well would be a
    // handler that can never fire, sitting there looking like behaviour someone can rely on.
    if (process.platform !== 'darwin') tray.on('click', () => { showMain(); sendMain('ui:reveal'); });
  } catch (err) {
    console.error('tray unavailable:', err && err.message); // non-fatal — the app still works
    tray = null;
  }
}

// The renderer tells us when lock flips (it owns `locked`), so the tick in the menu is the real state
// rather than a count of how many times this menu was clicked.
ipcMain.on('ui:lock-state', (_e, on) => { trayLocked = !!on; refreshTray(); });

function showMain() {
  if (!mainWindow || mainWindow.isDestroyed()) return;
  if (!mainWindow.isVisible()) mainWindow.showInactive();
}

// NOT here: `disable-features=CalculateNativeWinOcclusion`. Windows occlusion discarding the
// overlay's compositor tiles was the obvious suspect for the 152ms first-switch frame, and it is
// wrong — measured 2026-08-10, the frame stayed at 152.0ms with the switch on, against 3-5ms on
// every later switch. It costs idle GPU for nothing here; don't add it back without a number.

app.whenReady().then(() => {
  if (!gotInstanceLock) return; // losing copy: quitting, don't build windows or grab shortcuts
  // Show the app icon on the dock during dev too (packaged builds use build/icon.icns).
  if (process.platform === 'darwin' && app.dock) {
    try {
      const dockIcon = nativeImage.createFromPath(path.join(__dirname, 'build', 'icon.png'));
      if (!dockIcon.isEmpty()) app.dock.setIcon(dockIcon);
    } catch { /* non-fatal */ }
  }
  // Windows: without an explicit AppUserModelID the taskbar files us under Electron's own identity —
  // Electron's logo, Electron's grouping — no matter what icon the windows carry. Must be set before
  // the first window exists.
  if (IS_WIN) { try { app.setAppUserModelId('com.gametranslator.app'); } catch { /* non-fatal */ } }
  loadSettings();
  loadHistory();
  loadStats();
  backfillStats();
  loadVocab();
  backfillMonths(); // after loadVocab — it reads the collection it is seeding from
  applyLoginItem(); // re-assert on every boot: the OS entry can drift from the setting (app moved, profile restored)
  registerGtProtocol();
  createMainWindow();
  buildAppMenu(); // before the first window is focused, so the bar is never Electron's for a frame
  createTray(); // after the window exists — Show Gloss has something to show
  createOcrWindow(); // warm the OCR worker up front — first snip shouldn't wait for it
  ensureSnipWindows(); // pre-build the snip overlays so the first snip is instant
  // Hold-drag-to-translate, now on both platforms via the same extern-session engine. macOS uses a
  // Swift CGEventTap (mousehook) that also carries the middle-button trigger; Windows uses a
  // WH_KEYBOARD_LL hook for the ⌃⌥ edges plus a cursor poll (winkeyhook.js).
  //
  // The earlier "Windows sticks to ⌘⇧S only" decision was about uiohook-napi, which reads the whole
  // system's mouse AND keyboard and cost real input lag. This hook is keyboard-only, never swallows,
  // and exits on the first compare for any non-modifier key — see winkeyhook.js.
  startMouseHook();     // no-op off darwin
  startWinComboHook();  // no-op off win32

  // Replay the saved history into the panel once the window is up.
  mainWindow.webContents.once('did-finish-load', () => {
    if (history.length) sendMain('history:load', history);
    // Say it on arrival, not on the first failure. Without Screen Recording the app cannot do the
    // one thing it is for, and every path that needs it — snip, live, glass — has to decline
    // silently, so a new user's first drag simply does nothing and the pill stays a dark slab.
    // checkScreenPermission raises the banner (with its Open Settings button) as a side effect.
    //
    // The getSources call before it is what makes macOS put up its OWN prompt, naming Gloss, on a
    // Mac that has never been asked. That prompt is the only one-click route into the right
    // Settings pane; without it the user has to find the pane and drag the app in by hand. It
    // costs a full-screen capture, so it is only paid on the launches where the answer is no.
    if (!checkScreenPermission()) {
      desktopCapturer.getSources({ types: ['screen'], thumbnailSize: { width: 1, height: 1 } })
        .catch(() => {}); // already denied → macOS stays silent, and the banner is the fallback
    }
  });

  const failed = registerShortcuts();
  if (failed.length > 0) {
    mainWindow.webContents.once('did-finish-load', () => {
      sendMain('translation:error', 'Hotkey in use by another app: ' + failed.map((f) => f.accel).join(', '));
    });
  }

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createMainWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

app.on('will-quit', () => {
  globalShortcut.unregisterAll();
  // A live Tray keeps the process alive on Windows — the icon would sit there after the app is gone.
  if (tray && !tray.isDestroyed()) tray.destroy();
  tray = null;
});

app.on('before-quit', () => {
  // Lets learnWindow's 'close' handler tell a real quit apart from the window's own close button —
  // without this, hide-not-destroy would swallow preventDefault() on ⌘Q/Quit too and hang the quit.
  app.isQuitting = true;
  if (ocrWindow && !ocrWindow.isDestroyed()) ocrWindow.destroy();
  ocrWindow = null;
  for (const w of snipWindows) if (!w.isDestroyed()) w.destroy();
  snipWindows = [];
  stopVisionServer(); // don't leave the persistent visionocr process running as a zombie
  stopWinOcrServer(); // ditto for the PowerShell OCR server (Windows)
  stopMouseHook(); // ditto for the ⌃⌥ hook process (macOS)
  stopComboPoll();
  shutdownComboHook(); // unhook + unregister the ⌃⌥ keyboard callback (Windows)
  shutdownMouseButtons(); // ...and the side-button hook, if any row was bound to one (Windows)
  shutdownSnipHook(); // fully tear the Windows snip hook down (blocking — fine at quit, see winhook.js)
});

// ---- Debug-only handle for the CDP harness -----------------------------------------------------
// GT_DEBUG only. A CommonJS module's own top-level names are not reachable from the main process's
// inspector — Runtime.evaluate sees the Node global, not this module — so a harness driving this
// process can call `require('electron')` and nothing of ours. Every check written against the real
// functions (rather than against the UI that happens to call them) needs one door, and this is it.
// Never present in a normal run: DEBUG is GT_DEBUG, which the shipped app is never started with.
if (DEBUG) {
  global.__gt = { keepLastSnip, translateOnce, hoverDwellTick, localWordAnswer, wordStudyDetail,
    wordCacheGet, offlineWordAnswer, hoverVocabEntry, isOneWord,
    // Read/write the card the keep gesture acts on, so its rules (the time window, the single-word
    // test, one-save-per-tap) can be checked without driving a real ⌃⌥ drag across the user's screen.
    snipCard: (v) => (v === undefined ? lastSnipCard : (lastSnipCard = v)),
    keepArmedCard, armedAt: (v) => (v === undefined ? keepArmedAt : (keepArmedAt = v)),
    handleMouseHookLine, firedAt: (v) => (v === undefined ? lastSnipFiredAt : (lastSnipFiredAt = v)),
    doSnipStart,
    style: () => effectiveSnipStyle() };
}
